(function(g){g.__QURAN_DATA=g.__QURAN_DATA||{};g.__QURAN_DATA["tamil-049"]={"sura":49,"name_ar":"الحجرات","name_en":"Al-Hujurat","verses":18,"source":"https://www.tamililquran.com/tafsiribnkathir.php","count":18,"missing":[],"data":{"1":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=49&ayah=3\" class=\"link\">49:3</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 49:3 ஐ பார்க்கவும்"},"2":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=49&ayah=3\" class=\"link\">49:3</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 49:3 ஐ பார்க்கவும்"},"3":{"html":"<strong>இது மதீனாவில் அருளப்பட்டது</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بِسْمِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمِ</span><br />\r\n<br />\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.<br />\r\n<br />\r\n<strong>அல்லாஹ்வுக்கும் அவனுடைய தூதருக்கும் முன்னால் சுயமாக முடிவெடுப்பது தடைசெய்யப்பட்டுள்ளது; நபியவர்களுக்கு மரியாதை செலுத்துமாறு கட்டளையிடுதல்</strong><br />\r\n<br />\r\nஇந்த வசனங்களில், கண்ணியமிக்க அல்லாஹ் தனது நம்பிக்கையுள்ள அடியார்களுக்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் அவர்கள் கடைபிடிக்க வேண்டிய நற்பண்புகளான மரியாதை, கண்ணியம் மற்றும் கண்ணியப்படுத்துதல் ஆகியவற்றைக் கற்றுக்கொடுக்கிறான். கண்ணியமும் மேன்மையும் மிக்க அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يأَيُّهَا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تُقَدِّمُواْ</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">يَدَىِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَرَسُولِهِ</span><br />\r\n<br />\r\n(நம்பிக்கையாளர்களே! அல்லாஹ்வுக்கும் அவனுடைய தூதருக்கும் முன்னால் நீங்கள் முந்தாதீர்கள்,) அதாவது அவருக்கு முன்னால் முடிவெடுப்பதில் அவசரப்படாதீர்கள்; மாறாக, அனைத்து விவகாரங்களிலும் அவரையே பின்பற்றுங்கள். இப்னு அப்பாஸ் (ரழி) அவர்கள் இதைப் பற்றிக் கூறியதாக அலீ பின் அபீ தல்ஹா (ரழி) அவர்கள் அறிவிக்கிறார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تُقَدِّمُواْ</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">يَدَىِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَرَسُولِهِ</span><br />\r\n<br />\r\n(அல்லாஹ்வுக்கும் அவனுடைய தூதருக்கும் முன்னால் நீங்கள் முந்தாதீர்கள்,) \"குர்ஆன் மற்றும் சுன்னாவிற்கு முரணான எதையும் சொல்லாதீர்கள்.\" கத்தாதா (ரஹ்) அவர்கள் கூறினார்கள்: \"சிலர், 'இன்ன காரியத்தைப் பற்றி வஹீ (இறைச்செய்தி) அருளப்பட வேண்டும்', 'இன்ன காரியங்கள் அனுமதிக்கப்பட வேண்டும்' என்று கூறி வந்ததாக எங்களுக்குக் கூறப்பட்டது. இத்தகைய போக்கை அல்லாஹ் வெறுத்தான்.\" அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاتَّقُواْ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span><br />\r\n<br />\r\n(மேலும் அல்லாஹ்வுக்கு அஞ்சிக் கொள்ளுங்கள்.) அதாவது, 'அவன் உங்களுக்குக் கட்டளையிட்டவற்றில் (அவனுக்கு அஞ்சுங்கள்)'.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">سَمِيعٌ</span><br />\r\n<br />\r\n(நிச்சயமாக அல்லாஹ் செவியேற்பவன்,) 'உங்கள் பேச்சுகளை',<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">عَلِيمٌ</span><br />\r\n<br />\r\n(நன்கறிந்தவன்.) 'உங்கள் எண்ணங்களை'. அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يأَيُّهَا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَرْفَعُواْ</span> <span class=\"quran-arabic-font text-success\">أَصْوَاتَكُمْ</span> <span class=\"quran-arabic-font text-success\">فَوْقَ</span> <span class=\"quran-arabic-font text-success\">صَوْتِ</span> <span class=\"quran-arabic-font text-success\">النَّبِىِّ</span><br />\r\n<br />\r\n(நம்பிக்கையாளர்களே! நபியின் குரலுக்கு மேலாக உங்கள் குரல்களை உயர்த்தாதீர்கள்,) இதில் மற்றொரு நற்பண்பு அடங்கியுள்ளது. நம்பிக்கையாளர்கள் நபியவர்களின் (ஸல்) குரலுக்கு மேலாகத் தங்கள் குரல்களை உயர்த்தக் கூடாது என்று அல்லாஹ் அவர்களுக்குக் கற்றுக்கொடுக்கிறான். இந்த வசனம் அபூபக்கர் (ரழி) மற்றும் உமர் (ரழி) ஆகிய இருவரைப் பற்றி அருளப்பட்டதாகக் கூறப்படுகிறது. இப்னு அபீ முலைக்கா (ரஹ்) அவர்கள் கூறியதாக புகாரி (ரஹ்) பதிவு செய்துள்ளார்கள்: \"இரு நற்பண்புள்ளவர்களான அபூபக்கர் (ரழி) மற்றும் உமர் (ரழி) ஆகிய இருவரும், பனூ தமீம் கோத்திரத்தின் தூதுக்குழுவை நபியவர்கள் (ஸல்) சந்தித்துக் கொண்டிருந்தபோது அவர்களுக்கு முன்னால் தங்கள் குரல்களை உயர்த்தியதால் அழிவை நெருங்கிவிட்டனர். அவர்களில் ஒருவர் பனூ முஜாஷிஃ கிளையைச் சேர்ந்த அல்-அக்ராஃ பின் ஹாபிஸைப் (ரழி) பரிந்துரைக்க, மற்றவர் வேறொருவரைப் பரிந்துரைத்தார். (அறிவிப்பாளர் நாஃபிஃ (ரஹ்) கூறுகிறார்: 'அவருடைய பெயர் எனக்கு நினைவில்லை'). அபூபக்கர் (ரழி) அவர்கள் உமர் (ரழி) அவர்களிடம், 'நீங்கள் எனக்கு மாறுபடவே விரும்புகிறீர்கள்' என்று கூறினார்கள். அதற்கு உமர் (ரழி) அவர்கள், 'நான் உங்களுக்கு மாறுபட விரும்பவில்லை' என்று கூறினார்கள். அப்போது அவர்கள் இருவரின் குரல்களும் உயர்ந்தன. அதன் காரணமாகவே அல்லாஹ் இந்த வசனத்தை அருளினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يأَيُّهَا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَرْفَعُواْ</span> <span class=\"quran-arabic-font text-success\">أَصْوَاتَكُمْ</span> <span class=\"quran-arabic-font text-success\">فَوْقَ</span> <span class=\"quran-arabic-font text-success\">صَوْتِ</span> <span class=\"quran-arabic-font text-success\">النَّبِىِّ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَجْهَرُواْ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">بِالْقَوْلِ</span> <span class=\"quran-arabic-font text-success\">كَجَهْرِ</span> <span class=\"quran-arabic-font text-success\">بَعْضِكُمْ</span> <span class=\"quran-arabic-font text-success\">لِبَعْضٍ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تَحْبَطَ</span> <span class=\"quran-arabic-font text-success\">أَعْمَـلُكُمْ</span> <span class=\"quran-arabic-font text-success\">وَأَنتُمْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَشْعُرُونَ</span><br />\r\n<br />\r\n(நம்பிக்கையாளர்களே! நபியின் குரலுக்கு மேலாக உங்கள் குரல்களை உயர்த்தாதீர்கள். மேலும், நீங்கள் ஒருவருக்கொருவர் உரத்த குரலில் பேசுவது போல் அவரிடம் பேசாதீர்கள்; (அவ்வாறு செய்தால்) நீங்கள் அறியாத நிலையிலேயே உங்கள் நற்செயல்கள் அழிந்துவிடும்.)\" அப்துல்லாஹ் பின் அஸ்-ஸுபைர் (ரழி) அவர்கள் கூறினார்கள்: \"இதற்குப் பிறகு, உமர் (ரழி) அவர்களின் குரல் மிகவும் தாழ்வாக இருந்ததால், அவர் சொல்வதைப் புரிந்து கொள்வதற்காக அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அவரை மீண்டும் சொல்லுமாறு கேட்க வேண்டியிருந்தது.\" அப்துல்லாஹ் பின் அஸ்-ஸுபைர் (ரழி) அவர்கள் தனது தந்தை அபூபக்கர் (ரழி) அவர்களைப் பற்றி இவ்வாறு குறிப்பிடவில்லை. முஸ்லிம் இந்த ஹதீஸைப் பதிவு செய்யவில்லை. புகாரி (ரஹ்) பதிவு செய்துள்ள மற்றொரு அறிவிப்பில், பனூ தமீம் கோத்திரத்தைச் சேர்ந்த ஒரு தூதுக்குழு நபியவர்களிடம் (ஸல்) வந்தபோது, அபூபக்கர் (ரழி) அவர்கள் அல்-கஃகாஃ பின் மஃபத் (ரழி) அவர்களைத் தலைவராக நியமிக்கப் பரிந்துரைத்ததாகவும், உமர் (ரழி) அவர்கள் அல்-அக்ராஃ பின் ஹாபிஸைப் (ரழி) பரிந்துரைத்ததாகவும் உள்ளது. முஸ்லிம் இந்த அறிவிப்பைப் பதிவு செய்யவில்லை.<br />\r\n<br />\r\nஅனஸ் பின் மாலிக் (ரழி) அவர்கள் கூறியதாக புகாரி (ரஹ்) பதிவு செய்துள்ளார்கள்: \"நபியவர்கள் (ஸல்) ஸாபித் பின் கைஸ் (ரழி) அவர்களைக் காணவில்லை. அப்போது ஒரு மனிதர், 'அல்லாஹ்வின் தூதரே! நான் அவரைப் பற்றிய செய்தியை அறிந்து வருகிறேன்' என்றார். அந்த மனிதர் ஸாபித் (ரழி) அவர்களிடம் சென்றபோது, அவர் தனது வீட்டில் தலைகுனிந்து அமர்ந்திருப்பதைக் கண்டார். 'உமக்கு என்ன நேர்ந்தது?' என்று அவரிடம் கேட்டார். அதற்கு ஸாபித் (ரழி) அவர்கள், 'மிகவும் மோசமான விஷயம்!' என்றார்கள். தான் நபியவர்களின் (ஸல்) குரலுக்கு மேலாகத் தனது குரலை உயர்த்தி வந்ததாகவும், அதனால் தனது நற்செயல்கள் அழிந்து தான் நரகவாசிகளில் ஒருவனாகி விடுவோமோ என்று அஞ்சுவதாகவும் அவர் கூறினார். அந்த மனிதர் நபியவர்களிடம் (ஸல்) திரும்பி வந்து ஸாபித் (ரழி) அவர்களின் கூற்றைத் தெரிவித்தார். பின்னர் நபியவர்கள் (ஸல்) வழங்கிய ஒரு நற்செய்தியுடன் அவர் ஸாபித் (ரழி) அவர்களிடம் திரும்பினார். நபியவர்கள் (ஸல்) கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">اذْهَبْ</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِ</span> <span class=\"quran-arabic-font text-success\">فَقُلْ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span>: <span class=\"quran-arabic-font text-success\">إِنَّكَ</span> <span class=\"quran-arabic-font text-success\">لَسْتَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَهْلِ</span> <span class=\"quran-arabic-font text-success\">النَّارِ،</span> <span class=\"quran-arabic-font text-success\">وَلَكِنَّكَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَهْلِ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّة</span>»<br />\r\n<br />\r\n(அவரிடம் சென்று இந்தச் செய்தியைச் சொல்லுங்கள்; நிச்சயமாக நீங்கள் நரகவாசி அல்ல, மாறாக நீங்கள் சொர்க்கவாசிகளில் ஒருவர்.)\" புகாரி (ரஹ்) இந்த ஹதீஸை இதே வார்த்தைகளில் பதிவு செய்துள்ளார்கள்.<br />\r\n<br />\r\nஇமாம் அஹ்மத் (ரஹ்) அவர்கள் அனஸ் பின் மாலிக் (ரழி) அவர்கள் வழியாகப் பின்வருமாறு பதிவு செய்துள்ளார்கள்: \"இந்த வசனம் அருளப்பட்டபோது,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يأَيُّهَا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَرْفَعُواْ</span> <span class=\"quran-arabic-font text-success\">أَصْوَاتَكُمْ</span> <span class=\"quran-arabic-font text-success\">فَوْقَ</span> <span class=\"quran-arabic-font text-success\">صَوْتِ</span> <span class=\"quran-arabic-font text-success\">النَّبِىِّ</span><br />\r\n<br />\r\n(நம்பிக்கையாளர்களே! நபியின் குரலுக்கு மேலாக உங்கள் குரல்களை உயர்த்தாதீர்கள்), என்பது முதல்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَنتُمْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَشْعُرُونَ</span><br />\r\n<br />\r\n(நீங்கள் அறியாத நிலையில்), என்பது வரையிலான இந்த வசனம் அருளப்பட்டபோது, இயல்பிலேயே உரத்த குரல் கொண்ட ஸாபித் பின் கைஸ் பின் ஷம்மாஸ் (ரழி) அவர்கள், 'நான்தான் அல்லாஹ்வின் தூதருடைய (ஸல்) குரலுக்கு மேலாக என் குரலை உயர்த்தியவன். நான் நரகவாசிகளில் ஒருவன். என் நற்செயல்கள் வீணாகிவிட்டன' என்று கூறினார்கள். அவர்கள் மிகுந்த மனவேதனையுடன் தன் வீட்டிலேயே தங்கியிருந்தார்கள். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அவர் வராததைக் கவனித்தார்கள். எனவே சில மனிதர்கள் ஸாபித் (ரழி) அவர்களிடம் சென்று, 'நபியவர்கள் (ஸல்) உங்களைக் காணவில்லையே, என்ன விஷயம்?' என்று கேட்டார்கள். அதற்கு ஸாபித் (ரழி) அவர்கள், 'நான் நபியவர்களின் (ஸல்) குரலுக்கு மேலாக என் குரலை உயர்த்தி, அவர்களுக்கு முன்னால் சப்தமாகப் பேசக் கூடியவனாக இருந்தேன். என் நற்செயல்கள் வீணாகிவிட்டன, நான் நரகவாசிகளில் ஒருவன்' என்று கூறினார்கள். அவர்கள் நபியவர்களிடம் (ஸல்) சென்று ஸாபித் (ரழி) அவர்கள் கூறியதைத் தெரிவித்தார்கள். அப்போது நபியவர்கள் (ஸல்) கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَا،</span> <span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَهْلِ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّة</span>»<br />\r\n<br />\r\n(இல்லை, மாறாக அவர் சொர்க்கவாசிகளில் ஒருவர்.)\" அனஸ் (ரழி) அவர்கள் மேலும் கூறினார்கள்: \"ஸாபித் (ரழி) அவர்கள் சொர்க்கவாசி என்பதை அறிந்த நிலையில் அவர் எங்களுக்கு மத்தியில் நடமாடுவதை நாங்கள் கண்டு வந்தோம். யமாமா போரின்போது எமது படைகள் பின்வாங்கிய போது, ஸாபித் பின் கைஸ் பின் ஷம்மாஸ் (ரழி) அவர்கள் 'ஹனூத்' (வாசனைத் திரவியம்) பூசி, கஃபன் துணிகளை அணிந்தவர்களாக வந்து, 'யா அல்லாஹ்! இவர்கள் (இணைவைப்பாளர்கள்) செய்வதை விட்டும் நான் விலகிக் கொள்கிறேன். மேலும் இவர்கள் (முஸ்லிம்கள்) செய்வதற்காக உன்னிடம் மன்னிப்புக் கோருகிறேன்' என்று கூறிவிட்டு, வீர மரணம் எய்தும் வரை போரிட்டார்கள். அல்லாஹ் அவர்களைப் பொருந்திக் கொள்வானாக.\"<br />\r\n<br />\r\nஅதன் பிறகு அல்லாஹ், ஒருவரையொருவர் புண்படுத்தும் வகையில் சப்தமாகப் பேசுவது போல் நபியவர்களிடம் (ஸல்) உரத்த குரலில் பேசுவதைத் தடை செய்தான். அதற்குப் பதிலாக, அவரிடம் மரியாதை, கண்ணியம் மற்றும் அமைதியுடன் பேச வேண்டும் என்று கட்டளையிட்டான். இதனால்தான் கண்ணியமும் மேன்மையும் மிக்க அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَجْهَرُواْ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">بِالْقَوْلِ</span> <span class=\"quran-arabic-font text-success\">كَجَهْرِ</span> <span class=\"quran-arabic-font text-success\">بَعْضِكُمْ</span> <span class=\"quran-arabic-font text-success\">لِبَعْضٍ</span><br />\r\n<br />\r\n(நீங்கள் ஒருவருக்கொருவர் சப்தமாகப் பேசிக் கொள்வது போல் அவரிடம் சப்தமாகப் பேசாதீர்கள்,) அவன் மற்றொரு வசனத்தில் கூறியது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">تَجْعَلُواْ</span> <span class=\"quran-arabic-font text-success\">دُعَآءَ</span> <span class=\"quran-arabic-font text-success\">الرَّسُولِ</span> <span class=\"quran-arabic-font text-success\">بَيْنَكُمْ</span> <span class=\"quran-arabic-font text-success\">كَدُعَآءِ</span> <span class=\"quran-arabic-font text-success\">بَعْضِكُمْ</span> <span class=\"quran-arabic-font text-success\">بَعْضاً</span><br />\r\n<br />\r\n(உங்களுக்கிடையில் நீங்கள் ஒருவரையொருவர் அழைப்பது போல் (அல்லாஹ்வின்) தூதரை அழைக்காதீர்கள்.) (<a href=\"qurandisp.php?sura=24&ayah=63\" class=\"link\">24:63</a>)<br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்றான,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تَحْبَطَ</span> <span class=\"quran-arabic-font text-success\">أَعْمَـلُكُمْ</span> <span class=\"quran-arabic-font text-success\">وَأَنتُمْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَشْعُرُونَ</span><br />\r\n<br />\r\n(நீங்கள் உணராத நிலையிலேயே உங்கள் நற்செயல்கள் அழிந்துவிடும்.) என்பதன் பொருள்: நபியவர்கள் (ஸல்) உங்கள் மீது கோபப்படாமல் இருப்பதற்காக, அவரிடம் குரலை உயர்த்தக் கூடாது என நாம் உங்களுக்குக் கட்டளையிட்டோம். ஏனெனில் அவர் கோபப்பட்டால் அல்லாஹ்வும் கோபப்படுவான். நபியவர்களின் (ஸல்) கோபத்திற்கு ஆளானவரின் நற்செயல்கள் அவர் அறியாமலேயே வீணாகிவிடும். ஸஹீஹ் நூலில் ஒரு ஹதீஸ் இவ்வாறு இடம் பெற்றுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الرَّجُلَ</span> <span class=\"quran-arabic-font text-success\">لَيَتَكَلَّمُ</span> <span class=\"quran-arabic-font text-success\">بِالْكَلِمَةِ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">رِضْوَانِ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">تَعَالَى</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يُلْقِي</span> <span class=\"quran-arabic-font text-success\">لَهَا</span> <span class=\"quran-arabic-font text-success\">بَالًا،</span> <span class=\"quran-arabic-font text-success\">يُكْتَبُ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">بِهَا</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةُ،</span> <span class=\"quran-arabic-font text-success\">وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">الرَّجُلَ</span> <span class=\"quran-arabic-font text-success\">لَيَتَكَلَّمُ</span> <span class=\"quran-arabic-font text-success\">بِالْكَلِمَةِ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">سَخَطِ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">تَعَالَى</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يُلْقِي</span> <span class=\"quran-arabic-font text-success\">لَهَا</span> <span class=\"quran-arabic-font text-success\">بَالًا،</span> <span class=\"quran-arabic-font text-success\">يَهْوِي</span> <span class=\"quran-arabic-font text-success\">بِهَا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">أَبْعَدَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">السَّمَاءِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْض</span>»<br />\r\n<br />\r\n(நிச்சயமாக, ஒரு மனிதன் அதன் முக்கியத்துவத்தை உணராமலேயே மேலான அல்லாஹ்வின் திருப்திக்குரிய ஒரு வார்த்தையைப் பேசுவான், அதன் காரணமாக அவனுக்குச் சொர்க்கம் விதிக்கப்படுகிறது. நிச்சயமாக ஒரு மனிதன் கவனக்குறைவாக மேலான அல்லாஹ்வின் கோபத்திற்குரிய ஒரு வார்த்தையைப் பேசுவான், அதன் காரணமாக அவன் வானத்திற்கும் பூமிக்கும் இடையிலான தூரத்தை விட வெகு தூரத்தில் நரகத்தில் வீசப்படுவான்.)<br />\r\n<br />\r\nஅதன் பிறகு அல்லாஹ், அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுக்கு முன்னால் குரலைத் தாழ்த்துமாறு கட்டளையிடுகிறான். மேலும் இந்தச் சிறந்த நற்பண்பைப் பேணுமாறு ஊக்குவித்து வழிநடத்துகிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَغُضُّونَ</span> <span class=\"quran-arabic-font text-success\">أَصْوَاتَهُمْ</span> <span class=\"quran-arabic-font text-success\">عِندَ</span> <span class=\"quran-arabic-font text-success\">رَسُولِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">أُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">امْتَحَنَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">قُلُوبَهُمْ</span> <span class=\"quran-arabic-font text-success\">لِلتَّقْوَى</span><br />\r\n<br />\r\n(நிச்சயமாக, அல்லாஹ்வின் தூதருடைய (ஸல்) முன்னிலையில் எவர்கள் தங்கள் குரல்களைத் தாழ்த்திக் கொள்கிறார்களோ, அத்தகையோரின் இதயங்களை அல்லாஹ் தக்வாவிற்காக (பயபக்திக்காக) சோதித்துள்ளான்.) அதாவது, எவர்களின் இதயங்களை அல்லாஹ் தூய்மைப்படுத்தி, தக்வாவின் இருப்பிடமாக ஆக்கியுள்ளானோ அத்தகையோர் ஆவர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَهُم</span> <span class=\"quran-arabic-font text-success\">مَّغْفِرَةٌ</span> <span class=\"quran-arabic-font text-success\">وَأَجْرٌ</span> <span class=\"quran-arabic-font text-success\">عَظِيمٌ</span><br />\r\n<br />\r\n(அவர்களுக்கு மன்னிப்பும் மகத்தான நற்கூலியும் உண்டு.)<br />\r\n<br />\r\nஇமாம் அஹ்மத் (ரஹ்) அவர்கள் 'கிதாபுஸ் ஸுஹ்த்' நூலில் முஜாஹித் (ரஹ்) அவர்கள் கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"ஒருவர் உமர் (ரழி) அவர்களுக்குக் கடிதம் எழுதினார்: 'நம்பிக்கையாளர்களின் தலைவரே! பாவம் செய்ய வேண்டும் என்ற ஆசையே ஏற்படாமல் பாவம் செய்யாத மனிதர் சிறந்தவரா அல்லது பாவம் செய்ய ஆசை இருந்தும் (அல்லாஹ்வை) அஞ்சிக் கொண்டு அதைக் கைவிடுகிறவர் சிறந்தவரா?' உமர் (ரழி) அவர்கள் பதிலளித்தார்கள்: 'யார் பாவம் செய்ய ஆசை இருந்தும் அதைச் செய்யாமல் தன்னைத் தடுத்துக் கொள்கிறாரோ அவரே சிறந்தவர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">امْتَحَنَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">قُلُوبَهُمْ</span> <span class=\"quran-arabic-font text-success\">لِلتَّقْوَى</span> <span class=\"quran-arabic-font text-success\">لَهُم</span> <span class=\"quran-arabic-font text-success\">مَّغْفِرَةٌ</span> <span class=\"quran-arabic-font text-success\">وَأَجْرٌ</span> <span class=\"quran-arabic-font text-success\">عَظِيمٌ</span><br />\r\n<br />\r\n(அத்தகையோரின் இதயங்களைத்தான் அல்லாஹ் தக்வாவிற்காகச் சோதித்துள்ளான். அவர்களுக்கு மன்னிப்பும் மகத்தான நற்கூலியும் உண்டு.)\"<br />\r\n<br />","text":"இது மதீனாவில் அருளப்பட்டது\n\r\n\n\r\nبِسْمِ اللَّهِ الرَّحْمَـنِ الرَّحِيمِ\n\r\n\n\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.\n\r\n\n\r\nஅல்லாஹ்வுக்கும் அவனுடைய தூதருக்கும் முன்னால் சுயமாக முடிவெடுப்பது தடைசெய்யப்பட்டுள்ளது; நபியவர்களுக்கு மரியாதை செலுத்துமாறு கட்டளையிடுதல்\n\r\n\n\r\nஇந்த வசனங்களில், கண்ணியமிக்க அல்லாஹ் தனது நம்பிக்கையுள்ள அடியார்களுக்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் அவர்கள் கடைபிடிக்க வேண்டிய நற்பண்புகளான மரியாதை, கண்ணியம் மற்றும் கண்ணியப்படுத்துதல் ஆகியவற்றைக் கற்றுக்கொடுக்கிறான். கண்ணியமும் மேன்மையும் மிக்க அல்லாஹ் கூறினான்:\n\r\n\n\r\nيأَيُّهَا الَّذِينَ ءَامَنُواْ لاَ تُقَدِّمُواْ بَيْنَ يَدَىِ اللَّهِ وَرَسُولِهِ\n\r\n\n\r\n(நம்பிக்கையாளர்களே! அல்லாஹ்வுக்கும் அவனுடைய தூதருக்கும் முன்னால் நீங்கள் முந்தாதீர்கள்,) அதாவது அவருக்கு முன்னால் முடிவெடுப்பதில் அவசரப்படாதீர்கள்; மாறாக, அனைத்து விவகாரங்களிலும் அவரையே பின்பற்றுங்கள். இப்னு அப்பாஸ் (ரழி) அவர்கள் இதைப் பற்றிக் கூறியதாக அலீ பின் அபீ தல்ஹா (ரழி) அவர்கள் அறிவிக்கிறார்கள்:\n\r\n\n\r\nلاَ تُقَدِّمُواْ بَيْنَ يَدَىِ اللَّهِ وَرَسُولِهِ\n\r\n\n\r\n(அல்லாஹ்வுக்கும் அவனுடைய தூதருக்கும் முன்னால் நீங்கள் முந்தாதீர்கள்,) \"குர்ஆன் மற்றும் சுன்னாவிற்கு முரணான எதையும் சொல்லாதீர்கள்.\" கத்தாதா (ரஹ்) அவர்கள் கூறினார்கள்: \"சிலர், 'இன்ன காரியத்தைப் பற்றி வஹீ (இறைச்செய்தி) அருளப்பட வேண்டும்', 'இன்ன காரியங்கள் அனுமதிக்கப்பட வேண்டும்' என்று கூறி வந்ததாக எங்களுக்குக் கூறப்பட்டது. இத்தகைய போக்கை அல்லாஹ் வெறுத்தான்.\" அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَاتَّقُواْ اللَّهَ\n\r\n\n\r\n(மேலும் அல்லாஹ்வுக்கு அஞ்சிக் கொள்ளுங்கள்.) அதாவது, 'அவன் உங்களுக்குக் கட்டளையிட்டவற்றில் (அவனுக்கு அஞ்சுங்கள்)'.\n\r\n\n\r\nإِنَّ اللَّهَ سَمِيعٌ\n\r\n\n\r\n(நிச்சயமாக அல்லாஹ் செவியேற்பவன்,) 'உங்கள் பேச்சுகளை',\n\r\n\n\r\nعَلِيمٌ\n\r\n\n\r\n(நன்கறிந்தவன்.) 'உங்கள் எண்ணங்களை'. அல்லாஹ் கூறினான்:\n\r\n\n\r\nيأَيُّهَا الَّذِينَ ءَامَنُواْ لاَ تَرْفَعُواْ أَصْوَاتَكُمْ فَوْقَ صَوْتِ النَّبِىِّ\n\r\n\n\r\n(நம்பிக்கையாளர்களே! நபியின் குரலுக்கு மேலாக உங்கள் குரல்களை உயர்த்தாதீர்கள்,) இதில் மற்றொரு நற்பண்பு அடங்கியுள்ளது. நம்பிக்கையாளர்கள் நபியவர்களின் (ஸல்) குரலுக்கு மேலாகத் தங்கள் குரல்களை உயர்த்தக் கூடாது என்று அல்லாஹ் அவர்களுக்குக் கற்றுக்கொடுக்கிறான். இந்த வசனம் அபூபக்கர் (ரழி) மற்றும் உமர் (ரழி) ஆகிய இருவரைப் பற்றி அருளப்பட்டதாகக் கூறப்படுகிறது. இப்னு அபீ முலைக்கா (ரஹ்) அவர்கள் கூறியதாக புகாரி (ரஹ்) பதிவு செய்துள்ளார்கள்: \"இரு நற்பண்புள்ளவர்களான அபூபக்கர் (ரழி) மற்றும் உமர் (ரழி) ஆகிய இருவரும், பனூ தமீம் கோத்திரத்தின் தூதுக்குழுவை நபியவர்கள் (ஸல்) சந்தித்துக் கொண்டிருந்தபோது அவர்களுக்கு முன்னால் தங்கள் குரல்களை உயர்த்தியதால் அழிவை நெருங்கிவிட்டனர். அவர்களில் ஒருவர் பனூ முஜாஷிஃ கிளையைச் சேர்ந்த அல்-அக்ராஃ பின் ஹாபிஸைப் (ரழி) பரிந்துரைக்க, மற்றவர் வேறொருவரைப் பரிந்துரைத்தார். (அறிவிப்பாளர் நாஃபிஃ (ரஹ்) கூறுகிறார்: 'அவருடைய பெயர் எனக்கு நினைவில்லை'). அபூபக்கர் (ரழி) அவர்கள் உமர் (ரழி) அவர்களிடம், 'நீங்கள் எனக்கு மாறுபடவே விரும்புகிறீர்கள்' என்று கூறினார்கள். அதற்கு உமர் (ரழி) அவர்கள், 'நான் உங்களுக்கு மாறுபட விரும்பவில்லை' என்று கூறினார்கள். அப்போது அவர்கள் இருவரின் குரல்களும் உயர்ந்தன. அதன் காரணமாகவே அல்லாஹ் இந்த வசனத்தை அருளினான்:\n\r\n\n\r\nيأَيُّهَا الَّذِينَ ءَامَنُواْ لاَ تَرْفَعُواْ أَصْوَاتَكُمْ فَوْقَ صَوْتِ النَّبِىِّ وَلاَ تَجْهَرُواْ لَهُ بِالْقَوْلِ كَجَهْرِ بَعْضِكُمْ لِبَعْضٍ أَن تَحْبَطَ أَعْمَـلُكُمْ وَأَنتُمْ لاَ تَشْعُرُونَ\n\r\n\n\r\n(நம்பிக்கையாளர்களே! நபியின் குரலுக்கு மேலாக உங்கள் குரல்களை உயர்த்தாதீர்கள். மேலும், நீங்கள் ஒருவருக்கொருவர் உரத்த குரலில் பேசுவது போல் அவரிடம் பேசாதீர்கள்; (அவ்வாறு செய்தால்) நீங்கள் அறியாத நிலையிலேயே உங்கள் நற்செயல்கள் அழிந்துவிடும்.)\" அப்துல்லாஹ் பின் அஸ்-ஸுபைர் (ரழி) அவர்கள் கூறினார்கள்: \"இதற்குப் பிறகு, உமர் (ரழி) அவர்களின் குரல் மிகவும் தாழ்வாக இருந்ததால், அவர் சொல்வதைப் புரிந்து கொள்வதற்காக அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அவரை மீண்டும் சொல்லுமாறு கேட்க வேண்டியிருந்தது.\" அப்துல்லாஹ் பின் அஸ்-ஸுபைர் (ரழி) அவர்கள் தனது தந்தை அபூபக்கர் (ரழி) அவர்களைப் பற்றி இவ்வாறு குறிப்பிடவில்லை. முஸ்லிம் இந்த ஹதீஸைப் பதிவு செய்யவில்லை. புகாரி (ரஹ்) பதிவு செய்துள்ள மற்றொரு அறிவிப்பில், பனூ தமீம் கோத்திரத்தைச் சேர்ந்த ஒரு தூதுக்குழு நபியவர்களிடம் (ஸல்) வந்தபோது, அபூபக்கர் (ரழி) அவர்கள் அல்-கஃகாஃ பின் மஃபத் (ரழி) அவர்களைத் தலைவராக நியமிக்கப் பரிந்துரைத்ததாகவும், உமர் (ரழி) அவர்கள் அல்-அக்ராஃ பின் ஹாபிஸைப் (ரழி) பரிந்துரைத்ததாகவும் உள்ளது. முஸ்லிம் இந்த அறிவிப்பைப் பதிவு செய்யவில்லை.\n\r\n\n\r\nஅனஸ் பின் மாலிக் (ரழி) அவர்கள் கூறியதாக புகாரி (ரஹ்) பதிவு செய்துள்ளார்கள்: \"நபியவர்கள் (ஸல்) ஸாபித் பின் கைஸ் (ரழி) அவர்களைக் காணவில்லை. அப்போது ஒரு மனிதர், 'அல்லாஹ்வின் தூதரே! நான் அவரைப் பற்றிய செய்தியை அறிந்து வருகிறேன்' என்றார். அந்த மனிதர் ஸாபித் (ரழி) அவர்களிடம் சென்றபோது, அவர் தனது வீட்டில் தலைகுனிந்து அமர்ந்திருப்பதைக் கண்டார். 'உமக்கு என்ன நேர்ந்தது?' என்று அவரிடம் கேட்டார். அதற்கு ஸாபித் (ரழி) அவர்கள், 'மிகவும் மோசமான விஷயம்!' என்றார்கள். தான் நபியவர்களின் (ஸல்) குரலுக்கு மேலாகத் தனது குரலை உயர்த்தி வந்ததாகவும், அதனால் தனது நற்செயல்கள் அழிந்து தான் நரகவாசிகளில் ஒருவனாகி விடுவோமோ என்று அஞ்சுவதாகவும் அவர் கூறினார். அந்த மனிதர் நபியவர்களிடம் (ஸல்) திரும்பி வந்து ஸாபித் (ரழி) அவர்களின் கூற்றைத் தெரிவித்தார். பின்னர் நபியவர்கள் (ஸல்) வழங்கிய ஒரு நற்செய்தியுடன் அவர் ஸாபித் (ரழி) அவர்களிடம் திரும்பினார். நபியவர்கள் (ஸல்) கூறினார்கள்:\n\r\n\n\r\n«اذْهَبْ إِلَيْهِ فَقُلْ لَهُ: إِنَّكَ لَسْتَ مِنْ أَهْلِ النَّارِ، وَلَكِنَّكَ مِنْ أَهْلِ الْجَنَّة»\n\r\n\n\r\n(அவரிடம் சென்று இந்தச் செய்தியைச் சொல்லுங்கள்; நிச்சயமாக நீங்கள் நரகவாசி அல்ல, மாறாக நீங்கள் சொர்க்கவாசிகளில் ஒருவர்.)\" புகாரி (ரஹ்) இந்த ஹதீஸை இதே வார்த்தைகளில் பதிவு செய்துள்ளார்கள்.\n\r\n\n\r\nஇமாம் அஹ்மத் (ரஹ்) அவர்கள் அனஸ் பின் மாலிக் (ரழி) அவர்கள் வழியாகப் பின்வருமாறு பதிவு செய்துள்ளார்கள்: \"இந்த வசனம் அருளப்பட்டபோது,\n\r\n\n\r\nيأَيُّهَا الَّذِينَ ءَامَنُواْ لاَ تَرْفَعُواْ أَصْوَاتَكُمْ فَوْقَ صَوْتِ النَّبِىِّ\n\r\n\n\r\n(நம்பிக்கையாளர்களே! நபியின் குரலுக்கு மேலாக உங்கள் குரல்களை உயர்த்தாதீர்கள்), என்பது முதல்,\n\r\n\n\r\nوَأَنتُمْ لاَ تَشْعُرُونَ\n\r\n\n\r\n(நீங்கள் அறியாத நிலையில்), என்பது வரையிலான இந்த வசனம் அருளப்பட்டபோது, இயல்பிலேயே உரத்த குரல் கொண்ட ஸாபித் பின் கைஸ் பின் ஷம்மாஸ் (ரழி) அவர்கள், 'நான்தான் அல்லாஹ்வின் தூதருடைய (ஸல்) குரலுக்கு மேலாக என் குரலை உயர்த்தியவன். நான் நரகவாசிகளில் ஒருவன். என் நற்செயல்கள் வீணாகிவிட்டன' என்று கூறினார்கள். அவர்கள் மிகுந்த மனவேதனையுடன் தன் வீட்டிலேயே தங்கியிருந்தார்கள். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அவர் வராததைக் கவனித்தார்கள். எனவே சில மனிதர்கள் ஸாபித் (ரழி) அவர்களிடம் சென்று, 'நபியவர்கள் (ஸல்) உங்களைக் காணவில்லையே, என்ன விஷயம்?' என்று கேட்டார்கள். அதற்கு ஸாபித் (ரழி) அவர்கள், 'நான் நபியவர்களின் (ஸல்) குரலுக்கு மேலாக என் குரலை உயர்த்தி, அவர்களுக்கு முன்னால் சப்தமாகப் பேசக் கூடியவனாக இருந்தேன். என் நற்செயல்கள் வீணாகிவிட்டன, நான் நரகவாசிகளில் ஒருவன்' என்று கூறினார்கள். அவர்கள் நபியவர்களிடம் (ஸல்) சென்று ஸாபித் (ரழி) அவர்கள் கூறியதைத் தெரிவித்தார்கள். அப்போது நபியவர்கள் (ஸல்) கூறினார்கள்:\n\r\n\n\r\n«لَا، بَلْ هُوَ مِنْ أَهْلِ الْجَنَّة»\n\r\n\n\r\n(இல்லை, மாறாக அவர் சொர்க்கவாசிகளில் ஒருவர்.)\" அனஸ் (ரழி) அவர்கள் மேலும் கூறினார்கள்: \"ஸாபித் (ரழி) அவர்கள் சொர்க்கவாசி என்பதை அறிந்த நிலையில் அவர் எங்களுக்கு மத்தியில் நடமாடுவதை நாங்கள் கண்டு வந்தோம். யமாமா போரின்போது எமது படைகள் பின்வாங்கிய போது, ஸாபித் பின் கைஸ் பின் ஷம்மாஸ் (ரழி) அவர்கள் 'ஹனூத்' (வாசனைத் திரவியம்) பூசி, கஃபன் துணிகளை அணிந்தவர்களாக வந்து, 'யா அல்லாஹ்! இவர்கள் (இணைவைப்பாளர்கள்) செய்வதை விட்டும் நான் விலகிக் கொள்கிறேன். மேலும் இவர்கள் (முஸ்லிம்கள்) செய்வதற்காக உன்னிடம் மன்னிப்புக் கோருகிறேன்' என்று கூறிவிட்டு, வீர மரணம் எய்தும் வரை போரிட்டார்கள். அல்லாஹ் அவர்களைப் பொருந்திக் கொள்வானாக.\"\n\r\n\n\r\nஅதன் பிறகு அல்லாஹ், ஒருவரையொருவர் புண்படுத்தும் வகையில் சப்தமாகப் பேசுவது போல் நபியவர்களிடம் (ஸல்) உரத்த குரலில் பேசுவதைத் தடை செய்தான். அதற்குப் பதிலாக, அவரிடம் மரியாதை, கண்ணியம் மற்றும் அமைதியுடன் பேச வேண்டும் என்று கட்டளையிட்டான். இதனால்தான் கண்ணியமும் மேன்மையும் மிக்க அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَلاَ تَجْهَرُواْ لَهُ بِالْقَوْلِ كَجَهْرِ بَعْضِكُمْ لِبَعْضٍ\n\r\n\n\r\n(நீங்கள் ஒருவருக்கொருவர் சப்தமாகப் பேசிக் கொள்வது போல் அவரிடம் சப்தமாகப் பேசாதீர்கள்,) அவன் மற்றொரு வசனத்தில் கூறியது போல:\n\r\n\n\r\nلاَّ تَجْعَلُواْ دُعَآءَ الرَّسُولِ بَيْنَكُمْ كَدُعَآءِ بَعْضِكُمْ بَعْضاً\n\r\n\n\r\n(உங்களுக்கிடையில் நீங்கள் ஒருவரையொருவர் அழைப்பது போல் (அல்லாஹ்வின்) தூதரை அழைக்காதீர்கள்.) (24:63)\n\r\n\n\r\nஅல்லாஹ்வின் கூற்றான,\n\r\n\n\r\nأَن تَحْبَطَ أَعْمَـلُكُمْ وَأَنتُمْ لاَ تَشْعُرُونَ\n\r\n\n\r\n(நீங்கள் உணராத நிலையிலேயே உங்கள் நற்செயல்கள் அழிந்துவிடும்.) என்பதன் பொருள்: நபியவர்கள் (ஸல்) உங்கள் மீது கோபப்படாமல் இருப்பதற்காக, அவரிடம் குரலை உயர்த்தக் கூடாது என நாம் உங்களுக்குக் கட்டளையிட்டோம். ஏனெனில் அவர் கோபப்பட்டால் அல்லாஹ்வும் கோபப்படுவான். நபியவர்களின் (ஸல்) கோபத்திற்கு ஆளானவரின் நற்செயல்கள் அவர் அறியாமலேயே வீணாகிவிடும். ஸஹீஹ் நூலில் ஒரு ஹதீஸ் இவ்வாறு இடம் பெற்றுள்ளது:\n\r\n\n\r\n«إِنَّ الرَّجُلَ لَيَتَكَلَّمُ بِالْكَلِمَةِ مِنْ رِضْوَانِ اللهِ تَعَالَى لَا يُلْقِي لَهَا بَالًا، يُكْتَبُ لَهُ بِهَا الْجَنَّةُ، وَإِنَّ الرَّجُلَ لَيَتَكَلَّمُ بِالْكَلِمَةِ مِنْ سَخَطِ اللهِ تَعَالَى لَا يُلْقِي لَهَا بَالًا، يَهْوِي بِهَا فِي النَّارِ أَبْعَدَ مَا بَيْنَ السَّمَاءِ وَالْأَرْض»\n\r\n\n\r\n(நிச்சயமாக, ஒரு மனிதன் அதன் முக்கியத்துவத்தை உணராமலேயே மேலான அல்லாஹ்வின் திருப்திக்குரிய ஒரு வார்த்தையைப் பேசுவான், அதன் காரணமாக அவனுக்குச் சொர்க்கம் விதிக்கப்படுகிறது. நிச்சயமாக ஒரு மனிதன் கவனக்குறைவாக மேலான அல்லாஹ்வின் கோபத்திற்குரிய ஒரு வார்த்தையைப் பேசுவான், அதன் காரணமாக அவன் வானத்திற்கும் பூமிக்கும் இடையிலான தூரத்தை விட வெகு தூரத்தில் நரகத்தில் வீசப்படுவான்.)\n\r\n\n\r\nஅதன் பிறகு அல்லாஹ், அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுக்கு முன்னால் குரலைத் தாழ்த்துமாறு கட்டளையிடுகிறான். மேலும் இந்தச் சிறந்த நற்பண்பைப் பேணுமாறு ஊக்குவித்து வழிநடத்துகிறான்.\n\r\n\n\r\nإِنَّ الَّذِينَ يَغُضُّونَ أَصْوَاتَهُمْ عِندَ رَسُولِ اللَّهِ أُوْلَـئِكَ الَّذِينَ امْتَحَنَ اللَّهُ قُلُوبَهُمْ لِلتَّقْوَى\n\r\n\n\r\n(நிச்சயமாக, அல்லாஹ்வின் தூதருடைய (ஸல்) முன்னிலையில் எவர்கள் தங்கள் குரல்களைத் தாழ்த்திக் கொள்கிறார்களோ, அத்தகையோரின் இதயங்களை அல்லாஹ் தக்வாவிற்காக (பயபக்திக்காக) சோதித்துள்ளான்.) அதாவது, எவர்களின் இதயங்களை அல்லாஹ் தூய்மைப்படுத்தி, தக்வாவின் இருப்பிடமாக ஆக்கியுள்ளானோ அத்தகையோர் ஆவர்.\n\r\n\n\r\nلَهُم مَّغْفِرَةٌ وَأَجْرٌ عَظِيمٌ\n\r\n\n\r\n(அவர்களுக்கு மன்னிப்பும் மகத்தான நற்கூலியும் உண்டு.)\n\r\n\n\r\nஇமாம் அஹ்மத் (ரஹ்) அவர்கள் 'கிதாபுஸ் ஸுஹ்த்' நூலில் முஜாஹித் (ரஹ்) அவர்கள் கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"ஒருவர் உமர் (ரழி) அவர்களுக்குக் கடிதம் எழுதினார்: 'நம்பிக்கையாளர்களின் தலைவரே! பாவம் செய்ய வேண்டும் என்ற ஆசையே ஏற்படாமல் பாவம் செய்யாத மனிதர் சிறந்தவரா அல்லது பாவம் செய்ய ஆசை இருந்தும் (அல்லாஹ்வை) அஞ்சிக் கொண்டு அதைக் கைவிடுகிறவர் சிறந்தவரா?' உமர் (ரழி) அவர்கள் பதிலளித்தார்கள்: 'யார் பாவம் செய்ய ஆசை இருந்தும் அதைச் செய்யாமல் தன்னைத் தடுத்துக் கொள்கிறாரோ அவரே சிறந்தவர்.\n\r\n\n\r\nأُوْلَـئِكَ الَّذِينَ امْتَحَنَ اللَّهُ قُلُوبَهُمْ لِلتَّقْوَى لَهُم مَّغْفِرَةٌ وَأَجْرٌ عَظِيمٌ\n\r\n\n\r\n(அத்தகையோரின் இதயங்களைத்தான் அல்லாஹ் தக்வாவிற்காகச் சோதித்துள்ளான். அவர்களுக்கு மன்னிப்பும் மகத்தான நற்கூலியும் உண்டு.)\""},"4":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=49&ayah=6\" class=\"link\">49:6</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 49:6 ஐ பார்க்கவும்"},"5":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=49&ayah=6\" class=\"link\">49:6</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 49:6 ஐ பார்க்கவும்"},"6":{"html":"<strong>அறைகளுக்குப் பின்னாலிருந்து நபியை அழைப்பவர்களைக் கண்டித்தல்</strong><br />\r\n<br />\r\n<br />\r\nமேன்மையும் பாக்கியமும் மிக்க அல்லாஹ், நபியவர்களின் (ஸல்) மனைவியருக்குச் சொந்தமான அறைகளுக்குப் பின்னாலிருந்து அவர்களை (நபியை) அழைத்த நாகரிகமற்ற கிராமப்புற அரபியர்களைப் போன்றவர்களைக் கண்டித்தான்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَكْثَرُهُمْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَعْقِلُونَ</span><br />\r\n<br />\r\n<br />\r\n(அவர்களில் பெரும்பாலோர் விளங்கிக்கொள்ள மாட்டார்கள்.) பின்னர், மேன்மையும் கண்ணியமும் மிக்க அல்லாஹ் இது தொடர்பாகச் சிறந்த ஒழுக்கத்தை இவ்வாறாகக் கட்டளையிடுகிறான்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">أَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">صَبَرُواْ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">تَخْرُجَ</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">لَكَانَ</span> <span class=\"quran-arabic-font text-success\">خَيْراً</span> <span class=\"quran-arabic-font text-success\">لَّهُمْ</span><br />\r\n<br />\r\n<br />\r\n(நீர் அவர்களிடம் வெளியே வரும் வரை அவர்கள் பொறுத்திருந்தால், அதுவே அவர்களுக்குச் சிறந்ததாக இருந்திருக்கும்.) இது அவர்களுக்கு இம்மையிலும் மறுமையிலும் சிறந்த நன்மையைப் பெற்றுத்தந்திருக்கும். புகழுக்கெல்லாம் உரியவனான அல்லாஹ், அவர்கள் தன்னிடம் பாவமன்னிப்புக் கோரித் திரும்புமாறு பின்னர் ஊக்குவிக்கிறான்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">غَفُورٌ</span> <span class=\"quran-arabic-font text-success\">رَّحِيمٌ</span><br />\r\n<br />\r\n<br />\r\n(மேலும் அல்லாஹ் மன்னிப்பவனும் நிகரற்ற அன்புடையவனுமாவான்.) ஒன்றுக்கும் மேற்பட்ட சான்றுகளின்படி, இந்த வசனம் அல்-அக்ரஃ பின் ஹபீஸ் அத்-தமீமீ (ரழி) அவர்களைப் பற்றி இறங்கியதாக அறிவிக்கப்பட்டுள்ளது. அல்-அக்ரஃ பின் ஹபீஸ் (ரழி) அவர்கள், நபியவர்களின் (ஸல்) அறைகளுக்குப் பின்னாலிருந்து, \"முஹம்மதே! முஹம்மதே!\" என்று சத்தமிட்டு அல்லாஹ்வின் தூதரை (ஸல்) அழைத்ததாக இமாம் அஹ்மத் பதிவு செய்துள்ளார்கள். மற்றொரு அறிவிப்பின்படி, \"அல்லாஹ்வின் தூதரே!\" என்று அவர்கள் அழைத்ததாகவும், அதற்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அவருக்குப் பதிலளிக்கவில்லை என்றும் கூறப்பட்டுள்ளது. அப்பொழுது அல்-அக்ரஃ (ரழி) அவர்கள், \"அல்லாஹ்வின் தூதரே! நிச்சயமாக எனது புகழ்ச்சி அலங்காரமானது; எனது இகழ்ச்சி அலங்கோலமானது” என்று கூறினார். அதற்கு நபியவர்கள் (ஸல்), “அது அல்லாஹ் ஒருவனுக்கே உரியது” என்று கூறினார்கள்.<br />\r\n<br />\r\n<br />\r\n<strong>தீயவர்கள் கொண்டு வரும் செய்திகளின் நம்பகத்தன்மையை ஆராய்தல்</strong><br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">أَيُّهَا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">جَآءَكُمْ</span> <span class=\"quran-arabic-font text-success\">فَاسِقٌ</span> <span class=\"quran-arabic-font text-success\">بِنَبَإٍ</span> <span class=\"quran-arabic-font text-success\">فَتَبَيَّنُواْ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تُصِيبُواْ</span> <span class=\"quran-arabic-font text-success\">قَوْمًا</span> <span class=\"quran-arabic-font text-success\">بِجَهَالَةٍ</span> <span class=\"quran-arabic-font text-success\">فَتُصْبِحُواْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">فَعَلْتُمْ</span> <span class=\"quran-arabic-font text-success\">نَادِمِينَ</span><br />\r\n<br />\r\n(நம்பிக்கையாளர்களே! தீயவன் ஒருவன் உங்களிடம் ஒரு செய்தியைக் கொண்டு வந்தால், அதைத் தீர்க்க விசாரித்துக் கொள்ளுங்கள். (இல்லாவிடில்,) அறியாமையினால் ஒரு கூட்டத்தாருக்கு நீங்கள் தீங்கு செய்து விடலாம். பின்னர், நீங்கள் செய்தவை குறித்து நீங்களே கைசேதப்படுபவர்களாக (கவலைப்படுபவர்களாக) ஆகிவிடுவீர்கள்.)<br />\r\n<br />\r\n<br />\r\nபாவிகளும் தீயவர்களும் கொண்டு வரும் செய்திகள் உண்மையானவை தானா என்பதை உறுதிப்படுத்த அவற்றை நன்கு ஆராயுமாறு மேலான அல்லாஹ் கட்டளையிட்டான். இல்லையெனில், ஒரு பாவி கூறும் தகவல் உண்மையா பொய்யா என்பதைப் பொருட்படுத்தாமல் அதை அப்படியே ஏற்று அதன் அடிப்படையில் முடிவெடுத்தால், அதிகாரிகள் அந்தப் பாவிகளின் வழியைப் பின்பற்றுபவர்களாக ஆகிவிடுவார்கள். சீர் குலைந்தவர்கள் மற்றும் பாவிகளின் பாதையைப் பின்பற்றுவதை மேன்மையும் கண்ணியமும் மிக்க அல்லாஹ் தடுத்தான். இதன் காரணமாகவே, ஹதீஸ் கலை அறிஞர்களில் ஒரு பிரிவினர், நம்பகத்தன்மை உறுதிப்படுத்தப்படாத அறிவிப்பாளர்களிடமிருந்து வரும் அறிவிப்புகளை ஏற்க மறுக்கிறார்கள். ஏனெனில், எதார்த்தத்தில் அவர்கள் தீயவர்களில் ஒருவராக இருக்கக்கூடும்.<br />\r\n<br />\r\n<br />\r\n<strong>நபியவர்களின் முடிவே சிறந்தது</strong><br />\r\n<br />\r\n<br />\r\nஅல்லாஹ் கூறினான்,<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاعْلَمُوا</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">فِيكُمْ</span> <span class=\"quran-arabic-font text-success\">رَسُولَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">لَوْ</span> <span class=\"quran-arabic-font text-success\">يُطِيعُكُمْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">كَثِيرٍ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْأَمْرِ</span> <span class=\"quran-arabic-font text-success\">لَعَنِتُّمْ</span><br />\r\n<br />\r\n(மேலும், அல்லாஹ்வின் தூதர் உங்களிடையே இருக்கிறார் என்பதை நீங்கள் அறிந்துகொள்ளுங்கள். பல விவகாரங்களில் அவர் உங்களுக்குக் கட்டுப்பட்டால், நீங்களே சிரமத்திற்குள்ளாவீர்கள்.)<br />\r\n<br />\r\n<br />\r\n<br />\r\n<br />","text":"அறைகளுக்குப் பின்னாலிருந்து நபியை அழைப்பவர்களைக் கண்டித்தல்\n\r\n\n\r\n\n\r\nமேன்மையும் பாக்கியமும் மிக்க அல்லாஹ், நபியவர்களின் (ஸல்) மனைவியருக்குச் சொந்தமான அறைகளுக்குப் பின்னாலிருந்து அவர்களை (நபியை) அழைத்த நாகரிகமற்ற கிராமப்புற அரபியர்களைப் போன்றவர்களைக் கண்டித்தான்.\n\r\n\n\r\n\n\r\nأَكْثَرُهُمْ لاَ يَعْقِلُونَ\n\r\n\n\r\n\n\r\n(அவர்களில் பெரும்பாலோர் விளங்கிக்கொள்ள மாட்டார்கள்.) பின்னர், மேன்மையும் கண்ணியமும் மிக்க அல்லாஹ் இது தொடர்பாகச் சிறந்த ஒழுக்கத்தை இவ்வாறாகக் கட்டளையிடுகிறான்:\n\r\n\n\r\n\n\r\nوَلَوْ أَنَّهُمْ صَبَرُواْ حَتَّى تَخْرُجَ إِلَيْهِمْ لَكَانَ خَيْراً لَّهُمْ\n\r\n\n\r\n\n\r\n(நீர் அவர்களிடம் வெளியே வரும் வரை அவர்கள் பொறுத்திருந்தால், அதுவே அவர்களுக்குச் சிறந்ததாக இருந்திருக்கும்.) இது அவர்களுக்கு இம்மையிலும் மறுமையிலும் சிறந்த நன்மையைப் பெற்றுத்தந்திருக்கும். புகழுக்கெல்லாம் உரியவனான அல்லாஹ், அவர்கள் தன்னிடம் பாவமன்னிப்புக் கோரித் திரும்புமாறு பின்னர் ஊக்குவிக்கிறான்.\n\r\n\n\r\n\n\r\nوَاللَّهُ غَفُورٌ رَّحِيمٌ\n\r\n\n\r\n\n\r\n(மேலும் அல்லாஹ் மன்னிப்பவனும் நிகரற்ற அன்புடையவனுமாவான்.) ஒன்றுக்கும் மேற்பட்ட சான்றுகளின்படி, இந்த வசனம் அல்-அக்ரஃ பின் ஹபீஸ் அத்-தமீமீ (ரழி) அவர்களைப் பற்றி இறங்கியதாக அறிவிக்கப்பட்டுள்ளது. அல்-அக்ரஃ பின் ஹபீஸ் (ரழி) அவர்கள், நபியவர்களின் (ஸல்) அறைகளுக்குப் பின்னாலிருந்து, \"முஹம்மதே! முஹம்மதே!\" என்று சத்தமிட்டு அல்லாஹ்வின் தூதரை (ஸல்) அழைத்ததாக இமாம் அஹ்மத் பதிவு செய்துள்ளார்கள். மற்றொரு அறிவிப்பின்படி, \"அல்லாஹ்வின் தூதரே!\" என்று அவர்கள் அழைத்ததாகவும், அதற்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அவருக்குப் பதிலளிக்கவில்லை என்றும் கூறப்பட்டுள்ளது. அப்பொழுது அல்-அக்ரஃ (ரழி) அவர்கள், \"அல்லாஹ்வின் தூதரே! நிச்சயமாக எனது புகழ்ச்சி அலங்காரமானது; எனது இகழ்ச்சி அலங்கோலமானது” என்று கூறினார். அதற்கு நபியவர்கள் (ஸல்), “அது அல்லாஹ் ஒருவனுக்கே உரியது” என்று கூறினார்கள்.\n\r\n\n\r\n\n\r\nதீயவர்கள் கொண்டு வரும் செய்திகளின் நம்பகத்தன்மையை ஆராய்தல்\n\r\n\n\r\n\n\r\nيَا أَيُّهَا الَّذِينَ ءَامَنُواْ إِن جَآءَكُمْ فَاسِقٌ بِنَبَإٍ فَتَبَيَّنُواْ أَن تُصِيبُواْ قَوْمًا بِجَهَالَةٍ فَتُصْبِحُواْ عَلَى مَا فَعَلْتُمْ نَادِمِينَ\n\r\n\n\r\n(நம்பிக்கையாளர்களே! தீயவன் ஒருவன் உங்களிடம் ஒரு செய்தியைக் கொண்டு வந்தால், அதைத் தீர்க்க விசாரித்துக் கொள்ளுங்கள். (இல்லாவிடில்,) அறியாமையினால் ஒரு கூட்டத்தாருக்கு நீங்கள் தீங்கு செய்து விடலாம். பின்னர், நீங்கள் செய்தவை குறித்து நீங்களே கைசேதப்படுபவர்களாக (கவலைப்படுபவர்களாக) ஆகிவிடுவீர்கள்.)\n\r\n\n\r\n\n\r\nபாவிகளும் தீயவர்களும் கொண்டு வரும் செய்திகள் உண்மையானவை தானா என்பதை உறுதிப்படுத்த அவற்றை நன்கு ஆராயுமாறு மேலான அல்லாஹ் கட்டளையிட்டான். இல்லையெனில், ஒரு பாவி கூறும் தகவல் உண்மையா பொய்யா என்பதைப் பொருட்படுத்தாமல் அதை அப்படியே ஏற்று அதன் அடிப்படையில் முடிவெடுத்தால், அதிகாரிகள் அந்தப் பாவிகளின் வழியைப் பின்பற்றுபவர்களாக ஆகிவிடுவார்கள். சீர் குலைந்தவர்கள் மற்றும் பாவிகளின் பாதையைப் பின்பற்றுவதை மேன்மையும் கண்ணியமும் மிக்க அல்லாஹ் தடுத்தான். இதன் காரணமாகவே, ஹதீஸ் கலை அறிஞர்களில் ஒரு பிரிவினர், நம்பகத்தன்மை உறுதிப்படுத்தப்படாத அறிவிப்பாளர்களிடமிருந்து வரும் அறிவிப்புகளை ஏற்க மறுக்கிறார்கள். ஏனெனில், எதார்த்தத்தில் அவர்கள் தீயவர்களில் ஒருவராக இருக்கக்கூடும்.\n\r\n\n\r\n\n\r\nநபியவர்களின் முடிவே சிறந்தது\n\r\n\n\r\n\n\r\nஅல்லாஹ் கூறினான்,\n\r\n\n\r\n\n\r\nوَاعْلَمُوا أَنَّ فِيكُمْ رَسُولَ اللَّهِ لَوْ يُطِيعُكُمْ فِي كَثِيرٍ مِّنَ الْأَمْرِ لَعَنِتُّمْ\n\r\n\n\r\n(மேலும், அல்லாஹ்வின் தூதர் உங்களிடையே இருக்கிறார் என்பதை நீங்கள் அறிந்துகொள்ளுங்கள். பல விவகாரங்களில் அவர் உங்களுக்குக் கட்டுப்பட்டால், நீங்களே சிரமத்திற்குள்ளாவீர்கள்.)"},"7":{"html":"அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">وَاعْلَمُواْ</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">فِيكُمْ</span> <span class=\"quran-arabic-font text-success\">رَسُولَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> (மேலும், அறிந்து கொள்ளுங்கள்! நிச்சயமாக அல்லாஹ்வின் தூதர் உங்களிடையே இருக்கிறார்.) அதாவது, அவரைக் கண்ணியப்படுத்தி, அவருக்கு மரியாதை செய்யுங்கள். அவர் உங்களுக்குக் கட்டளையிடுவதற்குப் பணிந்து நடங்கள். ஏனெனில், உங்களுக்கு நன்மை பயப்பவை எவை என்பதை அவர் உங்களைவிட நன்கறிவார். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">النَّبِىُّ</span> <span class=\"quran-arabic-font text-success\">أَوْلَى</span> <span class=\"quran-arabic-font text-success\">بِالْمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَنْفُسِهِمْ</span><br />\r\n<br />\r\n(நபி அவர்கள் நம்பிக்கையாளர்களுக்கு அவர்களது உயிர்களை விடவும் நெருக்கமானவர்கள்) (<a href=\"qurandisp.php?sura=33&ayah=6\" class=\"link\">33:6</a>). பின்னர், அவர்கள் தங்களுக்கு எது சிறந்தது என்பதைக் கண்டறிவதில் குறைபாடு உடையவர்களாக இருக்கிறார்கள் என்பதை அவன் தெளிவுபடுத்துகிறான்;<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَوْ</span> <span class=\"quran-arabic-font text-success\">يُطِيعُكُمْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">كَثِيرٍ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْأَمْرِ</span> <span class=\"quran-arabic-font text-success\">لَعَنِتُّمْ</span><br />\r\n<br />\r\n(7 தொடர்ச்சி - அநேகமான காரியங்களில் அவர் உங்களுக்குக் கீழ்ப்படிந்தால், நிச்சயமாக நீங்கள் சிரமத்திற்கு ஆளாகிவிடுவீர்கள்.) \"அவர் உங்கள் கருத்துக்களுக்கும் விருப்பங்களுக்கும் கட்டுப்பட்டால், நீங்கள் துன்பத்தையும் கஷ்டத்தையுமே அடைவீர்கள்.\" கண்ணியமும் மேன்மையும் மிக்க அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَوِ</span> <span class=\"quran-arabic-font text-success\">اتَّبَعَ</span> <span class=\"quran-arabic-font text-success\">الْحَقُّ</span> <span class=\"quran-arabic-font text-success\">أَهْوَاءَهُمْ</span> <span class=\"quran-arabic-font text-success\">لَفَسَدَتِ</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتُ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضُ</span> <span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">فِيهِنَّ</span> <span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">أَتَيْنَاهُمْ</span> <span class=\"quran-arabic-font text-success\">بِذِكْرِهِمْ</span> <span class=\"quran-arabic-font text-success\">فَهُمْ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">ذِكْرِهِمْ</span> <span class=\"quran-arabic-font text-success\">مُّعْرِضُونَ</span><br />\r\n<br />\r\n(சத்தியம் மட்டும் அவர்களுடைய மனோ இச்சைகளைப் பின்பற்றியிருந்தால், வானங்களும் பூமியும் அவற்றில் உள்ளவைகளும் நிச்சயமாகச் சீரழிந்து போயிருக்கும். அவ்வாறன்றி, நாம் அவர்களுக்கு அவர்களுடைய அறிவுரையைக் (குர்ஆனைக்) கொண்டு வந்தோம்; ஆனால் அவர்கள் தங்கள் அறிவுரையிலிருந்து விலகிச் செல்கின்றனர்.) (<a href=\"qurandisp.php?sura=23&ayah=71\" class=\"link\">23:71</a>) அல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَكِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">حَبَّبَ</span> <span class=\"quran-arabic-font text-success\">إِلَيْكُمُ</span> <span class=\"quran-arabic-font text-success\">الْإِيمَانَ</span> <span class=\"quran-arabic-font text-success\">وَزَيَّنَهُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">قُلُوبِكُمْ</span><br />\r\n<br />\r\n(7 தொடர்ச்சி - எனினும், அல்லாஹ் உங்களுக்கு ஈமானை (நம்பிக்கையை) பிரியமானதாக ஆக்கினான்; அதனை உங்கள் உள்ளங்களில் அழகாக்கினான்.) \"அவன் உங்கள் ஆன்மாக்களுக்கு ஈமானைப் பிரியமானதாக ஆக்கி, உங்கள் இதயங்களில் அதை அலங்கரித்தான்.\" அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكَرَّهَ</span> <span class=\"quran-arabic-font text-success\">إِلَيْكُمُ</span> <span class=\"quran-arabic-font text-success\">الْكُفْرَ</span> <span class=\"quran-arabic-font text-success\">وَالْفُسُوقَ</span> <span class=\"quran-arabic-font text-success\">وَالْعِصْيَانَ</span><br />\r\n<br />\r\n(7 தொடர்ச்சி - மேலும் நிராகரிப்பையும், பாவங்களையும் (ஃபுஸூக்), மாறுபாடுகளையும் (இஸ்யான்) உங்களுக்கு வெறுப்பானதாக ஆக்கினான்.) \"அவன் நிராகரிப்பையும், பெரும் பாவங்களையும் (ஃபுஸூக்), மேலும் பெரும் பாவங்கள் அல்லது சிறு பாவங்கள் என அனைத்து வகையான பாவங்களையும் (இஸ்யான்) உங்களுக்கு வெறுப்பானதாக ஆக்கினான்.\" இந்தக் கூற்று, அல்லாஹ்வின் அருட்கொடையைப் பூரணப்படுத்துவதற்காக நம்மை ஒரு நிலையிலிருந்து சிறந்ததொரு நிலைக்குக் கொண்டு செல்கிறது. அடுத்து அல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أُولَئِكَ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الرَّاشِدُونَ</span><br />\r\n<br />\r\n(7 தொடர்ச்சி - இத்தகையவர்களே நேர்வழி பெற்றவர்கள்.) இப்பண்புகளைக் கொண்டவர்களே அல்லாஹ்வினால் நேர்வழியும் சரியான தன்மையும் வழங்கப்பட்ட நேர்வழி பெற்றவர்கள் ஆவர். இமாம் அஹ்மத் அவர்கள் அபூ ரிஃபாஆ அஸ்-ஸுரக்கீ (ரழி) அவர்கள் தம் தந்தை கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"உஹுத் போரின்போது, இணைவைப்பாளர்கள் பின்வாங்கியபோது, அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">اسْتَوُوا</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">أُثْنِيَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">رَبِّي</span> <span class=\"quran-arabic-font text-success\">عَزَّ</span> <span class=\"quran-arabic-font text-success\">وَجَل</span>»<br />\r\n<br />\r\n(நீங்கள் நேராக நில்லுங்கள், நான் கண்ணியமும் மேன்மையும் மிக்க என் இறைவனைப் புகழ வேண்டும்.) அவர்கள் நபி (ஸல்) அவர்களுக்குப் பின்னால் வரிசைகளாக நின்றார்கள். அப்போது அன்னார் (ஸல்) பின்வருமாறு கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">اللْهُمَّ</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">الْحَمْدُ</span> <span class=\"quran-arabic-font text-success\">كُلُّهُ،</span> <span class=\"quran-arabic-font text-success\">اللْهُمَّ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">قَابِضَ</span> <span class=\"quran-arabic-font text-success\">لِمَا</span> <span class=\"quran-arabic-font text-success\">بَسَطْتَ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">بَاسِطَ</span> <span class=\"quran-arabic-font text-success\">لِمَا</span> <span class=\"quran-arabic-font text-success\">قَبَضْتَ،</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">هَادِيَ</span> <span class=\"quran-arabic-font text-success\">لِمَنْ</span> <span class=\"quran-arabic-font text-success\">أَضْلَلْتَ،</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">مُضِلَّ</span> <span class=\"quran-arabic-font text-success\">لِمَنْ</span> <span class=\"quran-arabic-font text-success\">هَدَيْتَ،</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">مُعْطِيَ</span> <span class=\"quran-arabic-font text-success\">لِمَا</span> <span class=\"quran-arabic-font text-success\">مَنَعْتَ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">مَانِعَ</span> <span class=\"quran-arabic-font text-success\">لِمَا</span> <span class=\"quran-arabic-font text-success\">أَعْطَيْتَ،</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">مُقَرِّبَ</span> <span class=\"quran-arabic-font text-success\">لِمَا</span> <span class=\"quran-arabic-font text-success\">بَاعَدْتَ،</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">مُبَاعِدَ</span> <span class=\"quran-arabic-font text-success\">لِمَا</span> <span class=\"quran-arabic-font text-success\">قَرَّبْتَ</span>. <span class=\"quran-arabic-font text-success\">اللْهُمَّ</span> <span class=\"quran-arabic-font text-success\">ابْسُطْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْنَا</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">بَرَكَاتِكَ</span> <span class=\"quran-arabic-font text-success\">وَرَحْمَتِكَ</span> <span class=\"quran-arabic-font text-success\">وَفَضْلِكَ</span> <span class=\"quran-arabic-font text-success\">وَرِزْقِكَ،</span> <span class=\"quran-arabic-font text-success\">اللْهُمَّ</span> <span class=\"quran-arabic-font text-success\">إِنِّي</span> <span class=\"quran-arabic-font text-success\">أَسْأَلُكَ</span> <span class=\"quran-arabic-font text-success\">النَّعِيمَ</span> <span class=\"quran-arabic-font text-success\">الْمُقِيمَ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَحُولُ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">يَزُولُ</span>. <span class=\"quran-arabic-font text-success\">اللْهُمَّ</span> <span class=\"quran-arabic-font text-success\">إِنِّي</span> <span class=\"quran-arabic-font text-success\">أَسْأَلُكَ</span> <span class=\"quran-arabic-font text-success\">النَّعِيمَ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْعَيْلَةِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَمْنَ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْخَوْفِ</span>. <span class=\"quran-arabic-font text-success\">اللْهُمَّ</span> <span class=\"quran-arabic-font text-success\">إِنِّي</span> <span class=\"quran-arabic-font text-success\">عَائِذٌ</span> <span class=\"quran-arabic-font text-success\">بِكَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">شَرِّ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">أَعْطَيْتَنَا</span> <span class=\"quran-arabic-font text-success\">وَمِنْ</span> <span class=\"quran-arabic-font text-success\">شَرِّ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">مَنَعْتَنَا</span>. <span class=\"quran-arabic-font text-success\">اللْهُمَّ</span> <span class=\"quran-arabic-font text-success\">حَبِّبْ</span> <span class=\"quran-arabic-font text-success\">إِلَيْنَا</span> <span class=\"quran-arabic-font text-success\">الْإيمَانَ</span> <span class=\"quran-arabic-font text-success\">وَزَيِّنْهُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">قُلُوبِنَا</span> <span class=\"quran-arabic-font text-success\">وَكَرِّهْ</span> <span class=\"quran-arabic-font text-success\">إِلَيْنَا</span> <span class=\"quran-arabic-font text-success\">الْكُفْرَ</span> <span class=\"quran-arabic-font text-success\">وَالْفُسُوقَ</span> <span class=\"quran-arabic-font text-success\">وَالْعِصْيَانَ</span> <span class=\"quran-arabic-font text-success\">وَاجْعَلْنَا</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الرَّاشِدِينَ</span>. <span class=\"quran-arabic-font text-success\">اللْهُمَّ</span> <span class=\"quran-arabic-font text-success\">تَوَفَّنَا</span> <span class=\"quran-arabic-font text-success\">مُسْلِمِينَ</span> <span class=\"quran-arabic-font text-success\">وَأَحْيِنَا</span> <span class=\"quran-arabic-font text-success\">مُسْلِمِينَ</span> <span class=\"quran-arabic-font text-success\">وَأَلْحِقْنَا</span> <span class=\"quran-arabic-font text-success\">بِالصَّالِحِينَ</span> <span class=\"quran-arabic-font text-success\">غَيْرَ</span> <span class=\"quran-arabic-font text-success\">خَزَايَا</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">مَفْتُونِينَ،</span> <span class=\"quran-arabic-font text-success\">اللْهُمَّ</span> <span class=\"quran-arabic-font text-success\">قَاتِلِ</span> <span class=\"quran-arabic-font text-success\">الْكَفَرَةَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يُكَذِّبُونَ</span> <span class=\"quran-arabic-font text-success\">رُسُلَكَ</span> <span class=\"quran-arabic-font text-success\">وَيَصُدُّونَ</span> <span class=\"quran-arabic-font text-success\">عَنْ</span> <span class=\"quran-arabic-font text-success\">سَبِيلِكَ</span> <span class=\"quran-arabic-font text-success\">وَاجْعَلْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">رِجْزَكَ</span> <span class=\"quran-arabic-font text-success\">وَعَذَابَكَ،</span> <span class=\"quran-arabic-font text-success\">اللْهُمَّ</span> <span class=\"quran-arabic-font text-success\">قَاتِلِ</span> <span class=\"quran-arabic-font text-success\">الْكَفَرَةَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">أُوتُوا</span> <span class=\"quran-arabic-font text-success\">الْكِتَابَ</span> <span class=\"quran-arabic-font text-success\">إِلَهَ</span> <span class=\"quran-arabic-font text-success\">الْحَقِّ</span>»<br />\r\n<br />\r\n(யா அல்லாஹ்! புகழனைத்தும் உனக்கே உரியது. யா அல்லாஹ்! நீ விரிப்பதைத் தடுக்க எவரும் இல்லை; நீ சுருக்கியதை விரிக்க எவரும் இல்லை. நீ வழிகெடுத்தவருக்கு நேர்வழி காட்டுபவர் எவரும் இல்லை; நீ நேர்வழி காட்டியவரை வழிகெடுப்பவர் எவரும் இல்லை. நீ தடுத்ததைக் கொடுப்பவர் எவரும் இல்லை; நீ கொடுத்ததைத் தடுப்பவர் எவரும் இல்லை. நீ தூரமாக்கியதை நெருக்கமாக்க எவரும் இல்லை; நீ நெருக்கமாக்கியதைத் தூரமாக்க எவரும் இல்லை. யா அல்லாஹ்! உனது அபிவிருத்திகளையும், கருணையையும், அருளையும், வாழ்வாதாரத்தையும் எங்கள் மீது பொழிவாயாக. யா அல்லாஹ்! என்றுமே மாறாத, அழியாத நிலையான பேரின்பத்தை உன்னிடம் வேண்டுகிறேன். யா அல்லாஹ்! வறுமை ஏற்படும் நாளில் வாழ்வாதாரத்தையும், அச்சம் ஏற்படும் நாளில் பாதுகாப்பையும் உன்னிடம் வேண்டுகிறேன். யா அல்லாஹ்! நீ எங்களுக்கு வழங்கியவற்றின் தீய விளைவுகளிலிருந்தும், நீ எங்களுக்குத் தடுத்தவற்றின் தீமையிலிருந்தும் உன்னிடம் பாதுகாப்புத் தேடுகிறேன். யா அல்லாஹ்! ஈமானை எங்களுக்குப் பிரியமானதாக ஆக்குவாயாக; அதனை எங்கள் உள்ளங்களில் அழகாக்குவாயாக. மேலும் குஃப்ரை (நிராகரிப்பு), பாவங்களை (ஃபுஸூக்), மாறுபாடுகளை (இஸ்யான்) எங்களுக்கு வெறுப்பானதாக ஆக்கி, எங்களை நேர்வழி பெற்றவர்களில் சேர்த்தருள்வாயாக. யா அல்லாஹ்! எங்களை முஸ்லிம்களாக மரணிக்கச் செய்வாயாக; முஸ்லிம்களாக வாழச் செய்வாயாக; எந்தவொரு அவமானத்திற்கும் அல்லது சோதனைகளுக்கும் உள்ளாக்காமல், எங்களை ஸாலிஹீன்களுடன் (நல்லோர்களுடன்) சேர்த்தருள்வாயாக. யா அல்லாஹ்! உனது தூதர்களைப் பொய்யாக்கி, உனது பாதையிலிருந்து மக்களைத் தடுக்கும் அந்த நிராகரிப்பாளர்களுக்கு எதிராகப் போர் புரிவாயாக; அவர்கள் மீது உனது வேதனையையும் தண்டனையையும் இறக்குவாயாக. உண்மையான இறைவனே! வேதம் வழங்கப்பட்டவர்களில் உள்ள நிராகரிப்பாளர்களுக்கு எதிராகப் போர் புரிவாயாக.)\" இமாம் நஸாஈ அவர்கள் இந்த ஹதீஸை 'அமல் அல்-யவ்ம் வல்-லைலா'வில் பதிவு செய்துள்ளார்கள். அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَضْلاً</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَنِعْمَةً</span> <span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">عَلِيمٌ</span> <span class=\"quran-arabic-font text-success\">حَكِيمٌ</span><br />\r\n<br />\r\n(8. இது அல்லாஹ்விடமிருந்துள்ள அருட்கொடையாகவும், பாக்கியமாகவும் இருக்கிறது; மேலும் அல்லாஹ் நன்கறிந்தோனும், ஞானமிக்கோனும் ஆவான்.)<br />\r\n<br />","text":"அல்லாஹ் கூறுகிறான்: وَاعْلَمُواْ أَنَّ فِيكُمْ رَسُولَ اللَّهِ (மேலும், அறிந்து கொள்ளுங்கள்! நிச்சயமாக அல்லாஹ்வின் தூதர் உங்களிடையே இருக்கிறார்.) அதாவது, அவரைக் கண்ணியப்படுத்தி, அவருக்கு மரியாதை செய்யுங்கள். அவர் உங்களுக்குக் கட்டளையிடுவதற்குப் பணிந்து நடங்கள். ஏனெனில், உங்களுக்கு நன்மை பயப்பவை எவை என்பதை அவர் உங்களைவிட நன்கறிவார். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nالنَّبِىُّ أَوْلَى بِالْمُؤْمِنِينَ مِنْ أَنْفُسِهِمْ\n\r\n\n\r\n(நபி அவர்கள் நம்பிக்கையாளர்களுக்கு அவர்களது உயிர்களை விடவும் நெருக்கமானவர்கள்) (33:6). பின்னர், அவர்கள் தங்களுக்கு எது சிறந்தது என்பதைக் கண்டறிவதில் குறைபாடு உடையவர்களாக இருக்கிறார்கள் என்பதை அவன் தெளிவுபடுத்துகிறான்;\n\r\n\n\r\nلَوْ يُطِيعُكُمْ فِي كَثِيرٍ مِّنَ الْأَمْرِ لَعَنِتُّمْ\n\r\n\n\r\n(7 தொடர்ச்சி - அநேகமான காரியங்களில் அவர் உங்களுக்குக் கீழ்ப்படிந்தால், நிச்சயமாக நீங்கள் சிரமத்திற்கு ஆளாகிவிடுவீர்கள்.) \"அவர் உங்கள் கருத்துக்களுக்கும் விருப்பங்களுக்கும் கட்டுப்பட்டால், நீங்கள் துன்பத்தையும் கஷ்டத்தையுமே அடைவீர்கள்.\" கண்ணியமும் மேன்மையும் மிக்க அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَلَوِ اتَّبَعَ الْحَقُّ أَهْوَاءَهُمْ لَفَسَدَتِ السَّمَاوَاتُ وَالْأَرْضُ وَمَن فِيهِنَّ بَلْ أَتَيْنَاهُمْ بِذِكْرِهِمْ فَهُمْ عَن ذِكْرِهِمْ مُّعْرِضُونَ\n\r\n\n\r\n(சத்தியம் மட்டும் அவர்களுடைய மனோ இச்சைகளைப் பின்பற்றியிருந்தால், வானங்களும் பூமியும் அவற்றில் உள்ளவைகளும் நிச்சயமாகச் சீரழிந்து போயிருக்கும். அவ்வாறன்றி, நாம் அவர்களுக்கு அவர்களுடைய அறிவுரையைக் (குர்ஆனைக்) கொண்டு வந்தோம்; ஆனால் அவர்கள் தங்கள் அறிவுரையிலிருந்து விலகிச் செல்கின்றனர்.) (23:71) அல்லாஹ்வின் கூற்று:\n\r\n\n\r\nوَلَكِنَّ اللَّهَ حَبَّبَ إِلَيْكُمُ الْإِيمَانَ وَزَيَّنَهُ فِي قُلُوبِكُمْ\n\r\n\n\r\n(7 தொடர்ச்சி - எனினும், அல்லாஹ் உங்களுக்கு ஈமானை (நம்பிக்கையை) பிரியமானதாக ஆக்கினான்; அதனை உங்கள் உள்ளங்களில் அழகாக்கினான்.) \"அவன் உங்கள் ஆன்மாக்களுக்கு ஈமானைப் பிரியமானதாக ஆக்கி, உங்கள் இதயங்களில் அதை அலங்கரித்தான்.\" அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَكَرَّهَ إِلَيْكُمُ الْكُفْرَ وَالْفُسُوقَ وَالْعِصْيَانَ\n\r\n\n\r\n(7 தொடர்ச்சி - மேலும் நிராகரிப்பையும், பாவங்களையும் (ஃபுஸூக்), மாறுபாடுகளையும் (இஸ்யான்) உங்களுக்கு வெறுப்பானதாக ஆக்கினான்.) \"அவன் நிராகரிப்பையும், பெரும் பாவங்களையும் (ஃபுஸூக்), மேலும் பெரும் பாவங்கள் அல்லது சிறு பாவங்கள் என அனைத்து வகையான பாவங்களையும் (இஸ்யான்) உங்களுக்கு வெறுப்பானதாக ஆக்கினான்.\" இந்தக் கூற்று, அல்லாஹ்வின் அருட்கொடையைப் பூரணப்படுத்துவதற்காக நம்மை ஒரு நிலையிலிருந்து சிறந்ததொரு நிலைக்குக் கொண்டு செல்கிறது. அடுத்து அல்லாஹ்வின் கூற்று:\n\r\n\n\r\nأُولَئِكَ هُمُ الرَّاشِدُونَ\n\r\n\n\r\n(7 தொடர்ச்சி - இத்தகையவர்களே நேர்வழி பெற்றவர்கள்.) இப்பண்புகளைக் கொண்டவர்களே அல்லாஹ்வினால் நேர்வழியும் சரியான தன்மையும் வழங்கப்பட்ட நேர்வழி பெற்றவர்கள் ஆவர். இமாம் அஹ்மத் அவர்கள் அபூ ரிஃபாஆ அஸ்-ஸுரக்கீ (ரழி) அவர்கள் தம் தந்தை கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"உஹுத் போரின்போது, இணைவைப்பாளர்கள் பின்வாங்கியபோது, அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«اسْتَوُوا حَتَّى أُثْنِيَ عَلَى رَبِّي عَزَّ وَجَل»\n\r\n\n\r\n(நீங்கள் நேராக நில்லுங்கள், நான் கண்ணியமும் மேன்மையும் மிக்க என் இறைவனைப் புகழ வேண்டும்.) அவர்கள் நபி (ஸல்) அவர்களுக்குப் பின்னால் வரிசைகளாக நின்றார்கள். அப்போது அன்னார் (ஸல்) பின்வருமாறு கூறினார்கள்:\n\r\n\n\r\n«اللْهُمَّ لَكَ الْحَمْدُ كُلُّهُ، اللْهُمَّ لَا قَابِضَ لِمَا بَسَطْتَ وَلَا بَاسِطَ لِمَا قَبَضْتَ، وَلَا هَادِيَ لِمَنْ أَضْلَلْتَ، وَلَا مُضِلَّ لِمَنْ هَدَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ وَلَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُقَرِّبَ لِمَا بَاعَدْتَ، وَلَا مُبَاعِدَ لِمَا قَرَّبْتَ. اللْهُمَّ ابْسُطْ عَلَيْنَا مِنْ بَرَكَاتِكَ وَرَحْمَتِكَ وَفَضْلِكَ وَرِزْقِكَ، اللْهُمَّ إِنِّي أَسْأَلُكَ النَّعِيمَ الْمُقِيمَ الَّذِي لَا يَحُولُ وَلَا يَزُولُ. اللْهُمَّ إِنِّي أَسْأَلُكَ النَّعِيمَ يَوْمَ الْعَيْلَةِ وَالْأَمْنَ يَوْمَ الْخَوْفِ. اللْهُمَّ إِنِّي عَائِذٌ بِكَ مِنْ شَرِّ مَا أَعْطَيْتَنَا وَمِنْ شَرِّ مَا مَنَعْتَنَا. اللْهُمَّ حَبِّبْ إِلَيْنَا الْإيمَانَ وَزَيِّنْهُ فِي قُلُوبِنَا وَكَرِّهْ إِلَيْنَا الْكُفْرَ وَالْفُسُوقَ وَالْعِصْيَانَ وَاجْعَلْنَا مِنَ الرَّاشِدِينَ. اللْهُمَّ تَوَفَّنَا مُسْلِمِينَ وَأَحْيِنَا مُسْلِمِينَ وَأَلْحِقْنَا بِالصَّالِحِينَ غَيْرَ خَزَايَا وَلَا مَفْتُونِينَ، اللْهُمَّ قَاتِلِ الْكَفَرَةَ الَّذِينَ يُكَذِّبُونَ رُسُلَكَ وَيَصُدُّونَ عَنْ سَبِيلِكَ وَاجْعَلْ عَلَيْهِمْ رِجْزَكَ وَعَذَابَكَ، اللْهُمَّ قَاتِلِ الْكَفَرَةَ الَّذِينَ أُوتُوا الْكِتَابَ إِلَهَ الْحَقِّ»\n\r\n\n\r\n(யா அல்லாஹ்! புகழனைத்தும் உனக்கே உரியது. யா அல்லாஹ்! நீ விரிப்பதைத் தடுக்க எவரும் இல்லை; நீ சுருக்கியதை விரிக்க எவரும் இல்லை. நீ வழிகெடுத்தவருக்கு நேர்வழி காட்டுபவர் எவரும் இல்லை; நீ நேர்வழி காட்டியவரை வழிகெடுப்பவர் எவரும் இல்லை. நீ தடுத்ததைக் கொடுப்பவர் எவரும் இல்லை; நீ கொடுத்ததைத் தடுப்பவர் எவரும் இல்லை. நீ தூரமாக்கியதை நெருக்கமாக்க எவரும் இல்லை; நீ நெருக்கமாக்கியதைத் தூரமாக்க எவரும் இல்லை. யா அல்லாஹ்! உனது அபிவிருத்திகளையும், கருணையையும், அருளையும், வாழ்வாதாரத்தையும் எங்கள் மீது பொழிவாயாக. யா அல்லாஹ்! என்றுமே மாறாத, அழியாத நிலையான பேரின்பத்தை உன்னிடம் வேண்டுகிறேன். யா அல்லாஹ்! வறுமை ஏற்படும் நாளில் வாழ்வாதாரத்தையும், அச்சம் ஏற்படும் நாளில் பாதுகாப்பையும் உன்னிடம் வேண்டுகிறேன். யா அல்லாஹ்! நீ எங்களுக்கு வழங்கியவற்றின் தீய விளைவுகளிலிருந்தும், நீ எங்களுக்குத் தடுத்தவற்றின் தீமையிலிருந்தும் உன்னிடம் பாதுகாப்புத் தேடுகிறேன். யா அல்லாஹ்! ஈமானை எங்களுக்குப் பிரியமானதாக ஆக்குவாயாக; அதனை எங்கள் உள்ளங்களில் அழகாக்குவாயாக. மேலும் குஃப்ரை (நிராகரிப்பு), பாவங்களை (ஃபுஸூக்), மாறுபாடுகளை (இஸ்யான்) எங்களுக்கு வெறுப்பானதாக ஆக்கி, எங்களை நேர்வழி பெற்றவர்களில் சேர்த்தருள்வாயாக. யா அல்லாஹ்! எங்களை முஸ்லிம்களாக மரணிக்கச் செய்வாயாக; முஸ்லிம்களாக வாழச் செய்வாயாக; எந்தவொரு அவமானத்திற்கும் அல்லது சோதனைகளுக்கும் உள்ளாக்காமல், எங்களை ஸாலிஹீன்களுடன் (நல்லோர்களுடன்) சேர்த்தருள்வாயாக. யா அல்லாஹ்! உனது தூதர்களைப் பொய்யாக்கி, உனது பாதையிலிருந்து மக்களைத் தடுக்கும் அந்த நிராகரிப்பாளர்களுக்கு எதிராகப் போர் புரிவாயாக; அவர்கள் மீது உனது வேதனையையும் தண்டனையையும் இறக்குவாயாக. உண்மையான இறைவனே! வேதம் வழங்கப்பட்டவர்களில் உள்ள நிராகரிப்பாளர்களுக்கு எதிராகப் போர் புரிவாயாக.)\" இமாம் நஸாஈ அவர்கள் இந்த ஹதீஸை 'அமல் அல்-யவ்ம் வல்-லைலா'வில் பதிவு செய்துள்ளார்கள். அல்லாஹ் கூறினான்:\n\r\n\n\r\nفَضْلاً مِّنَ اللَّهِ وَنِعْمَةً وَاللَّهُ عَلِيمٌ حَكِيمٌ\n\r\n\n\r\n(8. இது அல்லாஹ்விடமிருந்துள்ள அருட்கொடையாகவும், பாக்கியமாகவும் இருக்கிறது; மேலும் அல்லாஹ் நன்கறிந்தோனும், ஞானமிக்கோனும் ஆவான்.)"},"8":{"html":"<span class=\"quran-arabic-font text-success\">﴾وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">عَلِيمٌ</span> <span class=\"quran-arabic-font text-success\">حَكِيمٌ﴿</span><br />\r\n<br />\r\n(8-ன் தொடர்ச்சி. மேலும் அல்லாஹ் எல்லாம் அறிந்தவன், மகா ஞானமுடையவன்.) நேர்வழிக்குத் தகுதியானவர்கள் யார் என்பதையும், வழிகேட்டிற்குத் தகுதியானவர்கள் யார் என்பதையும் அவன் நன்கு அறிந்தவன்; தனது கூற்றுகள், செயல்கள், சட்டமியற்றுதல் மற்றும் தான் நிர்ணயிக்கும் விதியிலும் அவன் மகா ஞானமுடையவன்.<br />\r\n<br />\r\n<br />\r\n<br />\r\n<br />\r\n<br />","text":"﴾وَاللَّهُ عَلِيمٌ حَكِيمٌ﴿\n\r\n\n\r\n(8-ன் தொடர்ச்சி. மேலும் அல்லாஹ் எல்லாம் அறிந்தவன், மகா ஞானமுடையவன்.) நேர்வழிக்குத் தகுதியானவர்கள் யார் என்பதையும், வழிகேட்டிற்குத் தகுதியானவர்கள் யார் என்பதையும் அவன் நன்கு அறிந்தவன்; தனது கூற்றுகள், செயல்கள், சட்டமியற்றுதல் மற்றும் தான் நிர்ணயிக்கும் விதியிலும் அவன் மகா ஞானமுடையவன்."},"9":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=49&ayah=10\" class=\"link\">49:10</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 49:10 ஐ பார்க்கவும்"},"10":{"html":"<strong>சண்டையிட்டுக் கொள்ளும் முஸ்லிம்களிடையே சமாதானம் ஏற்படுத்துதல்</strong><br />\r\n<br />\r\n<br />\r\nதங்களுக்குள் சண்டையிட்டுக் கொள்ளும் முஸ்லிம்களிடையே சமாதானம் செய்யுமாறு அல்லாஹ் கட்டளையிடுகிறான்,<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِن</span> <span class=\"quran-arabic-font text-success\">طَائِفَتَانِ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">اقْتَتَلُواْ</span> <span class=\"quran-arabic-font text-success\">فَأَصْلِحُواْ</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمَا</span><br />\r\n<br />\r\n<br />\r\n(இறைநம்பிக்கையாளர்களில் இரு பிரிவினர் தங்களுக்குள் சண்டையிட்டுக் கொண்டால், அவ்விருவருக்கும் இடையில் சமாதானம் செய்து வையுங்கள்.) எனவே, தங்களுக்குள் சண்டையிட்டுக் கொண்டாலும், முஸ்லிம்களிடையே எதிர் எதிராக இருக்கும் இரு குழுவினரையும் அல்லாஹ் 'இறைநம்பிக்கையாளர்கள்' (முஃமின்கள்) என்றே அழைக்கிறான். ஒரு பாவம் எவ்வளவு பெரியதாக இருந்தாலும், அதைச் செய்வது ஒருவரின் ஈமானை (நம்பிக்கையை) நீக்கிவிடாது என்பதற்கு ஆதாரமாக இமாம் புகாரி அவர்களும் ஏனைய அறிஞர்களும் இந்த வசனத்தைச் சான்றாகக் கொள்கின்றனர். இந்தக் கொள்கையானது கவாரிஜ் பிரிவினரின் கொள்கைக்கும், முஃதஸிலா போன்ற அவர்களின் கருத்தை ஏற்றுக் கொண்டவர்களின் கொள்கைக்கும் முரணானது. அபுபக்ரா (ரழி) அவர்கள் கூறியதாக ஹஸன் பஸரீ (ரஹ்) அவர்கள் அறிவிப்பதாவது: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மிம்பரின் மீது உரையாற்றிக் கொண்டிருந்தபோது ஹஸன் பின் அலீ (ரழி) அவர்கள் அவர்களுடன் இருந்தார்கள் என இமாம் புகாரி அவர்கள் பதிவு செய்துள்ளார்கள். நபி (ஸல்) அவர்கள் ஒருமுறை ஹஸன் (ரழி) அவர்களையும், ஒருமுறை மக்களையும் மாறி மாறிப் பார்த்தவாறு பின்வருமாறு கூறினார்கள்:<br />\r\n<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">ابْنِي</span> <span class=\"quran-arabic-font text-success\">هذَا</span> <span class=\"quran-arabic-font text-success\">سَيِّدٌ</span> <span class=\"quran-arabic-font text-success\">وَلَعَلَّ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">تَعَالَى</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يُصْلِحَ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">فِئَتَيْنِ</span> <span class=\"quran-arabic-font text-success\">عَظِيمَتَيْنِ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُسْلِمِين</span>»<br />\r\n<br />\r\n<br />\r\n(நிச்சயமாக, எனது இந்த மகன் ஒரு ஸையித் (தலைவர்) ஆவார்; இவரைக் கொண்டு முஸ்லிம்களின் இரு பெரும் பிரிவினருக்கிடையில் அல்லாஹ் சமாதானத்தை ஏற்படுத்தக்கூடும்.) நபி (ஸல்) அவர்கள் கூறியது போலவே நடந்தது. அஷ்-ஷாம் மற்றும் ஈராக் மக்களுக்கு இடையே பெரும் போர்களும் அச்சமூட்டும் சண்டைகளும் நிகழ்ந்த பிறகு, ஹஸன் (ரழி) அவர்கள் அவ்விரு பிரிவினரிடையே சமாதானத்தை ஏற்படுத்தினார்கள். அல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَإِن</span> <span class=\"quran-arabic-font text-success\">بَغَتْ</span> <span class=\"quran-arabic-font text-success\">إِحْدَاهُمَا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الأُخْرَى</span> <span class=\"quran-arabic-font text-success\">فَقَاتِلُوا</span> <span class=\"quran-arabic-font text-success\">الَّتِى</span> <span class=\"quran-arabic-font text-success\">تَبْغِى</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">تَفِيءَ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">أَمْرِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span><br />\r\n<br />\r\n<br />\r\n(அவர்களில் ஒரு பிரிவினர் மற்றவர் மீது வரம்பு மீறினால், வரம்பு மீறிய அந்தப் பிரிவினர் அல்லாஹ்வின் கட்டளையின் பக்கம் திரும்பும் வரை அவர்களுடன் போரிடுங்கள்.) அதாவது, கலகம் செய்யும் அந்தப் பிரிவினர் அல்லாஹ்வின் மற்றும் அவனது தூதரின் கட்டளைகளின்படி தீர்ப்புப் பெறத் திரும்பும் வரையிலும், அவர்கள் உண்மையைக் கேட்டு அதற்குக் கீழ்ப்படியும் வரையிலும் (போரிடுங்கள்) என்பதாகும். ஸஹீஹ் புகாரியில் அனஸ் (ரழி) அவர்கள் அறிவிக்கும் ஒரு ஹதீஸில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பின்வருமாறு கூறினார்கள்:<br />\r\n<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">انْصُرْ</span> <span class=\"quran-arabic-font text-success\">أَخَاكَ</span> <span class=\"quran-arabic-font text-success\">ظَالِمًا</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">مَظْلُومًا</span>»<br />\r\n<br />\r\n<br />\r\n(உனது சகோதரன் அநியாயம் செய்பவனாக இருந்தாலும் அல்லது அநியாயம் இழைக்கப்பட்டவனாக இருந்தாலும் அவனுக்கு உதவி செய்.) \"அல்லாஹ்வின் தூதரே! அநியாயம் இழைக்கப்பட்டவருக்கு நான் உதவி செய்வது சரி, ஆனால் அநியாயம் செய்பவருக்கு நான் எப்படி உதவி செய்வது?\" என்று கேட்டேன். அதற்கு அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">تَمْنَعُهُ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الظُّلْمِ</span> <span class=\"quran-arabic-font text-success\">فَذَاكَ</span> <span class=\"quran-arabic-font text-success\">نَصْرُكَ</span> <span class=\"quran-arabic-font text-success\">إِيَّاه</span>»<br />\r\n<br />\r\n<br />\r\n(அவர் அநியாயம் செய்வதிலிருந்து அவரைத் தடுப்பதே நீ அவருக்குச் செய்யும் உதவியாகும்.)\" ஸயீத் பின் ஜுபைர் (ரஹ்) அவர்கள் கூறினார்கள்: ஒருமுறை அவ்ஸ் மற்றும் கஸ்ரஜ் கோத்திரத்தினர் பேரீச்சை மட்டைகளாலும் செருப்புகளாலும் ஒருவருக்கொருவர் மோதிக் கொண்டனர். அவர்களுக்கு இடையே சமாதானம் செய்யுமாறு கட்டளையிட்டு, கண்ணியமிக்க இந்த வசனத்தை (ஆயத்தை) அல்லாஹ் இறக்கினான். அஸ்-ஸுத்தி (ரஹ்) அவர்கள் கூறினார்கள்: \"அன்சாரிகளில் இம்ரான் என்பவருக்கு உம்மு ஸைத் என்ற மனைவி இருந்தார். அவர் தனது குடும்பத்தினரைச் சந்திக்க விரும்பினார். ஆனால் அவரது கணவர் அவரை ஒரு மேல் அறையில் பூட்டி வைத்து அவரைப் பார்ப்பதைத் தடுத்தார். இதனால் அவரது குடும்பத்தினர் யாராலும் அவரைப் பார்க்கவோ சந்திக்கவோ முடியவில்லை. அவர் தனது குடும்பத்தினருக்கு ஒருவரைத் தூதாக அனுப்பினார். அவர்கள் வந்து அவரை அறையிலிருந்து கீழே இறக்கி அழைத்துச் செல்ல முயன்றனர். அப்போது கணவர் அங்கில்லை, எனவே கணவரின் குடும்பத்தினர் தங்கள் உறவினர்களை உதவிக்கு அழைத்தனர். மனைவியின் குடும்பத்தினர் அவரை அழைத்துச் செல்வதைத் தடுக்க உறவினர்கள் வந்தனர். இதனால் ஏற்பட்ட தள்ளுமுள்ளு, அவர்கள் செருப்புகளால் சண்டையிடும் அளவிற்குச் சென்றது. இவர்களது விஷயத்திலேயே இந்த வசனம் இறக்கப்பட்டது. நபி (ஸல்) அவர்கள் அவர்களிடையே சமாதானம் செய்ய ஒருவரை அனுப்பினார்கள். அவர்கள் அனைவரும் உயர்ந்தோனாகிய அல்லாஹ்வின் தீர்ப்பிற்கு கட்டுப்பட இணங்கினார்கள்.\" அடுத்ததாக, உயர்ந்தோனாகிய அல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَإِن</span> <span class=\"quran-arabic-font text-success\">فَاءَتْ</span> <span class=\"quran-arabic-font text-success\">فَأَصْلِحُواْ</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمَا</span> <span class=\"quran-arabic-font text-success\">بِالْعَدْلِ</span> <span class=\"quran-arabic-font text-success\">وَأَقْسِطُواْ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">يُحِبُّ</span> <span class=\"quran-arabic-font text-success\">الْمُقْسِطِينَ</span><br />\r\n<br />\r\n<br />\r\n(பிறகு அந்தப் பிரிவு இணங்கிவிட்டால், அவ்விருவருக்கும் இடையே நீதியுடன் சமரசம் செய்யுங்கள்; மேலும் நேர்மையாக நடந்து கொள்ளுங்கள். நிச்சயமாக, அல்லாஹ் நேர்மையாளர்களை நேசிக்கிறான்.) அதாவது, அவர்களிடையே ஏற்பட்ட பிணக்கில் உங்கள் தீர்ப்பின்போது நீதியாக நடந்து கொள்ளுங்கள் என்பதாகும்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">يُحِبُّ</span> <span class=\"quran-arabic-font text-success\">الْمُقْسِطِينَ</span><br />\r\n<br />\r\n<br />\r\n(நிச்சயமாக, அல்லாஹ் நேர்மையாளர்களை நேசிக்கிறான்.) அப்துல்லாஹ் பின் அம்ர் (ரழி) அவர்கள் அறிவிக்கிறார்கள், நபி (ஸல்) அவர்கள் கூறினார்கள் என இப்னு அபீ ஹாதிம் பதிவு செய்துள்ளார்கள்:<br />\r\n<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الْمُقْسِطِينَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">مَنَابِرَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">لُؤْلُؤٍ</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">يَدَيِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمنِ</span> <span class=\"quran-arabic-font text-success\">عَزَّ</span> <span class=\"quran-arabic-font text-success\">وَجَلَّ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">أَقْسَطُوا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span>»<br />\r\n<br />\r\n<br />\r\n(நிச்சயமாக இவ்வுலகில் நேர்மையாக நடந்தவர்கள், அவர்கள் காட்டிய நேர்மையின் காரணமாக, மறுமையில் அளவற்ற அருளாளனான அர்-ரஹ்மானின் முன்னிலையில் முத்துக்களால் ஆன மேடைகளில் அமர்த்தப்படுவார்கள்.) இமாம் நஸாயீ அவர்களும் இந்த ஹதீஸைப் பதிவு செய்துள்ளார்கள். அல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّمَا</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنُونَ</span> <span class=\"quran-arabic-font text-success\">إِخْوَةٌ</span><br />\r\n<br />\r\n<br />\r\n(இறைநம்பிக்கையாளர்கள் அனைவரும் சகோதரர்களே.) அதாவது, அவர்கள் அனைவரும் இஸ்லாமிய அடிப்படையில் சகோதரர்கள் ஆவர். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">الْمُسْلِمُ</span> <span class=\"quran-arabic-font text-success\">أَخُو</span> <span class=\"quran-arabic-font text-success\">الْمُسْلِمِ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَظْلِمُهُ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">يُسْلِمُه</span>»<br />\r\n<br />\r\n<br />\r\n(ஒரு முஸ்லிம் மற்றொரு முஸ்லிமின் சகோதரர் ஆவார். அவர் தனது சகோதரருக்கு அநீதி இழைக்க மாட்டார்; அவரைத் துயரத்தில் கைவிடவும் மாட்டார்.) ஸஹீஹ் முஸ்லிமில் உள்ளது:<br />\r\n<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">وَاللهُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">عَوْنِ</span> <span class=\"quran-arabic-font text-success\">الْعَبْدِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">الْعَبْدُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">عَوْنِ</span> <span class=\"quran-arabic-font text-success\">أَخِيه</span>»<br />\r\n<br />\r\n<br />\r\n(ஓர் அடியான் தனது சகோதரருக்கு உதவி செய்யும் காலமெல்லாம், அல்லாஹ் அந்த அடியானுக்கு உதவி செய்து கொண்டிருக்கிறான்.) மேலும் ஸஹீஹ் முஸ்லிமில் உள்ளது:<br />\r\n<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">دَعَا</span> <span class=\"quran-arabic-font text-success\">الْمُسْلِمُ</span> <span class=\"quran-arabic-font text-success\">لِأَخِيهِ</span> <span class=\"quran-arabic-font text-success\">بِظَهْرِ</span> <span class=\"quran-arabic-font text-success\">الْغَيْبِ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">الْمَلَكُ</span>: <span class=\"quran-arabic-font text-success\">آمِينَ</span> <span class=\"quran-arabic-font text-success\">وَلَكَ</span> <span class=\"quran-arabic-font text-success\">بِمِثْلِه</span>»<br />\r\n<br />\r\n<br />\r\n(ஒரு முஸ்லிம் தனது சகோதரர் இல்லாதபோது அவருக்காகப் பிரார்த்தித்தால், அதற்கு வானவர் \"ஆமீன், உமக்கும் அது போன்றே கிடைக்கட்டும்\" என்று கூறுகிறார்.) இது போன்ற பொருளில் பல ஹதீஸ்கள் உள்ளன. உதாரணமாக ஸஹீஹ் புகாரி மற்றும் முஸ்லிமில் உள்ளது:<br />\r\n<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مَثَلُ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">تَوَادِّهِمْ</span> <span class=\"quran-arabic-font text-success\">وَتَرَاحُمِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَتَعَاطُفِهِمْ</span> <span class=\"quran-arabic-font text-success\">كَمَثَلِ</span> <span class=\"quran-arabic-font text-success\">الْجَسَدِ</span> <span class=\"quran-arabic-font text-success\">الْوَاحِدِ،</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">اشْتَكَى</span> <span class=\"quran-arabic-font text-success\">مِنْهُ</span> <span class=\"quran-arabic-font text-success\">عُضْوٌ</span> <span class=\"quran-arabic-font text-success\">تَدَاعَى</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">سَائِرُ</span> <span class=\"quran-arabic-font text-success\">الْجَسَدِ</span> <span class=\"quran-arabic-font text-success\">بِالْحُمَّى</span> <span class=\"quran-arabic-font text-success\">وَالسَّهَر</span>»<br />\r\n<br />\r\n<br />\r\n(இறைநம்பிக்கையாளர்கள் ஒருவருக்கொருவர் காட்டும் அன்பு, கருணை மற்றும் இரக்கம் ஆகியவற்றிற்கு உவமை ஒரு உடலைப் போன்றது. உடலில் ஒரு உறுப்பு பாதிக்கப்பட்டால், உடல் முழுவதும் காய்ச்சலாலும் தூக்கமின்மையாலும் அதற்காகத் துடிக்கிறது.) மேலும் ஸஹீஹில் உள்ளது:<br />\r\n<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">الْمُؤْمِنُ</span> <span class=\"quran-arabic-font text-success\">لِلْمُؤْمِنِ</span> <span class=\"quran-arabic-font text-success\">كَالْبُنْيَانِ</span> <span class=\"quran-arabic-font text-success\">يَشُدُّ</span> <span class=\"quran-arabic-font text-success\">بَعْضُهُ</span> <span class=\"quran-arabic-font text-success\">بَعْضًا</span>»<br />\r\n<br />\r\n<br />\r\n(ஓர் இறைநம்பிக்கையாளர் மற்றோர் இறைநம்பிக்கையாளருக்கு ஒரு கட்டிடத்தைப் போன்றவர் ஆவார். அதன் ஒரு பகுதி மற்றொன்றை வலுப்படுத்துகிறது.) பின்னர் நபி (ஸல்) அவர்கள் தனது இரு கைகளின் விரல்களை ஒன்றோடொன்று கோர்த்துக் காட்டினார்கள். அல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأَصْلِحُواْ</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">أَخَوَيْكُمْ</span><br />\r\n<br />\r\n<br />\r\n(எனவே, உங்கள் சகோதரர்களிடையே சமரசம் செய்யுங்கள்,) என்பது சண்டையிட்டுக் கொள்ளும் இரு தரப்பினரைக் குறிக்கிறது.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاتَّقُواْ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span><br />\r\n<br />\r\n<br />\r\n(மேலும் அல்லாஹ்வுக்கு அஞ்சுங்கள் (தக்வா கொள்ளுங்கள்),) உங்கள் காரியங்கள் அனைத்திலும்,<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَعَلَّكُمْ</span> <span class=\"quran-arabic-font text-success\">تُرْحَمُونَ</span><br />\r\n<br />\r\n<br />\r\n(அதன் மூலம் நீங்கள் அவனது அருளைப் பெறலாம்.) இது அல்லாஹ்வுக்கு அஞ்சி அவனுக்குக் கீழ்ப்படிந்து நடப்போருக்கு அவனது அருள் கிடைக்கும் என்பதற்கான அல்லாஹ்விடமிருந்து வந்த வாக்குறுதியாகும்.<br />\r\n<br />","text":"சண்டையிட்டுக் கொள்ளும் முஸ்லிம்களிடையே சமாதானம் ஏற்படுத்துதல்\n\r\n\n\r\n\n\r\nதங்களுக்குள் சண்டையிட்டுக் கொள்ளும் முஸ்லிம்களிடையே சமாதானம் செய்யுமாறு அல்லாஹ் கட்டளையிடுகிறான்,\n\r\n\n\r\n\n\r\nوَإِن طَائِفَتَانِ مِنَ الْمُؤْمِنِينَ اقْتَتَلُواْ فَأَصْلِحُواْ بَيْنَهُمَا\n\r\n\n\r\n\n\r\n(இறைநம்பிக்கையாளர்களில் இரு பிரிவினர் தங்களுக்குள் சண்டையிட்டுக் கொண்டால், அவ்விருவருக்கும் இடையில் சமாதானம் செய்து வையுங்கள்.) எனவே, தங்களுக்குள் சண்டையிட்டுக் கொண்டாலும், முஸ்லிம்களிடையே எதிர் எதிராக இருக்கும் இரு குழுவினரையும் அல்லாஹ் 'இறைநம்பிக்கையாளர்கள்' (முஃமின்கள்) என்றே அழைக்கிறான். ஒரு பாவம் எவ்வளவு பெரியதாக இருந்தாலும், அதைச் செய்வது ஒருவரின் ஈமானை (நம்பிக்கையை) நீக்கிவிடாது என்பதற்கு ஆதாரமாக இமாம் புகாரி அவர்களும் ஏனைய அறிஞர்களும் இந்த வசனத்தைச் சான்றாகக் கொள்கின்றனர். இந்தக் கொள்கையானது கவாரிஜ் பிரிவினரின் கொள்கைக்கும், முஃதஸிலா போன்ற அவர்களின் கருத்தை ஏற்றுக் கொண்டவர்களின் கொள்கைக்கும் முரணானது. அபுபக்ரா (ரழி) அவர்கள் கூறியதாக ஹஸன் பஸரீ (ரஹ்) அவர்கள் அறிவிப்பதாவது: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மிம்பரின் மீது உரையாற்றிக் கொண்டிருந்தபோது ஹஸன் பின் அலீ (ரழி) அவர்கள் அவர்களுடன் இருந்தார்கள் என இமாம் புகாரி அவர்கள் பதிவு செய்துள்ளார்கள். நபி (ஸல்) அவர்கள் ஒருமுறை ஹஸன் (ரழி) அவர்களையும், ஒருமுறை மக்களையும் மாறி மாறிப் பார்த்தவாறு பின்வருமாறு கூறினார்கள்:\n\r\n\n\r\n\n\r\n«إِنَّ ابْنِي هذَا سَيِّدٌ وَلَعَلَّ اللهَ تَعَالَى أَنْ يُصْلِحَ بِهِ بَيْنَ فِئَتَيْنِ عَظِيمَتَيْنِ مِنَ الْمُسْلِمِين»\n\r\n\n\r\n\n\r\n(நிச்சயமாக, எனது இந்த மகன் ஒரு ஸையித் (தலைவர்) ஆவார்; இவரைக் கொண்டு முஸ்லிம்களின் இரு பெரும் பிரிவினருக்கிடையில் அல்லாஹ் சமாதானத்தை ஏற்படுத்தக்கூடும்.) நபி (ஸல்) அவர்கள் கூறியது போலவே நடந்தது. அஷ்-ஷாம் மற்றும் ஈராக் மக்களுக்கு இடையே பெரும் போர்களும் அச்சமூட்டும் சண்டைகளும் நிகழ்ந்த பிறகு, ஹஸன் (ரழி) அவர்கள் அவ்விரு பிரிவினரிடையே சமாதானத்தை ஏற்படுத்தினார்கள். அல்லாஹ்வின் கூற்று:\n\r\n\n\r\n\n\r\nفَإِن بَغَتْ إِحْدَاهُمَا عَلَى الأُخْرَى فَقَاتِلُوا الَّتِى تَبْغِى حَتَّى تَفِيءَ إِلَى أَمْرِ اللَّهِ\n\r\n\n\r\n\n\r\n(அவர்களில் ஒரு பிரிவினர் மற்றவர் மீது வரம்பு மீறினால், வரம்பு மீறிய அந்தப் பிரிவினர் அல்லாஹ்வின் கட்டளையின் பக்கம் திரும்பும் வரை அவர்களுடன் போரிடுங்கள்.) அதாவது, கலகம் செய்யும் அந்தப் பிரிவினர் அல்லாஹ்வின் மற்றும் அவனது தூதரின் கட்டளைகளின்படி தீர்ப்புப் பெறத் திரும்பும் வரையிலும், அவர்கள் உண்மையைக் கேட்டு அதற்குக் கீழ்ப்படியும் வரையிலும் (போரிடுங்கள்) என்பதாகும். ஸஹீஹ் புகாரியில் அனஸ் (ரழி) அவர்கள் அறிவிக்கும் ஒரு ஹதீஸில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பின்வருமாறு கூறினார்கள்:\n\r\n\n\r\n\n\r\n«انْصُرْ أَخَاكَ ظَالِمًا أَوْ مَظْلُومًا»\n\r\n\n\r\n\n\r\n(உனது சகோதரன் அநியாயம் செய்பவனாக இருந்தாலும் அல்லது அநியாயம் இழைக்கப்பட்டவனாக இருந்தாலும் அவனுக்கு உதவி செய்.) \"அல்லாஹ்வின் தூதரே! அநியாயம் இழைக்கப்பட்டவருக்கு நான் உதவி செய்வது சரி, ஆனால் அநியாயம் செய்பவருக்கு நான் எப்படி உதவி செய்வது?\" என்று கேட்டேன். அதற்கு அவர்கள் கூறினார்கள்:\n\r\n\n\r\n\n\r\n«تَمْنَعُهُ مِنَ الظُّلْمِ فَذَاكَ نَصْرُكَ إِيَّاه»\n\r\n\n\r\n\n\r\n(அவர் அநியாயம் செய்வதிலிருந்து அவரைத் தடுப்பதே நீ அவருக்குச் செய்யும் உதவியாகும்.)\" ஸயீத் பின் ஜுபைர் (ரஹ்) அவர்கள் கூறினார்கள்: ஒருமுறை அவ்ஸ் மற்றும் கஸ்ரஜ் கோத்திரத்தினர் பேரீச்சை மட்டைகளாலும் செருப்புகளாலும் ஒருவருக்கொருவர் மோதிக் கொண்டனர். அவர்களுக்கு இடையே சமாதானம் செய்யுமாறு கட்டளையிட்டு, கண்ணியமிக்க இந்த வசனத்தை (ஆயத்தை) அல்லாஹ் இறக்கினான். அஸ்-ஸுத்தி (ரஹ்) அவர்கள் கூறினார்கள்: \"அன்சாரிகளில் இம்ரான் என்பவருக்கு உம்மு ஸைத் என்ற மனைவி இருந்தார். அவர் தனது குடும்பத்தினரைச் சந்திக்க விரும்பினார். ஆனால் அவரது கணவர் அவரை ஒரு மேல் அறையில் பூட்டி வைத்து அவரைப் பார்ப்பதைத் தடுத்தார். இதனால் அவரது குடும்பத்தினர் யாராலும் அவரைப் பார்க்கவோ சந்திக்கவோ முடியவில்லை. அவர் தனது குடும்பத்தினருக்கு ஒருவரைத் தூதாக அனுப்பினார். அவர்கள் வந்து அவரை அறையிலிருந்து கீழே இறக்கி அழைத்துச் செல்ல முயன்றனர். அப்போது கணவர் அங்கில்லை, எனவே கணவரின் குடும்பத்தினர் தங்கள் உறவினர்களை உதவிக்கு அழைத்தனர். மனைவியின் குடும்பத்தினர் அவரை அழைத்துச் செல்வதைத் தடுக்க உறவினர்கள் வந்தனர். இதனால் ஏற்பட்ட தள்ளுமுள்ளு, அவர்கள் செருப்புகளால் சண்டையிடும் அளவிற்குச் சென்றது. இவர்களது விஷயத்திலேயே இந்த வசனம் இறக்கப்பட்டது. நபி (ஸல்) அவர்கள் அவர்களிடையே சமாதானம் செய்ய ஒருவரை அனுப்பினார்கள். அவர்கள் அனைவரும் உயர்ந்தோனாகிய அல்லாஹ்வின் தீர்ப்பிற்கு கட்டுப்பட இணங்கினார்கள்.\" அடுத்ததாக, உயர்ந்தோனாகிய அல்லாஹ்வின் கூற்று:\n\r\n\n\r\n\n\r\nفَإِن فَاءَتْ فَأَصْلِحُواْ بَيْنَهُمَا بِالْعَدْلِ وَأَقْسِطُواْ إِنَّ اللَّهَ يُحِبُّ الْمُقْسِطِينَ\n\r\n\n\r\n\n\r\n(பிறகு அந்தப் பிரிவு இணங்கிவிட்டால், அவ்விருவருக்கும் இடையே நீதியுடன் சமரசம் செய்யுங்கள்; மேலும் நேர்மையாக நடந்து கொள்ளுங்கள். நிச்சயமாக, அல்லாஹ் நேர்மையாளர்களை நேசிக்கிறான்.) அதாவது, அவர்களிடையே ஏற்பட்ட பிணக்கில் உங்கள் தீர்ப்பின்போது நீதியாக நடந்து கொள்ளுங்கள் என்பதாகும்.\n\r\n\n\r\n\n\r\nإِنَّ اللَّهَ يُحِبُّ الْمُقْسِطِينَ\n\r\n\n\r\n\n\r\n(நிச்சயமாக, அல்லாஹ் நேர்மையாளர்களை நேசிக்கிறான்.) அப்துல்லாஹ் பின் அம்ர் (ரழி) அவர்கள் அறிவிக்கிறார்கள், நபி (ஸல்) அவர்கள் கூறினார்கள் என இப்னு அபீ ஹாதிம் பதிவு செய்துள்ளார்கள்:\n\r\n\n\r\n\n\r\n«إِنَّ الْمُقْسِطِينَ فِي الدُّنْيَا عَلَى مَنَابِرَ مِنْ لُؤْلُؤٍ بَيْنَ يَدَيِ الرَّحْمنِ عَزَّ وَجَلَّ بِمَا أَقْسَطُوا فِي الدُّنْيَا»\n\r\n\n\r\n\n\r\n(நிச்சயமாக இவ்வுலகில் நேர்மையாக நடந்தவர்கள், அவர்கள் காட்டிய நேர்மையின் காரணமாக, மறுமையில் அளவற்ற அருளாளனான அர்-ரஹ்மானின் முன்னிலையில் முத்துக்களால் ஆன மேடைகளில் அமர்த்தப்படுவார்கள்.) இமாம் நஸாயீ அவர்களும் இந்த ஹதீஸைப் பதிவு செய்துள்ளார்கள். அல்லாஹ்வின் கூற்று:\n\r\n\n\r\n\n\r\nإِنَّمَا الْمُؤْمِنُونَ إِخْوَةٌ\n\r\n\n\r\n\n\r\n(இறைநம்பிக்கையாளர்கள் அனைவரும் சகோதரர்களே.) அதாவது, அவர்கள் அனைவரும் இஸ்லாமிய அடிப்படையில் சகோதரர்கள் ஆவர். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n\n\r\n«الْمُسْلِمُ أَخُو الْمُسْلِمِ لَا يَظْلِمُهُ وَلَا يُسْلِمُه»\n\r\n\n\r\n\n\r\n(ஒரு முஸ்லிம் மற்றொரு முஸ்லிமின் சகோதரர் ஆவார். அவர் தனது சகோதரருக்கு அநீதி இழைக்க மாட்டார்; அவரைத் துயரத்தில் கைவிடவும் மாட்டார்.) ஸஹீஹ் முஸ்லிமில் உள்ளது:\n\r\n\n\r\n\n\r\n«وَاللهُ فِي عَوْنِ الْعَبْدِ مَا كَانَ الْعَبْدُ فِي عَوْنِ أَخِيه»\n\r\n\n\r\n\n\r\n(ஓர் அடியான் தனது சகோதரருக்கு உதவி செய்யும் காலமெல்லாம், அல்லாஹ் அந்த அடியானுக்கு உதவி செய்து கொண்டிருக்கிறான்.) மேலும் ஸஹீஹ் முஸ்லிமில் உள்ளது:\n\r\n\n\r\n\n\r\n«إِذَا دَعَا الْمُسْلِمُ لِأَخِيهِ بِظَهْرِ الْغَيْبِ قَالَ الْمَلَكُ: آمِينَ وَلَكَ بِمِثْلِه»\n\r\n\n\r\n\n\r\n(ஒரு முஸ்லிம் தனது சகோதரர் இல்லாதபோது அவருக்காகப் பிரார்த்தித்தால், அதற்கு வானவர் \"ஆமீன், உமக்கும் அது போன்றே கிடைக்கட்டும்\" என்று கூறுகிறார்.) இது போன்ற பொருளில் பல ஹதீஸ்கள் உள்ளன. உதாரணமாக ஸஹீஹ் புகாரி மற்றும் முஸ்லிமில் உள்ளது:\n\r\n\n\r\n\n\r\n«مَثَلُ الْمُؤْمِنِينَ فِي تَوَادِّهِمْ وَتَرَاحُمِهِمْ وَتَعَاطُفِهِمْ كَمَثَلِ الْجَسَدِ الْوَاحِدِ، إِذَا اشْتَكَى مِنْهُ عُضْوٌ تَدَاعَى لَهُ سَائِرُ الْجَسَدِ بِالْحُمَّى وَالسَّهَر»\n\r\n\n\r\n\n\r\n(இறைநம்பிக்கையாளர்கள் ஒருவருக்கொருவர் காட்டும் அன்பு, கருணை மற்றும் இரக்கம் ஆகியவற்றிற்கு உவமை ஒரு உடலைப் போன்றது. உடலில் ஒரு உறுப்பு பாதிக்கப்பட்டால், உடல் முழுவதும் காய்ச்சலாலும் தூக்கமின்மையாலும் அதற்காகத் துடிக்கிறது.) மேலும் ஸஹீஹில் உள்ளது:\n\r\n\n\r\n\n\r\n«الْمُؤْمِنُ لِلْمُؤْمِنِ كَالْبُنْيَانِ يَشُدُّ بَعْضُهُ بَعْضًا»\n\r\n\n\r\n\n\r\n(ஓர் இறைநம்பிக்கையாளர் மற்றோர் இறைநம்பிக்கையாளருக்கு ஒரு கட்டிடத்தைப் போன்றவர் ஆவார். அதன் ஒரு பகுதி மற்றொன்றை வலுப்படுத்துகிறது.) பின்னர் நபி (ஸல்) அவர்கள் தனது இரு கைகளின் விரல்களை ஒன்றோடொன்று கோர்த்துக் காட்டினார்கள். அல்லாஹ்வின் கூற்று:\n\r\n\n\r\n\n\r\nفَأَصْلِحُواْ بَيْنَ أَخَوَيْكُمْ\n\r\n\n\r\n\n\r\n(எனவே, உங்கள் சகோதரர்களிடையே சமரசம் செய்யுங்கள்,) என்பது சண்டையிட்டுக் கொள்ளும் இரு தரப்பினரைக் குறிக்கிறது.\n\r\n\n\r\n\n\r\nوَاتَّقُواْ اللَّهَ\n\r\n\n\r\n\n\r\n(மேலும் அல்லாஹ்வுக்கு அஞ்சுங்கள் (தக்வா கொள்ளுங்கள்),) உங்கள் காரியங்கள் அனைத்திலும்,\n\r\n\n\r\n\n\r\nلَعَلَّكُمْ تُرْحَمُونَ\n\r\n\n\r\n\n\r\n(அதன் மூலம் நீங்கள் அவனது அருளைப் பெறலாம்.) இது அல்லாஹ்வுக்கு அஞ்சி அவனுக்குக் கீழ்ப்படிந்து நடப்போருக்கு அவனது அருள் கிடைக்கும் என்பதற்கான அல்லாஹ்விடமிருந்து வந்த வாக்குறுதியாகும்."},"11":{"html":"<strong>ஒருவரை ஒருவர் கேலி செய்வதும் ஏளனம் செய்வதும் தடைசெய்யப்பட்டுள்ளது</strong><br />\r\n<br />\r\nமேன்மைமிக்க அல்லாஹ் மக்களை ஏளனம் செய்வதைத் தடை செய்கிறான்; இது அவர்களை அவமதிப்பதையும் இழிவுபடுத்துவதையும் குறிக்கிறது. ஸஹீஹ் (முஸ்லிம்) நூலில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள் எனப் பதிவு செய்யப்பட்டுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">الْكِبْرُ</span> <span class=\"quran-arabic-font text-success\">بَطَرُ</span> <span class=\"quran-arabic-font text-success\">الْحَقِّ</span> <span class=\"quran-arabic-font text-success\">وَغَمْصُ</span> <span class=\"quran-arabic-font text-success\">النَّاس</span>»<br />\r\n<br />\r\n(பெருமை என்பது சத்தியத்தை மறுப்பதும், மக்களை இழிவுபடுத்துவதும் ஆகும்.) மற்றொரு அறிவிப்பில்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">غَمْطُ</span> <span class=\"quran-arabic-font text-success\">النَّاس</span>»<br />\r\n<br />\r\n(மக்களை இகழ்வதும் ஆகும்). மக்களை ஏளனம் செய்வதும் இழிவுபடுத்துவதும் விலக்கப்பட்டுள்ளது. ஏனெனில், பாதிக்கப்பட்டவர் ஏளனம் செய்பவர்களை விட மேன்மைமிக்க அல்லாஹ்விடம் அதிக கண்ணியமானவராகவும் அவனுக்கு மிகவும் பிரியமானவராகவும் இருக்கக்கூடும். இதனால்தான் மேன்மைமிக்க அல்லாஹ் இவ்வாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يأَيُّهَا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَسْخَرْ</span> <span class=\"quran-arabic-font text-success\">قَوْمٌ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">قَوْمٍ</span> <span class=\"quran-arabic-font text-success\">عَسَى</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَكُونُواْ</span> <span class=\"quran-arabic-font text-success\">خَيْراً</span> <span class=\"quran-arabic-font text-success\">مِّنْهُمْ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">نِسَآءٌ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">نِّسَآءٍ</span> <span class=\"quran-arabic-font text-success\">عَسَى</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَكُنَّ</span> <span class=\"quran-arabic-font text-success\">خَيْراً</span> <span class=\"quran-arabic-font text-success\">مِّنْهُنَّ</span><br />\r\n<br />\r\n(நம்பிக்கையாளர்களே! ஒரு சமூகத்தினர் மற்றொரு சமூகத்தினரை ஏளனம் செய்ய வேண்டாம்; அவர்கள் (ஏளனம் செய்யப்பட்டவர்கள்) இவர்களை விடச் சிறந்தவர்களாக இருக்கக்கூடும். எந்தப் பெண்களும் மற்றப் பெண்களை ஏளனம் செய்ய வேண்டாம்; அவர்கள் இவர்களை விடச் சிறந்தவர்களாக இருக்கக்கூடும்.) இவ்வாறு இந்தத் தடையை முதலில் ஆண்களுக்கும் பிறகு பெண்களுக்கும் அல்லாஹ் குறிப்பிடுகிறான். மேன்மைமிக்க அல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَلْمِزُواْ</span> <span class=\"quran-arabic-font text-success\">أَنفُسَكُمْ</span><br />\r\n<br />\r\n(உங்களையே நீங்கள் குறை கூறிப் பழித்துக் கொள்ளாதீர்கள்,) இது ஒருவரையொருவர் பழிப்பதைத் தடை செய்கிறது. மனிதர்களில் எவர் அவதூறு பேசுபவராகவும், புறம் பேசுபவராகவும் இருக்கிறாரோ, அவர் சபிக்கப்பட்டவர் என்று அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيْلٌ</span> <span class=\"quran-arabic-font text-success\">لِّكُلِّ</span> <span class=\"quran-arabic-font text-success\">هُمَزَةٍ</span> <span class=\"quran-arabic-font text-success\">لُّمَزَةٍ</span><br />\r\n<br />\r\n(குறை சொல்லிப் பழித்துத் திரியும் ஒவ்வொருவனுக்கும் கேடுதான்.) (<a href=\"qurandisp.php?sura=104&ayah=1\" class=\"link\">104:1</a>) ‘ஹம்ஸ்’ (Hamz) என்பது செயல்கள் மூலம் அவமதிப்பது, ‘லம்ஸ்’ (Lamz) என்பது வார்த்தைகள் மூலம் குறை கூறுவதாகும். மேன்மையும் கண்ணியமும் மிக்க அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">هَمَّازٍ</span> <span class=\"quran-arabic-font text-success\">مَّشَّآءِ</span> <span class=\"quran-arabic-font text-success\">بِنَمِيمٍ</span><br />\r\n<br />\r\n(அதிகம் குறை சொல்பவன், கோள் சொல்லிக் கொண்டு திரிபவன்.) (<a href=\"qurandisp.php?sura=68&ayah=11\" class=\"link\">68:11</a>) அதாவது, அவன் மக்களை இழிவுபடுத்தி, அவர்கள் மத்தியில் வரம்பு மீறி கோள் சொல்லிக் கொண்டு திரிகிறான்; இதுவே வார்த்தைகளைப் பயன்படுத்திச் செய்யப்படும் ‘லம்ஸ்’ ஆகும். இங்கு அல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَلْمِزُواْ</span> <span class=\"quran-arabic-font text-success\">أَنفُسَكُمْ</span><br />\r\n<br />\r\n(உங்களையே நீங்கள் குறை கூறிப் பழித்துக் கொள்ளாதீர்கள்,) என்பது மற்றொரு வசனத்தில் அவன் கூறியிருப்பதைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَقْتُلُواْ</span> <span class=\"quran-arabic-font text-success\">أَنفُسَكُمْ</span><br />\r\n<br />\r\n(உங்களையே நீங்கள் கொலை செய்துகொள்ளாதீர்கள்) (<a href=\"qurandisp.php?sura=4&ayah=29\" class=\"link\">4:29</a>), அதாவது ஒருவரையொருவர் கொலை செய்யாதீர்கள்.<br />\r\n<br />\r\nஅப்துல்லாஹ் பின் அப்பாஸ் (ரழி), முஜாஹித், ஸஈத் பின் ஜுபைர், கதாதா மற்றும் முகாத்தில் பின் ஹய்யான் ஆகியோர் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَلْمِزُواْ</span> <span class=\"quran-arabic-font text-success\">أَنفُسَكُمْ</span><br />\r\n<br />\r\n(உங்களையே நீங்கள் குறை கூறிப் பழித்துக் கொள்ளாதீர்கள்,) என்பதன் பொருள், \"உங்களில் எவரும் ஒருவரையொருவர் பழித்துக் கொள்ள வேண்டாம்\" என்பதாகும். அதே சமயம்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَنَابَزُواْ</span> <span class=\"quran-arabic-font text-success\">بِالاٌّلْقَـبِ</span><br />\r\n<br />\r\n(பட்டப்பெயர்களைக் கொண்டு ஒருவரையொருவர் அழைக்காதீர்கள்) என்பதன் பொருள், \"மக்கள் விரும்பாத பட்டப்பெயர்களைக் கொண்டு அவர்களை நீங்கள் அழைக்கக் கூடாது\" என்பதாகும். இமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ளார்கள்: அபூ ஜுபைரா பின் அத்-தஹ்ஹாக் (ரழி) அவர்கள் கூறினார்கள், \"இந்த வசனம் பனூ ஸலமா கிளையினராகிய எங்களைப் பற்றியே அருளப்பட்டது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَنَابَزُواْ</span> <span class=\"quran-arabic-font text-success\">بِالاٌّلْقَـبِ</span><br />\r\n<br />\r\n(பட்டப்பெயர்களைக் கொண்டு ஒருவரையொருவர் அழைக்காதீர்கள்.) அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மதீனாவிற்கு ஹிஜ்ரத் செய்து வந்தபோது, எங்களில் ஒவ்வொருவருக்கும் இரண்டு அல்லது மூன்று பட்டப்பெயர்கள் இருந்தன. நபி (ஸல்) அவர்கள் அந்தப் பட்டப்பெயர்களில் ஒன்றைக் கூறி ஒருவரைக் கூப்பிடும்போது, மக்கள், 'அல்லாஹ்வின் தூதரே! அவர் அந்தப் பட்டப்பெயரை வெறுக்கிறார்' என்று கூறுவார்கள். அதன் பின்னரே இந்த வசனம் அருளப்பட்டது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَنَابَزُواْ</span> <span class=\"quran-arabic-font text-success\">بِالاٌّلْقَـبِ</span><br />\r\n<br />\r\n(பட்டப்பெயர்களைக் கொண்டு ஒருவரையொருவர் அழைக்காதீர்கள்).\" அபூதாவூத் அவர்களும் இந்த ஹதீஸைப் பதிவு செய்துள்ளார்கள்.<br />\r\n<br />\r\nமேன்மையும் கண்ணியமும் மிக்க அல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بِئْسَ</span> <span class=\"quran-arabic-font text-success\">الاسْمُ</span> <span class=\"quran-arabic-font text-success\">الْفُسُوقُ</span> <span class=\"quran-arabic-font text-success\">بَعْدَ</span> <span class=\"quran-arabic-font text-success\">الايمَانِ</span><br />\r\n<br />\r\n(ஈமான் கொண்டதற்குப் பிறகு, பாவம் கலந்த பட்டப்பெயர் சூட்டுவது மிகக் கெட்டதாகும்,) இதன் பொருள், பாவமான பெயர்களும் வர்ணனைகளும் தீயவை என்பதாகும்; அதாவது, \"நீங்கள் இஸ்லாத்தை ஏற்று அதை விளங்கிக்கொண்ட பிறகு, ஜாஹிலிய்யா (அறியாமை) கால மக்கள் பயன்படுத்திய பட்டப்பெயர்களைப் பயன்படுத்துவது மிகக் கெட்டது.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">لَّمْ</span> <span class=\"quran-arabic-font text-success\">يَتُبْ</span><br />\r\n<br />\r\n(எவர் தவ்பா செய்து மீளவில்லையோ,) அதாவது இந்தப் பாவத்திலிருந்து,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الظَّـلِمُونَ</span><br />\r\n<br />\r\n(அவர்களே அநியாயக்காரர்கள்.)<br />\r\n<br />\r\n<br />\r\n<br />","text":"ஒருவரை ஒருவர் கேலி செய்வதும் ஏளனம் செய்வதும் தடைசெய்யப்பட்டுள்ளது\n\r\n\n\r\nமேன்மைமிக்க அல்லாஹ் மக்களை ஏளனம் செய்வதைத் தடை செய்கிறான்; இது அவர்களை அவமதிப்பதையும் இழிவுபடுத்துவதையும் குறிக்கிறது. ஸஹீஹ் (முஸ்லிம்) நூலில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள் எனப் பதிவு செய்யப்பட்டுள்ளது:\n\r\n\n\r\n«الْكِبْرُ بَطَرُ الْحَقِّ وَغَمْصُ النَّاس»\n\r\n\n\r\n(பெருமை என்பது சத்தியத்தை மறுப்பதும், மக்களை இழிவுபடுத்துவதும் ஆகும்.) மற்றொரு அறிவிப்பில்:\n\r\n\n\r\n«غَمْطُ النَّاس»\n\r\n\n\r\n(மக்களை இகழ்வதும் ஆகும்). மக்களை ஏளனம் செய்வதும் இழிவுபடுத்துவதும் விலக்கப்பட்டுள்ளது. ஏனெனில், பாதிக்கப்பட்டவர் ஏளனம் செய்பவர்களை விட மேன்மைமிக்க அல்லாஹ்விடம் அதிக கண்ணியமானவராகவும் அவனுக்கு மிகவும் பிரியமானவராகவும் இருக்கக்கூடும். இதனால்தான் மேன்மைமிக்க அல்லாஹ் இவ்வாறு கூறுகிறான்:\n\r\n\n\r\nيأَيُّهَا الَّذِينَ ءَامَنُواْ لاَ يَسْخَرْ قَوْمٌ مِّن قَوْمٍ عَسَى أَن يَكُونُواْ خَيْراً مِّنْهُمْ وَلاَ نِسَآءٌ مِّن نِّسَآءٍ عَسَى أَن يَكُنَّ خَيْراً مِّنْهُنَّ\n\r\n\n\r\n(நம்பிக்கையாளர்களே! ஒரு சமூகத்தினர் மற்றொரு சமூகத்தினரை ஏளனம் செய்ய வேண்டாம்; அவர்கள் (ஏளனம் செய்யப்பட்டவர்கள்) இவர்களை விடச் சிறந்தவர்களாக இருக்கக்கூடும். எந்தப் பெண்களும் மற்றப் பெண்களை ஏளனம் செய்ய வேண்டாம்; அவர்கள் இவர்களை விடச் சிறந்தவர்களாக இருக்கக்கூடும்.) இவ்வாறு இந்தத் தடையை முதலில் ஆண்களுக்கும் பிறகு பெண்களுக்கும் அல்லாஹ் குறிப்பிடுகிறான். மேன்மைமிக்க அல்லாஹ்வின் கூற்று:\n\r\n\n\r\nوَلاَ تَلْمِزُواْ أَنفُسَكُمْ\n\r\n\n\r\n(உங்களையே நீங்கள் குறை கூறிப் பழித்துக் கொள்ளாதீர்கள்,) இது ஒருவரையொருவர் பழிப்பதைத் தடை செய்கிறது. மனிதர்களில் எவர் அவதூறு பேசுபவராகவும், புறம் பேசுபவராகவும் இருக்கிறாரோ, அவர் சபிக்கப்பட்டவர் என்று அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَيْلٌ لِّكُلِّ هُمَزَةٍ لُّمَزَةٍ\n\r\n\n\r\n(குறை சொல்லிப் பழித்துத் திரியும் ஒவ்வொருவனுக்கும் கேடுதான்.) (104:1) ‘ஹம்ஸ்’ (Hamz) என்பது செயல்கள் மூலம் அவமதிப்பது, ‘லம்ஸ்’ (Lamz) என்பது வார்த்தைகள் மூலம் குறை கூறுவதாகும். மேன்மையும் கண்ணியமும் மிக்க அல்லாஹ் கூறினான்:\n\r\n\n\r\nهَمَّازٍ مَّشَّآءِ بِنَمِيمٍ\n\r\n\n\r\n(அதிகம் குறை சொல்பவன், கோள் சொல்லிக் கொண்டு திரிபவன்.) (68:11) அதாவது, அவன் மக்களை இழிவுபடுத்தி, அவர்கள் மத்தியில் வரம்பு மீறி கோள் சொல்லிக் கொண்டு திரிகிறான்; இதுவே வார்த்தைகளைப் பயன்படுத்திச் செய்யப்படும் ‘லம்ஸ்’ ஆகும். இங்கு அல்லாஹ்வின் கூற்று:\n\r\n\n\r\nوَلاَ تَلْمِزُواْ أَنفُسَكُمْ\n\r\n\n\r\n(உங்களையே நீங்கள் குறை கூறிப் பழித்துக் கொள்ளாதீர்கள்,) என்பது மற்றொரு வசனத்தில் அவன் கூறியிருப்பதைப் போன்றது:\n\r\n\n\r\nوَلاَ تَقْتُلُواْ أَنفُسَكُمْ\n\r\n\n\r\n(உங்களையே நீங்கள் கொலை செய்துகொள்ளாதீர்கள்) (4:29), அதாவது ஒருவரையொருவர் கொலை செய்யாதீர்கள்.\n\r\n\n\r\nஅப்துல்லாஹ் பின் அப்பாஸ் (ரழி), முஜாஹித், ஸஈத் பின் ஜுபைர், கதாதா மற்றும் முகாத்தில் பின் ஹய்யான் ஆகியோர் கூறினார்கள்:\n\r\n\n\r\nوَلاَ تَلْمِزُواْ أَنفُسَكُمْ\n\r\n\n\r\n(உங்களையே நீங்கள் குறை கூறிப் பழித்துக் கொள்ளாதீர்கள்,) என்பதன் பொருள், \"உங்களில் எவரும் ஒருவரையொருவர் பழித்துக் கொள்ள வேண்டாம்\" என்பதாகும். அதே சமயம்,\n\r\n\n\r\nوَلاَ تَنَابَزُواْ بِالاٌّلْقَـبِ\n\r\n\n\r\n(பட்டப்பெயர்களைக் கொண்டு ஒருவரையொருவர் அழைக்காதீர்கள்) என்பதன் பொருள், \"மக்கள் விரும்பாத பட்டப்பெயர்களைக் கொண்டு அவர்களை நீங்கள் அழைக்கக் கூடாது\" என்பதாகும். இமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ளார்கள்: அபூ ஜுபைரா பின் அத்-தஹ்ஹாக் (ரழி) அவர்கள் கூறினார்கள், \"இந்த வசனம் பனூ ஸலமா கிளையினராகிய எங்களைப் பற்றியே அருளப்பட்டது:\n\r\n\n\r\nوَلاَ تَنَابَزُواْ بِالاٌّلْقَـبِ\n\r\n\n\r\n(பட்டப்பெயர்களைக் கொண்டு ஒருவரையொருவர் அழைக்காதீர்கள்.) அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மதீனாவிற்கு ஹிஜ்ரத் செய்து வந்தபோது, எங்களில் ஒவ்வொருவருக்கும் இரண்டு அல்லது மூன்று பட்டப்பெயர்கள் இருந்தன. நபி (ஸல்) அவர்கள் அந்தப் பட்டப்பெயர்களில் ஒன்றைக் கூறி ஒருவரைக் கூப்பிடும்போது, மக்கள், 'அல்லாஹ்வின் தூதரே! அவர் அந்தப் பட்டப்பெயரை வெறுக்கிறார்' என்று கூறுவார்கள். அதன் பின்னரே இந்த வசனம் அருளப்பட்டது:\n\r\n\n\r\nوَلاَ تَنَابَزُواْ بِالاٌّلْقَـبِ\n\r\n\n\r\n(பட்டப்பெயர்களைக் கொண்டு ஒருவரையொருவர் அழைக்காதீர்கள்).\" அபூதாவூத் அவர்களும் இந்த ஹதீஸைப் பதிவு செய்துள்ளார்கள்.\n\r\n\n\r\nமேன்மையும் கண்ணியமும் மிக்க அல்லாஹ்வின் கூற்று:\n\r\n\n\r\nبِئْسَ الاسْمُ الْفُسُوقُ بَعْدَ الايمَانِ\n\r\n\n\r\n(ஈமான் கொண்டதற்குப் பிறகு, பாவம் கலந்த பட்டப்பெயர் சூட்டுவது மிகக் கெட்டதாகும்,) இதன் பொருள், பாவமான பெயர்களும் வர்ணனைகளும் தீயவை என்பதாகும்; அதாவது, \"நீங்கள் இஸ்லாத்தை ஏற்று அதை விளங்கிக்கொண்ட பிறகு, ஜாஹிலிய்யா (அறியாமை) கால மக்கள் பயன்படுத்திய பட்டப்பெயர்களைப் பயன்படுத்துவது மிகக் கெட்டது.\"\n\r\n\n\r\nوَمَن لَّمْ يَتُبْ\n\r\n\n\r\n(எவர் தவ்பா செய்து மீளவில்லையோ,) அதாவது இந்தப் பாவத்திலிருந்து,\n\r\n\n\r\nفَأُوْلَـئِكَ هُمُ الظَّـلِمُونَ\n\r\n\n\r\n(அவர்களே அநியாயக்காரர்கள்.)"},"12":{"html":"<strong>ஆதாரமற்ற சந்தேகத்தின் தடை</strong><br />\r\n<br />\r\nமேலான அல்லாஹ், தன் நம்பிக்கையுள்ள அடியார்களைச் சந்தேகம் கொள்வதிலிருந்து தடுக்கிறான். ஒருவருடைய குடும்பத்தினர், உறவினர்கள் மற்றும் பொதுவாக ஏனைய மக்களின் நடத்தையில் ஆதாரமற்ற சந்தேகங்கள் மற்றும் ஐயங்கள் கொள்வதும் இதில் அடங்கும். எனவே, முஸ்லிம்கள் ஆதாரமற்ற சந்தேகங்களைத் தவிர்க்க வேண்டும். நம்பிக்கையாளர்களின் தலைவர் உமர் பின் அல்-கத்தாப் (ரழி) அவர்கள் கூறினார்கள்: \"உமது முஃமினான சகோதரரின் வாயிலிருந்து வரும் ஒரு வார்த்தைக்கு உம்மால் ஒரு நல்ல விளக்கத்தைக் காண முடிகின்ற வரை, அதைப்பற்றித் தவறாக எண்ணாதீர்.\" மாலிக் (ரஹ்) அவர்கள் பதிவு செய்துள்ளார்கள்: அபூ ஹுரைரா (ரழி) அவர்கள் அறிவிக்கிறார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِيَّاكُمْ</span> <span class=\"quran-arabic-font text-success\">وَالظَّنَّ</span> <span class=\"quran-arabic-font text-success\">فَإِنَّ</span> <span class=\"quran-arabic-font text-success\">الظَّنَّ</span> <span class=\"quran-arabic-font text-success\">أَكْذَبُ</span> <span class=\"quran-arabic-font text-success\">الْحَدِيثِ،</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">تَجَسَّسُوا</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">تَحَسَّسُوا،</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">تَنَافَسُوا</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">تَحَاسَدُوا،</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">تَبَاغَضُوا</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">تَدَابَرُوا،</span> <span class=\"quran-arabic-font text-success\">وَكُونُوا</span> <span class=\"quran-arabic-font text-success\">عِبَادَ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">إِخْوَانًا</span>»<br />\r\n<br />\r\n(சந்தேகத்தைக் குறித்து எச்சரிக்கையாக இருங்கள்; ஏனெனில், சந்தேகம் என்பது பேச்சுகளிலேயே மிகவும் பொய்யானதாகும். ஒருவரை ஒருவர் உளவு பார்க்காதீர்கள்; மற்றவர்களின் குறைகளைத் துருவித் தேடாதீர்கள்; ஒருவருக்கொருவர் போட்டி போடாதீர்கள்; ஒருவர் மீது ஒருவர் பொறாமை கொள்ளாதீர்கள்; ஒருவரை ஒருவர் வெறுக்காதீர்கள்; ஒருவருக்கொருவர் முதுகைக் காட்டிக்கொண்டு ஒதுங்காதீர்கள். அல்லாஹ்வின் அடியார்களே! நீங்கள் சகோதரர்களாக இருங்கள்!) இந்த ஹதீஸை இரண்டு ஸஹீஹ் நூல்களும் அபூ தாவூதும் பதிவு செய்துள்ளன. அனஸ் (ரழி) அவர்கள் அறிவிக்கிறார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تَقَاطَعُوا</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">تَدَابَرُوا</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">تَبَاغَضُوا</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">تَحَاسَدُوا،</span> <span class=\"quran-arabic-font text-success\">وَكُونُوا</span> <span class=\"quran-arabic-font text-success\">عِبَادَ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">إِخْوَانًا،</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">يَحِلُّ</span> <span class=\"quran-arabic-font text-success\">لِمُسْلِمٍ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يَهْجُرَ</span> <span class=\"quran-arabic-font text-success\">أَخَاهُ</span> <span class=\"quran-arabic-font text-success\">فَوْقَ</span> <span class=\"quran-arabic-font text-success\">ثَلَاثَةِ</span> <span class=\"quran-arabic-font text-success\">أَيَّام</span>»<br />\r\n<br />\r\n(உறவுகளைத் துண்டித்துக் கொள்ளாதீர்கள்; ஒருவருக்கொருவர் முதுகைக் காட்டிக்கொண்டு ஒதுங்காதீர்கள்; ஒருவரை ஒருவர் வெறுக்காதீர்கள்; ஒருவர் மீது ஒருவர் பொறாமை கொள்ளாதீர்கள். அல்லாஹ்வின் அடியார்களே! நீங்கள் சகோதரர்களாக இருங்கள். ஒரு முஸ்லிம் தன் சகோதரனை மூன்று நாட்களுக்கு மேல் வெறுத்து ஒதுங்குவது அனுமதிக்கப்பட்டதல்ல.) முஸ்லிம் மற்றும் திர்மிதி ஆகியோரால் இந்த ஹதீஸ் சேகரிக்கப்பட்டுள்ளது, மேலும் திர்மிதி இதனை ஸஹீஹ் எனக் கருதுகிறார். அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَجَسَّسُواْ</span><br />\r\n<br />\r\n(மேலும் உளவு பார்க்காதீர்கள்), ஒருவரை ஒருவர். 'தஜஸ்ஸுஸ்' என்பது பொதுவாகத் தீய நோக்கங்களைக் கொண்டது, உளவு பார்ப்பவர் 'ஜாஸூஸ்' என்று அழைக்கப்படுவார். 'தஹஸ்ஸுஸ்' (விசாரித்தல்) என்பது பொதுவாக நல்ல காரணத்திற்காகச் செய்யப்படுவதாகும். மேலானவனும் கண்ணியமிக்கவனுமான அல்லாஹ், யஃகூப் (அலை) அவர்கள் கூறியதாகக் குறிப்பிடுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">بَنِيَّ</span> <span class=\"quran-arabic-font text-success\">اذْهَبُواْ</span> <span class=\"quran-arabic-font text-success\">فَتَحَسَّسُواْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">يُوسُفَ</span> <span class=\"quran-arabic-font text-success\">وَأَخِيهِ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَيْأَسُوا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">رَّوْحِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span><br />\r\n<br />\r\n(\"என் மைந்தர்களே! நீங்கள் சென்று யூசுஃபைப் பற்றியும் அவரது சகோதரரைப் பற்றியும் விசாரித்து (தஹஸ்ஸஸு) வாருங்கள்; அல்லாஹ்வின் அருளில் ஒருபோதும் நம்பிக்கை இழக்காதீர்கள்.\") (<a href=\"qurandisp.php?sura=12&ayah=87\" class=\"link\">12:87</a>) 'தஜஸ்ஸுஸ்' மற்றும் 'தஹஸ்ஸுஸ்' ஆகிய இரண்டு சொற்களுமே தீய அர்த்தங்களையும் கொண்டிருக்கலாம். ஸஹீஹ் நூலில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியதாகப் பதிவு செய்யப்பட்டுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تَجَسَّسُوا</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">تَحَسَّسُوا،</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">تَبَاغَضُوا</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">تَدَابَرُوا،</span> <span class=\"quran-arabic-font text-success\">وَكُونُوا</span> <span class=\"quran-arabic-font text-success\">عِبَادَ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">إِخْوَانًا</span>»<br />\r\n<br />\r\n(தஜஸ்ஸுஸும் செய்யாதீர்கள், தஹஸ்ஸுஸும் செய்யாதீர்கள், ஒருவரை ஒருவர் வெறுக்காதீர்கள், ஒருவருக்கொருவர் முதுகைக் காட்டிக்கொண்டு ஒதுங்காதீர்கள். அல்லாஹ்வின் அடியார்களே! நீங்கள் சகோதரர்களாக இருங்கள்.) அல்-அவ்ஸாஈ அவர்கள் கூறினார்கள்: \"தஜஸ்ஸுஸ் என்பது ஒன்றைத் தேடித் துருவுவது; தஹஸ்ஸுஸ் என்பது மக்கள் பேசிக்கொண்டிருக்கும்போது அவர்களின் அனுமதியின்றி ஒட்டுக் கேட்பது அல்லது அவர்களின் வீட்டு வாசல்களில் நின்று ஒட்டுக் கேட்பது. ததாபுர் என்பது ஒருவரை ஒருவர் புறக்கணிப்பதாகும்.\" இப்னு அபீ ஹாதிம் அவர்கள் இந்தக் கூற்றைப் பதிவு செய்துள்ளார். புறம் பேசுவதைப் பற்றி மேலான அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَغْتَب</span> <span class=\"quran-arabic-font text-success\">بَّعْضُكُم</span> <span class=\"quran-arabic-font text-success\">بَعْضاً</span><br />\r\n<br />\r\n(உங்களில் ஒருவர் மற்றவரைப் பற்றிப் புறம் பேச வேண்டாம்). இவ்வாறு அல்லாஹ் அதனைத் தடை செய்தான். இது அபூ தாவூத் தொகுத்த ஒரு ஹதீஸில் விளக்கப்பட்டுள்ளது. அபூ ஹுரைரா (ரழி) அவர்கள் கூறினார்கள்: \"'அல்லாஹ்வின் தூதரே! புறம் பேசுதல் என்றால் என்ன?' என்று கேட்கப்பட்டது.\" அதற்கு அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">ذِكْرُكَ</span> <span class=\"quran-arabic-font text-success\">أَخَاكَ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">يَكْرَه</span>»<br />\r\n<br />\r\n(உமது சகோதரர் விரும்பாத ஒரு விஷயத்தைக் கொண்டு அவரைப் பற்றிக் குறிப்பிடுவதாகும்.) \"'நான் சொல்வது என் சகோதரரிடம் உண்மையில் இருந்தாலுமா?' என்று கேட்கப்பட்டது.\" அதற்கு அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">تَقُولُ</span> <span class=\"quran-arabic-font text-success\">فَقَدِ</span> <span class=\"quran-arabic-font text-success\">اغْتَبْتَهُ،</span> <span class=\"quran-arabic-font text-success\">وَإِنْ</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يَكُنْ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">تَقُولُ</span> <span class=\"quran-arabic-font text-success\">فَقَدْ</span> <span class=\"quran-arabic-font text-success\">بَهَتَّه</span>»<br />\r\n<br />\r\n(நீர் சொல்வது அவரிடம் இருந்தால் நீர் அவரைப் பற்றிப் புறம் பேசினீர்; நீர் சொல்வது அவரிடம் இல்லையென்றால், நீர் அவர் மீது அவதூறு சுமத்தினீர்.)\" திர்மிதி இந்த ஹதீஸைச் சேகரித்து \"ஹஸன் ஸஹீஹ்\" எனக் குறிப்பிட்டுள்ளார். புறம் பேசுவது குறித்துக் கடுமையான எச்சரிக்கை விடுக்கப்பட்டுள்ளது. அதனால்தான் மேலானவனும் பாக்கியம் மிக்கவனுமான அல்லாஹ், அதனைத் தன் இறந்த சகோதரனின் மாமிசத்தை உண்பதற்கு ஒப்பிட்டுக் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَيُحِبُّ</span> <span class=\"quran-arabic-font text-success\">أَحَدُكُمْ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَأْكُلَ</span> <span class=\"quran-arabic-font text-success\">لَحْمَ</span> <span class=\"quran-arabic-font text-success\">أَخِيهِ</span> <span class=\"quran-arabic-font text-success\">مَيْتاً</span> <span class=\"quran-arabic-font text-success\">فَكَرِهْتُمُوهُ</span><br />\r\n<br />\r\n(உங்களில் எவராவது தன் இறந்த சகோதரனின் மாமிசத்தை உண்ண விரும்புவாரா? அதனை நீங்கள் வெறுப்பீர்கள்.) இறந்த மனிதனின் மாமிசத்தை உண்பதை உங்கள் இயற்கை உணர்வால் நீங்கள் எவ்வாறு வெறுக்கிறீர்களோ, அதுபோலவே உங்கள் மார்க்கத்தின் அடிப்படையில் புறம் பேசுவதையும் வெறுங்கள். பின்னது முன்னதை விடக் கடுமையான தண்டனைக்குரியது. இந்த வசனம் மக்களைப் புறம் பேசுவதிலிருந்து ஊக்கமிழக்கச் செய்யவும் அதற்கு எதிராக எச்சரிக்கவும் செய்கிறது. நபி (ஸல்) அவர்கள் ஒருவர் தான் கொடுத்த அன்பளிப்பைத் திரும்பப் பெறுவதைத் தடுப்பதற்காக இந்த வார்த்தைகளைப் பயன்படுத்தினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">كَالْكَلْبِ</span> <span class=\"quran-arabic-font text-success\">يَقِيءُ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يَرْجِعُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">قَيْئِه</span>»<br />\r\n<br />\r\n(அவன் தான் வாந்தி எடுத்துவிட்டு, அதனைத் தானே உண்ணும் நாயைப் போன்றவன்.) இவ்வாறு கூறிய பின்,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَيْسَ</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">مَثَلُ</span> <span class=\"quran-arabic-font text-success\">السَّوْء</span>»<br />\r\n<br />\r\n(நமக்குத் தீய உவமை தகாது) என்றார்கள்.<br />\r\n<br />\r\nஅபூ தாவூத் (ரஹ்) அவர்கள் பதிவு செய்துள்ளார்கள்: அபூ பர்ஸா அல்-அஸ்லமீ (ரழி) அவர்கள் அறிவிக்கிறார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் உரற்றியதாவது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">مَعْشَرَ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">آمَنَ</span> <span class=\"quran-arabic-font text-success\">بِلِسَانِهِ</span> <span class=\"quran-arabic-font text-success\">وَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَدْخُلِ</span> <span class=\"quran-arabic-font text-success\">الْإِيمَانُ</span> <span class=\"quran-arabic-font text-success\">قَلْبَهُ،</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تَغْتَابُوا</span> <span class=\"quran-arabic-font text-success\">الْمُسْلِمِينَ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">تَتَّبِعُوا</span> <span class=\"quran-arabic-font text-success\">عَوْرَاتِهِمْ،</span> <span class=\"quran-arabic-font text-success\">فَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">مَنِ</span> <span class=\"quran-arabic-font text-success\">اتَّبَعَ</span> <span class=\"quran-arabic-font text-success\">عَوْرَاتِهِمْ</span> <span class=\"quran-arabic-font text-success\">يَتَّبِعِ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">عَوْرَتَهُ،</span> <span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">يَتَّبِعِ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">عَوْرَتَهُ</span> <span class=\"quran-arabic-font text-success\">يَفْضَحْهُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">بَيْتِه</span>»<br />\r\n<br />\r\n(\"நாவால் ஈமான் கொண்டு, உள்ளத்தில் ஈமான் நுழையாதவர்களே! முஸ்லிம்களைப் பற்றிப் புறம் பேசாதீர்கள்; அவர்களின் குறைகளைத் துருவித் துருவி ஆராயாதீர்கள். ஏனெனில், எவன் அவர்களின் குறைகளைத் தேடித் திரிகிறானோ, அல்லாஹ் அவனது குறையைத் தேடுவான்; எவனது குறையை அல்லாஹ் தேடுகிறானோ, அவனை அவனது வீட்டிற்குள்ளேயே அல்லாஹ் இழிவுபடுத்தி விடுவான்.\")<br />\r\n<br />\r\nஅபூ தாவூத் (ரஹ்) அவர்கள் பதிவு செய்துள்ளார்கள்: அனஸ் (ரழி) அவர்கள் கூறினார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَمَّا</span> <span class=\"quran-arabic-font text-success\">عُرِجَ</span> <span class=\"quran-arabic-font text-success\">بِي</span> <span class=\"quran-arabic-font text-success\">مَرَرْتُ</span> <span class=\"quran-arabic-font text-success\">بِقَوْمٍ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">أَظْفَارٌ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">نُحَاسٍ</span> <span class=\"quran-arabic-font text-success\">يَخْمُشُونَ</span> <span class=\"quran-arabic-font text-success\">وُجُوهَهُمْ</span> <span class=\"quran-arabic-font text-success\">وَصُدُورَهُمْ،</span> <span class=\"quran-arabic-font text-success\">فَقُلْتُ</span>: <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">هَؤُلَاءِ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">جِبْرِيلُ؟</span> <span class=\"quran-arabic-font text-success\">قَالَ</span>: <span class=\"quran-arabic-font text-success\">هَؤُلَاءِ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَأْكُلُونَ</span> <span class=\"quran-arabic-font text-success\">لُحُومَ</span> <span class=\"quran-arabic-font text-success\">النَّاسِ،</span> <span class=\"quran-arabic-font text-success\">وَيَقَعُونَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">أَعْرَاضِهِم</span>»<br />\r\n<br />\r\n(\"நான் (விண்ணுலகிற்கு) அழைத்துச் செல்லப்பட்ட இரவில், செம்பினாலான நகங்களைக் கொண்ட சிலரைக் கடந்து சென்றேன். அவர்கள் தங்கள் முகங்களையும் நெஞ்சங்களையும் (அந்நகங்களால்) காயப்படுத்திக் கொண்டிருந்தார்கள். நான், ‘ஜிப்ரீலே! இவர்கள் யார்?’ என்று கேட்டேன். அதற்கு அவர், ‘இவர்கள் (பிற) மனிதர்களின் இறைச்சியைச் சாப்பிட்டு, அவர்களின் மானத்தில் கைவைத்தவர்கள் (புறம் பேசியவர்கள்)’ என்று கூறினார்.\")<br />\r\n<br />\r\nபல்வேறு அறிவிப்பாளர் தொடர்களின் வழியாக, நபி (ஸல்) அவர்கள் விடைபெறும் ஹஜ்ஜின் போது கூறியதாக ஸஹீஹ் மற்றும் முஸ்னத் நூல்கள் பதிவு செய்துள்ளன:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">دِمَاءَكُمْ</span> <span class=\"quran-arabic-font text-success\">وَأَمْوَالَكُمْ</span> <span class=\"quran-arabic-font text-success\">وَأَعْرَاضَكُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">حَرَامٌ</span> <span class=\"quran-arabic-font text-success\">كَحُرْمَةِ</span> <span class=\"quran-arabic-font text-success\">يَوْمِكُمْ</span> <span class=\"quran-arabic-font text-success\">هذَا،</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">شَهْرِكُمْ</span> <span class=\"quran-arabic-font text-success\">هذَا،</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">بَلَدِكُمْ</span> <span class=\"quran-arabic-font text-success\">هذَا</span>»<br />\r\n<br />\r\n(நிச்சயமாக உங்கள் இரத்தமும், உங்கள் செல்வமும், உங்கள் கண்ணியமும் உங்களுக்குள் புனிதமானவையாகும்; உங்களது இந்த நகரத்தில், இந்த மாதத்தில், இன்றைய தினத்தைப் போலவே புனிதமானதாகும்.) அபூ தாவூத் பதிவு செய்துள்ளார்கள்: அபூ ஹுரைரா (ரழி) அவர்கள் அறிவிக்கிறார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">كُلُّ</span> <span class=\"quran-arabic-font text-success\">الْمُسْلِمِ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْمُسْلِمِ</span> <span class=\"quran-arabic-font text-success\">حَرَامٌ</span> <span class=\"quran-arabic-font text-success\">مَالُهُ</span> <span class=\"quran-arabic-font text-success\">وَعِرْضُهُ</span> <span class=\"quran-arabic-font text-success\">وَدَمُهُ،</span> <span class=\"quran-arabic-font text-success\">حَسْبُ</span> <span class=\"quran-arabic-font text-success\">امْرِىءٍ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الشَّرِّ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يَحْقِرَ</span> <span class=\"quran-arabic-font text-success\">أَخَاهُ</span> <span class=\"quran-arabic-font text-success\">الْمُسْلِم</span>»<br />\r\n<br />\r\n(ஒவ்வொரு முஸ்லிமும் மற்றொரு முஸ்லிமுக்குத் தடை செய்யப்பட்டவர் (புனிதமானவர்); அவனது செல்வம், அவனது கண்ணியம் மற்றும் அவனது இரத்தம். ஒருவன் தன் முஸ்லிம் சகோதரனை இழிவாகக் கருதுவதே அவன் செய்த தீமைக்குப் போதுமானதாகும்.) திர்மிதி இந்த ஹதீஸைச் சேகரித்து \"ஹஸன் ஃகரீப்\" எனக் குறிப்பிட்டுள்ளார். அல்-ஹாஃபிழ் அபூ யஃலா அவர்கள் பதிவு செய்துள்ளார்கள்: அபூ ஹுரைரா (ரழி) அவர்கள் கூறினார்கள்: \"மாஇஸ் (ரழி) அவர்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் வந்து, 'அல்லாஹ்வின் தூதரே! நான் விபச்சாரம் செய்துவிட்டேன்' என்று கூறினார். அவர் தனது கூற்றை நான்கு முறை மீண்டும் சொல்லும் வரை அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அவரை விட்டும் முகத்தைத் திருப்பிக் கொண்டார்கள். ஐந்தாவது முறை, நபி (ஸல்) அவர்கள் அவரிடம் கேட்டார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">زَنَيْتَ؟</span>»<br />\r\n<br />\r\n(நீ விபச்சாரம் செய்தாயா?) மாஇஸ் (ரழி) 'ஆம்' என்றார். நபி (ஸல்) அவர்கள் கேட்டார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">وَتَدْرِي</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">الزِّنَا؟</span>»<br />\r\n<br />\r\n(விபச்சாரம் என்றால் என்னவென்று உனக்குத் தெரியுமா?) அதற்கு மாஇஸ் (ரழி) 'ஆம், ஒரு கணவன் தன் மனைவியுடன் சட்டப்பூர்வமாகச் செய்வதை, நான் அவளுடன் சட்டவிரோதமாகச் செய்துவிட்டேன்' என்றார். நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">تُرِيدُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">هذَا</span> <span class=\"quran-arabic-font text-success\">الْقَوْلِ؟</span>»<br />\r\n<br />\r\n(இந்தக் கூற்றின் மூலம் நீ எதை நாடுகிறாய்?) அதற்கு அவர் 'நீங்கள் என்னைத் தூய்மைப்படுத்த வேண்டும் என்று நான் நாடுகிறேன்' என்றார். நபி (ஸல்) அவர்கள் கேட்டார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَدْخَلْتَ</span> <span class=\"quran-arabic-font text-success\">ذلِكَ</span> <span class=\"quran-arabic-font text-success\">مِنْكَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">ذلِكَ</span> <span class=\"quran-arabic-font text-success\">مِنْهَا</span> <span class=\"quran-arabic-font text-success\">كَمَا</span> <span class=\"quran-arabic-font text-success\">يَغِيبُ</span> <span class=\"quran-arabic-font text-success\">الْمِيلُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْمُكْحُلَةِ</span> <span class=\"quran-arabic-font text-success\">وَالرِّشَا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْبِئْرِ؟</span>»<br />\r\n<br />\r\n(சுர்மா குச்சியானது சுர்மா சிமிழிலும், கயிறு கிணற்றிலும் நுழைவது போல் உன்னுடையது அவளுடையதில் நுழைந்ததா?) அவர் 'ஆம், அல்லாஹ்வின் தூதரே!' என்றார். நபி (ஸல்) அவர்கள் மாஇஸ் (ரழி) அவர்களுக்குக் கல்லால் எறிந்து மரண தண்டனை நிறைவேற்றக் கட்டளையிட்டார்கள்; அவ்வாறே நிறைவேற்றப்பட்டது. அதற்குப் பிறகு இரண்டு மனிதர்கள் தங்களுக்குள், 'அல்லாஹ் யாருடைய ரகசியத்தை மறைத்தானோ அந்த மனிதரைப் பார்த்தாயா? ஒரு நாய் கல்லால் எறியப்படுவது போல் கொல்லப்படும் வரை அவரது இதயம் அவரை அமைதியாக இருக்க விடவில்லை' என்று பேசிக்கொள்வதை நபி (ஸல்) அவர்கள் செவிமடுத்தார்கள். நபி (ஸல்) அவர்கள் தொடர்ந்து சென்றுகொண்டிருக்கும்போது ஒரு கழுதையின் சடலத்தைக் கடந்து சென்றார்கள். அப்போது அவர்கள் கேட்டார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَيْنَ</span> <span class=\"quran-arabic-font text-success\">فُلَانٌ</span> <span class=\"quran-arabic-font text-success\">وَفُلَانٌ؟</span> <span class=\"quran-arabic-font text-success\">انْزِلَا</span> <span class=\"quran-arabic-font text-success\">فَكُلَا</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">جِيفَةِ</span> <span class=\"quran-arabic-font text-success\">هذَا</span> <span class=\"quran-arabic-font text-success\">الْحِمَار</span>»<br />\r\n<br />\r\n(இன்னாரும் இன்னாரும் எங்கே? இறங்கி இந்தக் கழுதையின் சடலத்திலிருந்து உண்ணுங்கள்.) அதற்கு அவர்கள் 'அல்லாஹ் உங்களை மன்னிப்பானாக, அல்லாஹ்வின் தூதரே! இதனை யாராவது உண்பார்களா?' என்று கேட்டார்கள். அதற்கு நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">فَمَا</span> <span class=\"quran-arabic-font text-success\">نِلْتُمَا</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَخِيكُمَا</span> <span class=\"quran-arabic-font text-success\">آنِفًا</span> <span class=\"quran-arabic-font text-success\">أَشَدُّ</span> <span class=\"quran-arabic-font text-success\">أَكْلًا</span> <span class=\"quran-arabic-font text-success\">مِنْهُ،</span> <span class=\"quran-arabic-font text-success\">وَالَّذِي</span> <span class=\"quran-arabic-font text-success\">نَفْسِي</span> <span class=\"quran-arabic-font text-success\">بِيَدِهِ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">الْآنَ</span> <span class=\"quran-arabic-font text-success\">لَفِي</span> <span class=\"quran-arabic-font text-success\">أَنْهَارِ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">يَنْغَمِسُ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span>»<br />\r\n<br />\r\n(சற்று முன்பு உங்கள் சகோதரனைப் பற்றி நீங்கள் பேசிய புறம், இதனை உண்பதை விடக் கடுமையானதாகும். எனது உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது சத்தியமாக! அவர் இப்போது சொர்க்கத்தின் ஆறுகளில் மூழ்கித் திளைத்துக் கொண்டிருக்கிறார்.)\" இந்த ஹதீஸின் அறிவிப்பாளர் தொடர் ஆதாரபூர்வமானது. இமாம் அஹ்மத் பதிவு செய்துள்ளார்: ஜாபிர் பின் அப்துல்லாஹ் (ரழி) அவர்கள் கூறினார்கள்: \"நாங்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுடன் இருந்தபோது, ஒரு அழுகிய துர்நாற்றத்தைக் காற்று கொண்டு வந்தது. அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கேட்டார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَتَدْرُونَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">هذِهِ</span> <span class=\"quran-arabic-font text-success\">الرِّيحُ؟</span> <span class=\"quran-arabic-font text-success\">هَذِهِ</span> <span class=\"quran-arabic-font text-success\">رِيحُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَغْتَابُونَ</span> <span class=\"quran-arabic-font text-success\">النَّاس</span>»<br />\r\n<br />\r\n(இந்த நாற்றம் என்னவென்று உங்களுக்குத் தெரியுமா? இது மக்களைப் பற்றிப் புறம் பேசுபவர்களின் நாற்றமாகும்.)\"<br />\r\n<br />\r\n<strong>புறம் பேசுதல் மற்றும் அவதூறிலிருந்து ஏற்றுக்கொள்ளப்பட்ட பாவமன்னிப்பு</strong><br />\r\n<br />\r\nமேலானவனும் கண்ணியமிக்கவனுமான அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاتَّقُواْ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span><br />\r\n<br />\r\n(மேலும் அல்லாஹ்வுக்கு அஞ்சுங்கள் (தக்வா கொள்ளுங்கள்)), அதாவது அவன் உங்களுக்கு ஏவியவற்றிலும் விலக்கியவற்றிலும் (அவனை அஞ்சுங்கள்). அவனுக்குப் பயந்து அவரிடம் எச்சரிக்கையாக இருங்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">تَوَّابٌ</span> <span class=\"quran-arabic-font text-success\">رَّحِيمٌ</span><br />\r\n<br />\r\n(நிச்சயமாக அல்லாஹ் பாவமன்னிப்பை ஏற்றுக்கொள்பவனாகவும், மகா கருணையாளனாகவும் இருக்கிறான்.) அவனிடம் பாவமன்னிப்புத் தேடுபவர்களை அவன் மன்னிக்கிறான்; அவனிடம் மீண்டு வருபவர்களிடமும் அவன் மீது நம்பிக்கை வைப்பவர்களிடமும் அவன் கருணை காட்டுகிறான். புறம் பேசிய பாவத்திற்காகச் செய்யப்படும் தவ்பா (பாவமன்னிப்பு) என்பது, மீண்டும் அதைச் செய்யக்கூடாது என்ற உறுதியுடன் புறம் பேசுவதிலிருந்து விலகியிருப்பதாகும் என்று பெரும்பான்மையான அறிஞர்கள் கூறியுள்ளனர். இதில் வருத்தம் தெரிவிப்பது அவசியமா என்பதிலும், யாரிடம் புறம் பேசப்பட்டதோ அவரிடம் மன்னிப்புக் கேட்க வேண்டுமா என்பதிலும் கருத்து வேறுபாடுகள் உள்ளன. சில அறிஞர்கள் யாரிடம் புறம் பேசப்பட்டதோ அவரிடம் மன்னிப்புக் கேட்பது அவசியமில்லை எனக் கூறுகின்றனர்; ஏனெனில், தங்களைப் பற்றிப் பேசப்பட்டதைத் தெரிந்தால் அவர்கள் இன்னும் அதிகமாக வேதனைப்படக்கூடும். எனவே, எந்த சபையில் ஒருவரைப் பற்றிப் புறம் பேசப்பட்டதோ, அதே சபையில் அவரைப் புகழ்ந்து பேசுவதே சிறந்தது என அவர்கள் கூறுகின்றனர். மேலும், முன்னர் செய்த புறம் பேசுதலுக்குப் பரிகாரமாக, பாதிக்கப்பட்டவரை மீண்டும் மற்றவர்கள் புறம் பேசாதவாறு தன்னால் முடிந்தவரைத் தடுத்துப் பாதுகாப்பதும் சிறந்தது.<br />\r\n<br />","text":"ஆதாரமற்ற சந்தேகத்தின் தடை\n\r\n\n\r\nமேலான அல்லாஹ், தன் நம்பிக்கையுள்ள அடியார்களைச் சந்தேகம் கொள்வதிலிருந்து தடுக்கிறான். ஒருவருடைய குடும்பத்தினர், உறவினர்கள் மற்றும் பொதுவாக ஏனைய மக்களின் நடத்தையில் ஆதாரமற்ற சந்தேகங்கள் மற்றும் ஐயங்கள் கொள்வதும் இதில் அடங்கும். எனவே, முஸ்லிம்கள் ஆதாரமற்ற சந்தேகங்களைத் தவிர்க்க வேண்டும். நம்பிக்கையாளர்களின் தலைவர் உமர் பின் அல்-கத்தாப் (ரழி) அவர்கள் கூறினார்கள்: \"உமது முஃமினான சகோதரரின் வாயிலிருந்து வரும் ஒரு வார்த்தைக்கு உம்மால் ஒரு நல்ல விளக்கத்தைக் காண முடிகின்ற வரை, அதைப்பற்றித் தவறாக எண்ணாதீர்.\" மாலிக் (ரஹ்) அவர்கள் பதிவு செய்துள்ளார்கள்: அபூ ஹுரைரா (ரழி) அவர்கள் அறிவிக்கிறார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِيَّاكُمْ وَالظَّنَّ فَإِنَّ الظَّنَّ أَكْذَبُ الْحَدِيثِ، وَلَا تَجَسَّسُوا وَلَا تَحَسَّسُوا، وَلَا تَنَافَسُوا وَلَا تَحَاسَدُوا، وَلَا تَبَاغَضُوا وَلَا تَدَابَرُوا، وَكُونُوا عِبَادَ اللهِ إِخْوَانًا»\n\r\n\n\r\n(சந்தேகத்தைக் குறித்து எச்சரிக்கையாக இருங்கள்; ஏனெனில், சந்தேகம் என்பது பேச்சுகளிலேயே மிகவும் பொய்யானதாகும். ஒருவரை ஒருவர் உளவு பார்க்காதீர்கள்; மற்றவர்களின் குறைகளைத் துருவித் தேடாதீர்கள்; ஒருவருக்கொருவர் போட்டி போடாதீர்கள்; ஒருவர் மீது ஒருவர் பொறாமை கொள்ளாதீர்கள்; ஒருவரை ஒருவர் வெறுக்காதீர்கள்; ஒருவருக்கொருவர் முதுகைக் காட்டிக்கொண்டு ஒதுங்காதீர்கள். அல்லாஹ்வின் அடியார்களே! நீங்கள் சகோதரர்களாக இருங்கள்!) இந்த ஹதீஸை இரண்டு ஸஹீஹ் நூல்களும் அபூ தாவூதும் பதிவு செய்துள்ளன. அனஸ் (ரழி) அவர்கள் அறிவிக்கிறார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«لَا تَقَاطَعُوا وَلَا تَدَابَرُوا وَلَا تَبَاغَضُوا وَلَا تَحَاسَدُوا، وَكُونُوا عِبَادَ اللهِ إِخْوَانًا، وَلَا يَحِلُّ لِمُسْلِمٍ أَنْ يَهْجُرَ أَخَاهُ فَوْقَ ثَلَاثَةِ أَيَّام»\n\r\n\n\r\n(உறவுகளைத் துண்டித்துக் கொள்ளாதீர்கள்; ஒருவருக்கொருவர் முதுகைக் காட்டிக்கொண்டு ஒதுங்காதீர்கள்; ஒருவரை ஒருவர் வெறுக்காதீர்கள்; ஒருவர் மீது ஒருவர் பொறாமை கொள்ளாதீர்கள். அல்லாஹ்வின் அடியார்களே! நீங்கள் சகோதரர்களாக இருங்கள். ஒரு முஸ்லிம் தன் சகோதரனை மூன்று நாட்களுக்கு மேல் வெறுத்து ஒதுங்குவது அனுமதிக்கப்பட்டதல்ல.) முஸ்லிம் மற்றும் திர்மிதி ஆகியோரால் இந்த ஹதீஸ் சேகரிக்கப்பட்டுள்ளது, மேலும் திர்மிதி இதனை ஸஹீஹ் எனக் கருதுகிறார். அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَلاَ تَجَسَّسُواْ\n\r\n\n\r\n(மேலும் உளவு பார்க்காதீர்கள்), ஒருவரை ஒருவர். 'தஜஸ்ஸுஸ்' என்பது பொதுவாகத் தீய நோக்கங்களைக் கொண்டது, உளவு பார்ப்பவர் 'ஜாஸூஸ்' என்று அழைக்கப்படுவார். 'தஹஸ்ஸுஸ்' (விசாரித்தல்) என்பது பொதுவாக நல்ல காரணத்திற்காகச் செய்யப்படுவதாகும். மேலானவனும் கண்ணியமிக்கவனுமான அல்லாஹ், யஃகூப் (அலை) அவர்கள் கூறியதாகக் குறிப்பிடுகிறான்:\n\r\n\n\r\nيَا بَنِيَّ اذْهَبُواْ فَتَحَسَّسُواْ مِن يُوسُفَ وَأَخِيهِ وَلاَ تَيْأَسُوا مِن رَّوْحِ اللَّهِ\n\r\n\n\r\n(\"என் மைந்தர்களே! நீங்கள் சென்று யூசுஃபைப் பற்றியும் அவரது சகோதரரைப் பற்றியும் விசாரித்து (தஹஸ்ஸஸு) வாருங்கள்; அல்லாஹ்வின் அருளில் ஒருபோதும் நம்பிக்கை இழக்காதீர்கள்.\") (12:87) 'தஜஸ்ஸுஸ்' மற்றும் 'தஹஸ்ஸுஸ்' ஆகிய இரண்டு சொற்களுமே தீய அர்த்தங்களையும் கொண்டிருக்கலாம். ஸஹீஹ் நூலில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியதாகப் பதிவு செய்யப்பட்டுள்ளது:\n\r\n\n\r\n«لَا تَجَسَّسُوا وَلَا تَحَسَّسُوا، وَلَا تَبَاغَضُوا وَلَا تَدَابَرُوا، وَكُونُوا عِبَادَ اللهِ إِخْوَانًا»\n\r\n\n\r\n(தஜஸ்ஸுஸும் செய்யாதீர்கள், தஹஸ்ஸுஸும் செய்யாதீர்கள், ஒருவரை ஒருவர் வெறுக்காதீர்கள், ஒருவருக்கொருவர் முதுகைக் காட்டிக்கொண்டு ஒதுங்காதீர்கள். அல்லாஹ்வின் அடியார்களே! நீங்கள் சகோதரர்களாக இருங்கள்.) அல்-அவ்ஸாஈ அவர்கள் கூறினார்கள்: \"தஜஸ்ஸுஸ் என்பது ஒன்றைத் தேடித் துருவுவது; தஹஸ்ஸுஸ் என்பது மக்கள் பேசிக்கொண்டிருக்கும்போது அவர்களின் அனுமதியின்றி ஒட்டுக் கேட்பது அல்லது அவர்களின் வீட்டு வாசல்களில் நின்று ஒட்டுக் கேட்பது. ததாபுர் என்பது ஒருவரை ஒருவர் புறக்கணிப்பதாகும்.\" இப்னு அபீ ஹாதிம் அவர்கள் இந்தக் கூற்றைப் பதிவு செய்துள்ளார். புறம் பேசுவதைப் பற்றி மேலான அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَلاَ يَغْتَب بَّعْضُكُم بَعْضاً\n\r\n\n\r\n(உங்களில் ஒருவர் மற்றவரைப் பற்றிப் புறம் பேச வேண்டாம்). இவ்வாறு அல்லாஹ் அதனைத் தடை செய்தான். இது அபூ தாவூத் தொகுத்த ஒரு ஹதீஸில் விளக்கப்பட்டுள்ளது. அபூ ஹுரைரா (ரழி) அவர்கள் கூறினார்கள்: \"'அல்லாஹ்வின் தூதரே! புறம் பேசுதல் என்றால் என்ன?' என்று கேட்கப்பட்டது.\" அதற்கு அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«ذِكْرُكَ أَخَاكَ بِمَا يَكْرَه»\n\r\n\n\r\n(உமது சகோதரர் விரும்பாத ஒரு விஷயத்தைக் கொண்டு அவரைப் பற்றிக் குறிப்பிடுவதாகும்.) \"'நான் சொல்வது என் சகோதரரிடம் உண்மையில் இருந்தாலுமா?' என்று கேட்கப்பட்டது.\" அதற்கு அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِنْ كَانَ فِيهِ مَا تَقُولُ فَقَدِ اغْتَبْتَهُ، وَإِنْ لَمْ يَكُنْ فِيهِ مَا تَقُولُ فَقَدْ بَهَتَّه»\n\r\n\n\r\n(நீர் சொல்வது அவரிடம் இருந்தால் நீர் அவரைப் பற்றிப் புறம் பேசினீர்; நீர் சொல்வது அவரிடம் இல்லையென்றால், நீர் அவர் மீது அவதூறு சுமத்தினீர்.)\" திர்மிதி இந்த ஹதீஸைச் சேகரித்து \"ஹஸன் ஸஹீஹ்\" எனக் குறிப்பிட்டுள்ளார். புறம் பேசுவது குறித்துக் கடுமையான எச்சரிக்கை விடுக்கப்பட்டுள்ளது. அதனால்தான் மேலானவனும் பாக்கியம் மிக்கவனுமான அல்லாஹ், அதனைத் தன் இறந்த சகோதரனின் மாமிசத்தை உண்பதற்கு ஒப்பிட்டுக் கூறினான்:\n\r\n\n\r\nأَيُحِبُّ أَحَدُكُمْ أَن يَأْكُلَ لَحْمَ أَخِيهِ مَيْتاً فَكَرِهْتُمُوهُ\n\r\n\n\r\n(உங்களில் எவராவது தன் இறந்த சகோதரனின் மாமிசத்தை உண்ண விரும்புவாரா? அதனை நீங்கள் வெறுப்பீர்கள்.) இறந்த மனிதனின் மாமிசத்தை உண்பதை உங்கள் இயற்கை உணர்வால் நீங்கள் எவ்வாறு வெறுக்கிறீர்களோ, அதுபோலவே உங்கள் மார்க்கத்தின் அடிப்படையில் புறம் பேசுவதையும் வெறுங்கள். பின்னது முன்னதை விடக் கடுமையான தண்டனைக்குரியது. இந்த வசனம் மக்களைப் புறம் பேசுவதிலிருந்து ஊக்கமிழக்கச் செய்யவும் அதற்கு எதிராக எச்சரிக்கவும் செய்கிறது. நபி (ஸல்) அவர்கள் ஒருவர் தான் கொடுத்த அன்பளிப்பைத் திரும்பப் பெறுவதைத் தடுப்பதற்காக இந்த வார்த்தைகளைப் பயன்படுத்தினார்கள்:\n\r\n\n\r\n«كَالْكَلْبِ يَقِيءُ ثُمَّ يَرْجِعُ فِي قَيْئِه»\n\r\n\n\r\n(அவன் தான் வாந்தி எடுத்துவிட்டு, அதனைத் தானே உண்ணும் நாயைப் போன்றவன்.) இவ்வாறு கூறிய பின்,\n\r\n\n\r\n«لَيْسَ لَنَا مَثَلُ السَّوْء»\n\r\n\n\r\n(நமக்குத் தீய உவமை தகாது) என்றார்கள்.\n\r\n\n\r\nஅபூ தாவூத் (ரஹ்) அவர்கள் பதிவு செய்துள்ளார்கள்: அபூ பர்ஸா அல்-அஸ்லமீ (ரழி) அவர்கள் அறிவிக்கிறார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் உரற்றியதாவது:\n\r\n\n\r\n«يَا مَعْشَرَ مَنْ آمَنَ بِلِسَانِهِ وَلَمْ يَدْخُلِ الْإِيمَانُ قَلْبَهُ، لَا تَغْتَابُوا الْمُسْلِمِينَ وَلَا تَتَّبِعُوا عَوْرَاتِهِمْ، فَإِنَّهُ مَنِ اتَّبَعَ عَوْرَاتِهِمْ يَتَّبِعِ اللهُ عَوْرَتَهُ، وَمَنْ يَتَّبِعِ اللهُ عَوْرَتَهُ يَفْضَحْهُ فِي بَيْتِه»\n\r\n\n\r\n(\"நாவால் ஈமான் கொண்டு, உள்ளத்தில் ஈமான் நுழையாதவர்களே! முஸ்லிம்களைப் பற்றிப் புறம் பேசாதீர்கள்; அவர்களின் குறைகளைத் துருவித் துருவி ஆராயாதீர்கள். ஏனெனில், எவன் அவர்களின் குறைகளைத் தேடித் திரிகிறானோ, அல்லாஹ் அவனது குறையைத் தேடுவான்; எவனது குறையை அல்லாஹ் தேடுகிறானோ, அவனை அவனது வீட்டிற்குள்ளேயே அல்லாஹ் இழிவுபடுத்தி விடுவான்.\")\n\r\n\n\r\nஅபூ தாவூத் (ரஹ்) அவர்கள் பதிவு செய்துள்ளார்கள்: அனஸ் (ரழி) அவர்கள் கூறினார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«لَمَّا عُرِجَ بِي مَرَرْتُ بِقَوْمٍ لَهُمْ أَظْفَارٌ مِنْ نُحَاسٍ يَخْمُشُونَ وُجُوهَهُمْ وَصُدُورَهُمْ، فَقُلْتُ: مَنْ هَؤُلَاءِ يَا جِبْرِيلُ؟ قَالَ: هَؤُلَاءِ الَّذِينَ يَأْكُلُونَ لُحُومَ النَّاسِ، وَيَقَعُونَ فِي أَعْرَاضِهِم»\n\r\n\n\r\n(\"நான் (விண்ணுலகிற்கு) அழைத்துச் செல்லப்பட்ட இரவில், செம்பினாலான நகங்களைக் கொண்ட சிலரைக் கடந்து சென்றேன். அவர்கள் தங்கள் முகங்களையும் நெஞ்சங்களையும் (அந்நகங்களால்) காயப்படுத்திக் கொண்டிருந்தார்கள். நான், ‘ஜிப்ரீலே! இவர்கள் யார்?’ என்று கேட்டேன். அதற்கு அவர், ‘இவர்கள் (பிற) மனிதர்களின் இறைச்சியைச் சாப்பிட்டு, அவர்களின் மானத்தில் கைவைத்தவர்கள் (புறம் பேசியவர்கள்)’ என்று கூறினார்.\")\n\r\n\n\r\nபல்வேறு அறிவிப்பாளர் தொடர்களின் வழியாக, நபி (ஸல்) அவர்கள் விடைபெறும் ஹஜ்ஜின் போது கூறியதாக ஸஹீஹ் மற்றும் முஸ்னத் நூல்கள் பதிவு செய்துள்ளன:\n\r\n\n\r\n«إِنَّ دِمَاءَكُمْ وَأَمْوَالَكُمْ وَأَعْرَاضَكُمْ عَلَيْكُمْ حَرَامٌ كَحُرْمَةِ يَوْمِكُمْ هذَا، فِي شَهْرِكُمْ هذَا، فِي بَلَدِكُمْ هذَا»\n\r\n\n\r\n(நிச்சயமாக உங்கள் இரத்தமும், உங்கள் செல்வமும், உங்கள் கண்ணியமும் உங்களுக்குள் புனிதமானவையாகும்; உங்களது இந்த நகரத்தில், இந்த மாதத்தில், இன்றைய தினத்தைப் போலவே புனிதமானதாகும்.) அபூ தாவூத் பதிவு செய்துள்ளார்கள்: அபூ ஹுரைரா (ரழி) அவர்கள் அறிவிக்கிறார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«كُلُّ الْمُسْلِمِ عَلَى الْمُسْلِمِ حَرَامٌ مَالُهُ وَعِرْضُهُ وَدَمُهُ، حَسْبُ امْرِىءٍ مِنَ الشَّرِّ أَنْ يَحْقِرَ أَخَاهُ الْمُسْلِم»\n\r\n\n\r\n(ஒவ்வொரு முஸ்லிமும் மற்றொரு முஸ்லிமுக்குத் தடை செய்யப்பட்டவர் (புனிதமானவர்); அவனது செல்வம், அவனது கண்ணியம் மற்றும் அவனது இரத்தம். ஒருவன் தன் முஸ்லிம் சகோதரனை இழிவாகக் கருதுவதே அவன் செய்த தீமைக்குப் போதுமானதாகும்.) திர்மிதி இந்த ஹதீஸைச் சேகரித்து \"ஹஸன் ஃகரீப்\" எனக் குறிப்பிட்டுள்ளார். அல்-ஹாஃபிழ் அபூ யஃலா அவர்கள் பதிவு செய்துள்ளார்கள்: அபூ ஹுரைரா (ரழி) அவர்கள் கூறினார்கள்: \"மாஇஸ் (ரழி) அவர்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் வந்து, 'அல்லாஹ்வின் தூதரே! நான் விபச்சாரம் செய்துவிட்டேன்' என்று கூறினார். அவர் தனது கூற்றை நான்கு முறை மீண்டும் சொல்லும் வரை அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அவரை விட்டும் முகத்தைத் திருப்பிக் கொண்டார்கள். ஐந்தாவது முறை, நபி (ஸல்) அவர்கள் அவரிடம் கேட்டார்கள்:\n\r\n\n\r\n«زَنَيْتَ؟»\n\r\n\n\r\n(நீ விபச்சாரம் செய்தாயா?) மாஇஸ் (ரழி) 'ஆம்' என்றார். நபி (ஸல்) அவர்கள் கேட்டார்கள்:\n\r\n\n\r\n«وَتَدْرِي مَا الزِّنَا؟»\n\r\n\n\r\n(விபச்சாரம் என்றால் என்னவென்று உனக்குத் தெரியுமா?) அதற்கு மாஇஸ் (ரழி) 'ஆம், ஒரு கணவன் தன் மனைவியுடன் சட்டப்பூர்வமாகச் செய்வதை, நான் அவளுடன் சட்டவிரோதமாகச் செய்துவிட்டேன்' என்றார். நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«مَا تُرِيدُ إِلَى هذَا الْقَوْلِ؟»\n\r\n\n\r\n(இந்தக் கூற்றின் மூலம் நீ எதை நாடுகிறாய்?) அதற்கு அவர் 'நீங்கள் என்னைத் தூய்மைப்படுத்த வேண்டும் என்று நான் நாடுகிறேன்' என்றார். நபி (ஸல்) அவர்கள் கேட்டார்கள்:\n\r\n\n\r\n«أَدْخَلْتَ ذلِكَ مِنْكَ فِي ذلِكَ مِنْهَا كَمَا يَغِيبُ الْمِيلُ فِي الْمُكْحُلَةِ وَالرِّشَا فِي الْبِئْرِ؟»\n\r\n\n\r\n(சுர்மா குச்சியானது சுர்மா சிமிழிலும், கயிறு கிணற்றிலும் நுழைவது போல் உன்னுடையது அவளுடையதில் நுழைந்ததா?) அவர் 'ஆம், அல்லாஹ்வின் தூதரே!' என்றார். நபி (ஸல்) அவர்கள் மாஇஸ் (ரழி) அவர்களுக்குக் கல்லால் எறிந்து மரண தண்டனை நிறைவேற்றக் கட்டளையிட்டார்கள்; அவ்வாறே நிறைவேற்றப்பட்டது. அதற்குப் பிறகு இரண்டு மனிதர்கள் தங்களுக்குள், 'அல்லாஹ் யாருடைய ரகசியத்தை மறைத்தானோ அந்த மனிதரைப் பார்த்தாயா? ஒரு நாய் கல்லால் எறியப்படுவது போல் கொல்லப்படும் வரை அவரது இதயம் அவரை அமைதியாக இருக்க விடவில்லை' என்று பேசிக்கொள்வதை நபி (ஸல்) அவர்கள் செவிமடுத்தார்கள். நபி (ஸல்) அவர்கள் தொடர்ந்து சென்றுகொண்டிருக்கும்போது ஒரு கழுதையின் சடலத்தைக் கடந்து சென்றார்கள். அப்போது அவர்கள் கேட்டார்கள்:\n\r\n\n\r\n«أَيْنَ فُلَانٌ وَفُلَانٌ؟ انْزِلَا فَكُلَا مِنْ جِيفَةِ هذَا الْحِمَار»\n\r\n\n\r\n(இன்னாரும் இன்னாரும் எங்கே? இறங்கி இந்தக் கழுதையின் சடலத்திலிருந்து உண்ணுங்கள்.) அதற்கு அவர்கள் 'அல்லாஹ் உங்களை மன்னிப்பானாக, அல்லாஹ்வின் தூதரே! இதனை யாராவது உண்பார்களா?' என்று கேட்டார்கள். அதற்கு நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«فَمَا نِلْتُمَا مِنْ أَخِيكُمَا آنِفًا أَشَدُّ أَكْلًا مِنْهُ، وَالَّذِي نَفْسِي بِيَدِهِ إِنَّهُ الْآنَ لَفِي أَنْهَارِ الْجَنَّةِ يَنْغَمِسُ فِيهَا»\n\r\n\n\r\n(சற்று முன்பு உங்கள் சகோதரனைப் பற்றி நீங்கள் பேசிய புறம், இதனை உண்பதை விடக் கடுமையானதாகும். எனது உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது சத்தியமாக! அவர் இப்போது சொர்க்கத்தின் ஆறுகளில் மூழ்கித் திளைத்துக் கொண்டிருக்கிறார்.)\" இந்த ஹதீஸின் அறிவிப்பாளர் தொடர் ஆதாரபூர்வமானது. இமாம் அஹ்மத் பதிவு செய்துள்ளார்: ஜாபிர் பின் அப்துல்லாஹ் (ரழி) அவர்கள் கூறினார்கள்: \"நாங்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுடன் இருந்தபோது, ஒரு அழுகிய துர்நாற்றத்தைக் காற்று கொண்டு வந்தது. அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கேட்டார்கள்:\n\r\n\n\r\n«أَتَدْرُونَ مَا هذِهِ الرِّيحُ؟ هَذِهِ رِيحُ الَّذِينَ يَغْتَابُونَ النَّاس»\n\r\n\n\r\n(இந்த நாற்றம் என்னவென்று உங்களுக்குத் தெரியுமா? இது மக்களைப் பற்றிப் புறம் பேசுபவர்களின் நாற்றமாகும்.)\"\n\r\n\n\r\nபுறம் பேசுதல் மற்றும் அவதூறிலிருந்து ஏற்றுக்கொள்ளப்பட்ட பாவமன்னிப்பு\n\r\n\n\r\nமேலானவனும் கண்ணியமிக்கவனுமான அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَاتَّقُواْ اللَّهَ\n\r\n\n\r\n(மேலும் அல்லாஹ்வுக்கு அஞ்சுங்கள் (தக்வா கொள்ளுங்கள்)), அதாவது அவன் உங்களுக்கு ஏவியவற்றிலும் விலக்கியவற்றிலும் (அவனை அஞ்சுங்கள்). அவனுக்குப் பயந்து அவரிடம் எச்சரிக்கையாக இருங்கள்.\n\r\n\n\r\nإِنَّ اللَّهَ تَوَّابٌ رَّحِيمٌ\n\r\n\n\r\n(நிச்சயமாக அல்லாஹ் பாவமன்னிப்பை ஏற்றுக்கொள்பவனாகவும், மகா கருணையாளனாகவும் இருக்கிறான்.) அவனிடம் பாவமன்னிப்புத் தேடுபவர்களை அவன் மன்னிக்கிறான்; அவனிடம் மீண்டு வருபவர்களிடமும் அவன் மீது நம்பிக்கை வைப்பவர்களிடமும் அவன் கருணை காட்டுகிறான். புறம் பேசிய பாவத்திற்காகச் செய்யப்படும் தவ்பா (பாவமன்னிப்பு) என்பது, மீண்டும் அதைச் செய்யக்கூடாது என்ற உறுதியுடன் புறம் பேசுவதிலிருந்து விலகியிருப்பதாகும் என்று பெரும்பான்மையான அறிஞர்கள் கூறியுள்ளனர். இதில் வருத்தம் தெரிவிப்பது அவசியமா என்பதிலும், யாரிடம் புறம் பேசப்பட்டதோ அவரிடம் மன்னிப்புக் கேட்க வேண்டுமா என்பதிலும் கருத்து வேறுபாடுகள் உள்ளன. சில அறிஞர்கள் யாரிடம் புறம் பேசப்பட்டதோ அவரிடம் மன்னிப்புக் கேட்பது அவசியமில்லை எனக் கூறுகின்றனர்; ஏனெனில், தங்களைப் பற்றிப் பேசப்பட்டதைத் தெரிந்தால் அவர்கள் இன்னும் அதிகமாக வேதனைப்படக்கூடும். எனவே, எந்த சபையில் ஒருவரைப் பற்றிப் புறம் பேசப்பட்டதோ, அதே சபையில் அவரைப் புகழ்ந்து பேசுவதே சிறந்தது என அவர்கள் கூறுகின்றனர். மேலும், முன்னர் செய்த புறம் பேசுதலுக்குப் பரிகாரமாக, பாதிக்கப்பட்டவரை மீண்டும் மற்றவர்கள் புறம் பேசாதவாறு தன்னால் முடிந்தவரைத் தடுத்துப் பாதுகாப்பதும் சிறந்தது."},"13":{"html":"<strong>ஆதம் (அலை) மற்றும் ஹவ்வா (அலை) அவர்களின் சந்ததிகளே மனிதகுலம் அனைத்தும்</strong><br />\r\n<br />\r\nமேலான அல்லாஹ், மனிதர்கள் அனைவரையும் ஆதம் (அலை) எனும் ஒரே மனிதரிலிருந்தும், அவரிடமிருந்து அவரது துணையாகிய ஹவ்வா (அலை) அவர்களையும் படைத்ததாக மனிதகுலத்திற்கு அறிவிக்கிறான். அவர்களது சந்ததிகளிலிருந்து அவன் பல்வேறு நாடுகளையும் (தேசங்களையும்), சிறியதும் பெரியதுமான கிளைக் கோத்திரங்களைக் கொண்ட கோத்திரங்களையும் உருவாக்கினான். 'ஷுஊப்' (தேசங்கள்) என்பது அரபியல்லாதவர்களையும், 'கபாயில்' (கோத்திரங்கள்) என்பது அரபியர்களையும் குறிக்கும் என்றும் கூறப்பட்டுள்ளது. இது தொடர்பான பல்வேறு கருத்துக்கள், அபூ அம்ர் இப்னு அப்துல்-பர்ர் அவர்களின் 'அல்-இன்பாஹ்' எனும் நூலின் முன்னுரையிலும், 'அல்-கஸத் வல்-அமாம் ஃபீ மஃரிஃபதி அன்ஸாப் அல்-அரப் வல்-அஜம்' எனும் நூலிலும் தொகுக்கப்பட்டுள்ளன. எனவே, மக்கள் அனைவரும் ஆதம் (அலை) மற்றும் ஹவ்வா (அலை) ஆகியோரின் வழித்தோன்றல்களே; இந்த கண்ணியத்தில் அனைவரும் சமமானவர்களே. அவர்களுக்கு இடையிலான ஒரே வேறுபாடு, மேலான அல்லாஹ்வுக்குக் கீழ்ப்படிவதிலும் அவனது தூதர் (ஸல்) அவர்களைப் பின்பற்றுவதிலும் அமைந்துள்ள மார்க்கப்பற்று மட்டுமே. புறம் பேசுவதையும் பிறரை இழிவாகக் கருதுவதையும் தடை செய்த பிறகு, மனிதர்கள் அனைவரும் மனிதாபிமான அடிப்படையில் சமமானவர்களே என்று உணர்த்தும் வகையில் அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يأَيُّهَا</span> <span class=\"quran-arabic-font text-success\">النَّاسُ</span> <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">خَلَقْنَـكُم</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">ذَكَرٍ</span> <span class=\"quran-arabic-font text-success\">وَأُنْثَى</span> <span class=\"quran-arabic-font text-success\">وَجَعَلْنَـكُمْ</span> <span class=\"quran-arabic-font text-success\">شُعُوباً</span> <span class=\"quran-arabic-font text-success\">وَقَبَآئِلَ</span> <span class=\"quran-arabic-font text-success\">لِتَعَـرَفُواْ</span><br />\r\n<br />\r\n(மனிதர்களே! நிச்சயமாக நாம் உங்களை ஓர் ஆண் மற்றும் ஒரு பெண்ணிலிருந்தே படைத்தோம்; மேலும் நீங்கள் ஒருவரையொருவர் அறிந்துகொள்வதற்காக உங்களை நாடுகளாகவும் (தேசங்களாகவும்) கோத்திரங்களாகவும் ஆக்கினோம்.) அதாவது, அவர்கள் தங்கள் தேசம் அல்லது கோத்திரத்தின் மூலம் ஒருவரையொருவர் அடையாளம் கண்டு கொள்வதற்காக. அல்லாஹ்வின் வசனமான,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِتَعَـرَفُواْ</span><br />\r\n<br />\r\n(நீங்கள் ஒருவரையொருவர் அறிந்துகொள்வதற்காக.) என்பது, \"இன்னாரின் மகனான இன்னார், இன்ன கோத்திரத்தைச் சேர்ந்தவர்\" என்று ஒருவர் தங்களை அறிமுகப்படுத்திக் கொள்வதைக் குறிக்கிறது என்று முஜாஹித் (ரஹ்) அவர்கள் கூறினார்கள். சுஃப்யான் அத்-தவ்ரீ (ரஹ்) அவர்கள் கூறுகையில்: \"(யமனிலிருந்த) ஹிம்யர் கோத்திரத்தினர் தங்கள் மாகாணங்களின் அடிப்படையில் ஒருவரையொருவர் அடையாளம் கண்டு கொண்டனர். அதேசமயம் ஹிஜாஸ் (மேற்கு அரேபியா) பகுதியிலிருந்த அரபியர்கள் தங்கள் கோத்திரங்களின் அடிப்படையில் ஒருவரையொருவர் அடையாளம் கண்டு கொண்டனர்.\"<br />\r\n<br />\r\n<strong>தக்வாவினால் (இறை அச்சத்தினால்) மட்டுமே கண்ணியம் கிடைக்கிறது</strong><br />\r\n<br />\r\nமேலான அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">أَكْرَمَكُمْ</span> <span class=\"quran-arabic-font text-success\">عَندَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">أَتْقَـكُمْ</span><br />\r\n<br />\r\n(நிச்சயமாக, அல்லாஹ்விடம் உங்களில் மிகக் கண்ணியமானவர் உங்களில் அதிக தக்வா (இறை அச்சம்) உடையவரே ஆவார்.) அதாவது, 'மேலான அல்லாஹ்விடம் நீங்கள் கண்ணியத்தைப் பெறுவது உங்களது குடும்பப் பாரம்பரியத்தினால் அல்ல, மாறாக தக்வாவின் மூலமேயாகும்.' இக்கருத்தை உறுதிப்படுத்தும் பல ஹதீஸ்கள் நபி (ஸல்) அவர்களிடமிருந்து அறிவிக்கப்பட்டுள்ளன. இமாம் புகாரி (ரஹ்), அபூ ஹுரைரா (ரழி) அவர்கள் அறிவிப்பதாகப் பதிவு செய்துள்ளார்கள்: \"மக்களில் மிகவும் கண்ணியமானவர் யார்? என்று சிலர் நபி (ஸல்) அவர்களிடம் கேட்டார்கள். அதற்கு அவர்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَكْرَمُهُمْ</span> <span class=\"quran-arabic-font text-success\">عِنْدَ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">أَتْقَاهُم</span>»<br />\r\n<br />\r\n(அவர்களில் யார் அதிக தக்வா உடையவரோ, அவரே அல்லாஹ்விடம் மிகவும் கண்ணியமானவர்) என்று பதிலளித்தார்கள். அதற்கு அவர்கள்: 'நாங்கள் இதைப் பற்றிக் கேட்கவில்லை' என்றார்கள். அப்போது நபி (ஸல்) அவர்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">فَأَكْرَمُ</span> <span class=\"quran-arabic-font text-success\">النَّاسِ</span> <span class=\"quran-arabic-font text-success\">يُوسُفُ</span> <span class=\"quran-arabic-font text-success\">نَبِيُّ</span> <span class=\"quran-arabic-font text-success\">اللهِ،</span> <span class=\"quran-arabic-font text-success\">ابْنُ</span> <span class=\"quran-arabic-font text-success\">نَبِيِّ</span> <span class=\"quran-arabic-font text-success\">اللهِ،</span> <span class=\"quran-arabic-font text-success\">ابْنِ</span> <span class=\"quran-arabic-font text-success\">نَبِيِّ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">ابْنِ</span> <span class=\"quran-arabic-font text-success\">خَلِيلِ</span> <span class=\"quran-arabic-font text-success\">الله</span>»<br />\r\n<br />\r\n(அப்படியானால், அல்லாஹ்வின் கலீலுடைய (நண்பருடைய) மகனின், மகனின், மகனான அல்லாஹ்வின் நபியாகிய யூசுஃப் (அலை) அவர்களே மக்களில் மிகவும் கண்ணியமானவர்) என்றார்கள். அப்போதும் அவர்கள்: 'நாங்கள் இதைப் பற்றிக் கேட்கவில்லை' என்றார்கள். நபி (ஸல்) அவர்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">فَعَنْ</span> <span class=\"quran-arabic-font text-success\">مَعَادِنِ</span> <span class=\"quran-arabic-font text-success\">الْعَرَبِ</span> <span class=\"quran-arabic-font text-success\">تَسْأَلُونِّي</span>»<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">؟</span> (அப்படியானால், அரபு வம்சாவளிகளைப் பற்றித் தான் நீங்கள் என்னிடம் கேட்கிறீர்களா?) என்று கேட்டார்கள். அவர்கள்: 'ஆம்' என்றார்கள். நபி (ஸல்) அவர்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">فَخِيَارُكُمْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْجَاهِلِيَّةِ</span> <span class=\"quran-arabic-font text-success\">خِيَارُكُمْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْإِسْلَامِ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">فَقُهُوا</span>»<br />\r\n<br />\r\n(ஜாஹிலிய்யா (அறியாமை) காலத்தில் உங்களில் சிறந்தவர்களாக இருந்தவர்களே இஸ்லாத்திலும் சிறந்தவர்கள்; அவர்கள் மார்க்க அறிவைப் பெற்றிருந்தால்) என்று கூறினார்கள்.\" இமாம் புகாரி (ரஹ்) இந்த ஹதீஸைத் தமது ஸஹீஹ் நூலில் பல இடங்களிலும், இமாம் நஸாயீ (ரஹ்) அவர்கள் தமது சுனன் நூலின் தஃப்ஸீர் பிரிவிலும் பதிவு செய்துள்ளனர். இமாம் முஸ்லிம் (ரஹ்), அபூ ஹுரைரா (ரழி) அவர்கள் வாயிலாகப் பதிவு செய்துள்ளார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَنْظُرُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">صُوَرِكُمْ</span> <span class=\"quran-arabic-font text-success\">وَأَمْوَالِكُمْ</span> <span class=\"quran-arabic-font text-success\">وَلكِنْ</span> <span class=\"quran-arabic-font text-success\">يَنْظُرُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">قُلُوبِكُمْ</span> <span class=\"quran-arabic-font text-success\">وَأَعْمَالِكُم</span>»<br />\r\n<br />\r\n(நிச்சயமாக, அல்லாஹ் உங்கள் உருவங்களையோ உங்கள் செல்வங்களையோ பார்ப்பதில்லை. மாறாக, அவன் உங்கள் உள்ளங்களையும் உங்கள் செயல்களையுமே பார்க்கிறான்). இப்னு மாஜா (ரஹ்) அவர்களும் இந்த ஹதீஸைப் பதிவு செய்துள்ளார்கள். இமாம் இப்னு அபீ ஹாதிம் (ரஹ்), அப்துல்லாஹ் பின் உமர் (ரழி) அவர்கள் அறிவிப்பதாகப் பதிவு செய்துள்ளார்கள்: \"மக்கா வெற்றிகொள்ளப்பட்ட நாளில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தங்களது 'அல்-கஸ்வா' எனும் ஒட்டகத்தின் மீது அமர்ந்து கஃபாவைத் தவாஃப் செய்தார்கள். அப்போது தமது கையிலிருந்த ஒரு குச்சியால் கஃபாவின் மூலைகளைத் தொட்டுக் கொண்டிருந்தார்கள். மஸ்ஜிதுல் ஹராமில் ஒட்டகம் அமர்வதற்கு இடம் கிடைக்காததால், மனிதர்களின் கைகளின் உதவியோடு அவர்கள் கீழே இறங்கினார்கள். அவர்கள் தமது ஒட்டகத்தைப் பள்ளத்தாக்கின் அடிப்பகுதிக்குக் கொண்டு சென்று அமர வைத்தார்கள். பின்னர் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அல்-கஸ்வாவின் மீது அமர்ந்தபடி உரை நிகழ்த்தினார்கள். மேலான அல்லாஹ்வைப் போற்றிப் புகழ்ந்த பிறகு அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">أَيُّهَا</span> <span class=\"quran-arabic-font text-success\">النَّاسُ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">تَعَالَى</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">أَذْهَبَ</span> <span class=\"quran-arabic-font text-success\">عَنْكُمْ</span> <span class=\"quran-arabic-font text-success\">عُبِّيَّةَ</span> <span class=\"quran-arabic-font text-success\">الْجَاهِلِيَّةِ</span> <span class=\"quran-arabic-font text-success\">وَتَعَظُّمَهَا</span> <span class=\"quran-arabic-font text-success\">بِآبَائِهَا،</span> <span class=\"quran-arabic-font text-success\">فَالنَّاسُ</span> <span class=\"quran-arabic-font text-success\">رَجُلَانِ</span>: <span class=\"quran-arabic-font text-success\">رَجُلٌ</span> <span class=\"quran-arabic-font text-success\">بَرٌّ</span> <span class=\"quran-arabic-font text-success\">تَقِيٌّ</span> <span class=\"quran-arabic-font text-success\">كَرِيمٌ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">تَعَالَى،</span> <span class=\"quran-arabic-font text-success\">وَرَجُلٌ</span> <span class=\"quran-arabic-font text-success\">فَاجِرٌ</span> <span class=\"quran-arabic-font text-success\">شَقِيٌّ</span> <span class=\"quran-arabic-font text-success\">هَيِّنٌ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">تَعَالَى،</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">عَزَّ</span> <span class=\"quran-arabic-font text-success\">وَجَلَّ</span> <span class=\"quran-arabic-font text-success\">يَقُولُ</span>:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يأَيُّهَا</span> <span class=\"quran-arabic-font text-success\">النَّاسُ</span> <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">خَلَقْنَـكُم</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">ذَكَرٍ</span> <span class=\"quran-arabic-font text-success\">وَأُنْثَى</span> <span class=\"quran-arabic-font text-success\">وَجَعَلْنَـكُمْ</span> <span class=\"quran-arabic-font text-success\">شُعُوباً</span> <span class=\"quran-arabic-font text-success\">وَقَبَآئِلَ</span> <span class=\"quran-arabic-font text-success\">لِتَعَـرَفُواْ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">أَكْرَمَكُمْ</span> <span class=\"quran-arabic-font text-success\">عَندَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">أَتْقَـكُمْ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">عَلِيمٌ</span> <span class=\"quran-arabic-font text-success\">خَبِيرٌ</span> »<br />\r\n<br />\r\n(மக்களே! ஜாஹிலிய்யா காலத்துப் பெருமைகளையும், தங்களது முன்னோர்களைக் கொண்டு பெருமை பாராட்டும் பழக்கத்தையும் மேலான அல்லாஹ் உங்களிடமிருந்து அகற்றிவிட்டான். மனிதர்கள் இரு வகையினரே: ஒருவன் நல்லவன், தக்வா உடையவன், அவன் மேலான அல்லாஹ்விடம் கண்ணியமானவன். மற்றொருவன் பாவி, துரதிர்ஷ்டசாலி, அவன் மேலான அல்லாஹ்விடம் அற்பமானவன். நிச்சயமாக, வல்லமையும் கண்ணியமும் மிக்க அல்லாஹ் கூறுகிறான்: (மனிதர்களே! நிச்சயமாக நாம் உங்களை ஓர் ஆண் மற்றும் ஒரு பெண்ணிலிருந்தே படைத்தோம்; மேலும் நீங்கள் ஒருவரையொருவர் அறிந்துகொள்வதற்காக உங்களை நாடுகளாகவும் கோத்திரங்களாகவும் ஆக்கினோம். நிச்சயமாக, அல்லாஹ்விடம் உங்களில் மிகக் கண்ணியமானவர் உங்களில் அதிக தக்வா உடையவரே ஆவார். நிச்சயமாக அல்லாஹ் எல்லாம் அறிந்தவன், நன்கறிந்தவன்.))\" நபி (ஸல்) அவர்கள் மேலும் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَقُولُ</span> <span class=\"quran-arabic-font text-success\">قَوْلِي</span> <span class=\"quran-arabic-font text-success\">هذَا</span> <span class=\"quran-arabic-font text-success\">وَأَسْتَغْفِرُ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">لِي</span> <span class=\"quran-arabic-font text-success\">وَلَكُم</span>»<br />\r\n<br />\r\n(நான் இதைக் கூறிவிட்டு, எனக்காகவும் உங்களுக்காகவும் அல்லாஹ்விடம் மன்னிப்புக் கோருகிறேன்.)\" இதனை அப்த் பின் ஹுமைத் பதிவு செய்துள்ளார்கள்.<br />\r\n<br />\r\nமேலும் இமாம் அஹ்மத் (ரஹ்) அவர்கள் பதிவு செய்துள்ளார்கள்: அபூ நழ்ரா (ரஹ்) அவர்கள், அய்யாமுத் தஷ்ரீக் (ஹஜ்ஜின் போது மினாவில் தங்கும்) நாட்களின் நடுப்பகுதியில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஆற்றிய உரையைக் கேட்ட ஒருவரிடமிருந்து அறிவிக்கிறார்கள்: (அதில் நபி (ஸல்) அவர்கள் கூறினார்கள்:)<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">أَيُّهَا</span> <span class=\"quran-arabic-font text-success\">النَّاسُ،</span> <span class=\"quran-arabic-font text-success\">أَلَا</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">رَبَّكُمْ</span> <span class=\"quran-arabic-font text-success\">وَاحِدٌ،</span> <span class=\"quran-arabic-font text-success\">وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">أَبَاكُمْ</span> <span class=\"quran-arabic-font text-success\">وَاحِدٌ،</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">فَضْلَ</span> <span class=\"quran-arabic-font text-success\">لِعَرَبِيٍّ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَعْجَمِيٍّ،</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">لِعَجَمِيٍّ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">عَرَبِيٍّ،</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">لِأَحْمَرَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَسْوَدَ،</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">لِأَسْوَدَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَحْمَرَ،</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">بِالتَّقْوَى،</span> <span class=\"quran-arabic-font text-success\">أَبَلَّغْتُ؟</span>»<br />\r\n<br />\r\n(\"மக்களே! அறிந்துகொள்ளுங்கள்! நிச்சயமாக உங்கள் இறைவன் ஒருவனே; உங்கள் தந்தை ஒருவரே. ஓர் அரபியருக்கு அரபியல்லாதவரை விடவோ, அரபியல்லாதவருக்கு அரபியரை விடவோ, சிவப்பு நிறத்தவருக்குக் கருப்பரை விடவோ, கருப்பருக்குச் சிவப்பு நிறத்தவரை விடவோ தக்வாவைத் தவிர வேறு எவ்விதச் சிறப்பும் இல்லை. நான் (இச்செய்தியை) சேர்த்துவிட்டேனா?\") என்று கேட்டார்கள். அதற்கு மக்கள், \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் சேர்த்துவிட்டார்கள்\" என்று பதிலளித்தார்கள். பிறகு, \"இங்கு வந்திருப்பவர் வராதவருக்கு இதனை எடுத்துரைக்கட்டும்\" என்று கூறினார்கள்.<br />\r\n<br />\r\nமேலான அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">عَلِيمٌ</span> <span class=\"quran-arabic-font text-success\">خَبِيرٌ</span><br />\r\n<br />\r\n(நிச்சயமாக அல்லாஹ் எல்லாம் அறிந்தவன், நன்கறிந்தவன்). இதன் பொருள், அவன் உங்களைப் பற்றியும், உங்கள் அனைத்து விவகாரங்கள் குறித்தும் நன்கறிந்தவன் என்பதாகும். அல்லாஹ் தான் நாடியவர்களுக்கு நேர்வழி காட்டுகிறான், தான் நாடியவர்களை வழிகேட்டில் விடுகிறான், தான் நாடியவர்கள் மீது கருணை காட்டுகிறான், தான் நாடியவர்களைத் தண்டிக்கிறான், தான் நாடியவர்களை மற்றவர்களை விட உயர்த்துகிறான். இவை அனைத்திலும் அவன் மிக்க ஞானமுடையவனாகவும், எல்லாம் அறிந்தவனாகவும், நன்கறிந்தவனாகவும் இருக்கிறான். திருமண ஒப்பந்தத்தின்போது (இரு குடும்பத்தாருக்கும் இடையிலான) அந்தஸ்து சமமாக இருக்க வேண்டும் என்பது ஒரு கட்டாய நிபந்தனையல்ல என்பதற்கு இந்த கண்ணியமிக்க வசனத்தையும் நாம் குறிப்பிட்ட ஹதீஸ்களையும் பல அறிஞர்கள் ஆதாரமாகக் கொள்கின்றனர். இவ்விஷயத்தில் தேவைப்படும் ஒரே தகுதி மார்க்கப்பற்று மட்டுமே என்று அவர்கள் கூறுகின்றனர். மேலான அல்லாஹ் கூறியிருப்பதைப் போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">أَكْرَمَكُمْ</span> <span class=\"quran-arabic-font text-success\">عَندَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">أَتْقَـكُمْ</span><br />\r\n<br />\r\n(நிச்சயமாக, அல்லாஹ்விடம் உங்களில் மிகக் கண்ணியமானவர் உங்களில் அதிக தக்வா உடையவரே.)<br />\r\n<br />","text":"ஆதம் (அலை) மற்றும் ஹவ்வா (அலை) அவர்களின் சந்ததிகளே மனிதகுலம் அனைத்தும்\n\r\n\n\r\nமேலான அல்லாஹ், மனிதர்கள் அனைவரையும் ஆதம் (அலை) எனும் ஒரே மனிதரிலிருந்தும், அவரிடமிருந்து அவரது துணையாகிய ஹவ்வா (அலை) அவர்களையும் படைத்ததாக மனிதகுலத்திற்கு அறிவிக்கிறான். அவர்களது சந்ததிகளிலிருந்து அவன் பல்வேறு நாடுகளையும் (தேசங்களையும்), சிறியதும் பெரியதுமான கிளைக் கோத்திரங்களைக் கொண்ட கோத்திரங்களையும் உருவாக்கினான். 'ஷுஊப்' (தேசங்கள்) என்பது அரபியல்லாதவர்களையும், 'கபாயில்' (கோத்திரங்கள்) என்பது அரபியர்களையும் குறிக்கும் என்றும் கூறப்பட்டுள்ளது. இது தொடர்பான பல்வேறு கருத்துக்கள், அபூ அம்ர் இப்னு அப்துல்-பர்ர் அவர்களின் 'அல்-இன்பாஹ்' எனும் நூலின் முன்னுரையிலும், 'அல்-கஸத் வல்-அமாம் ஃபீ மஃரிஃபதி அன்ஸாப் அல்-அரப் வல்-அஜம்' எனும் நூலிலும் தொகுக்கப்பட்டுள்ளன. எனவே, மக்கள் அனைவரும் ஆதம் (அலை) மற்றும் ஹவ்வா (அலை) ஆகியோரின் வழித்தோன்றல்களே; இந்த கண்ணியத்தில் அனைவரும் சமமானவர்களே. அவர்களுக்கு இடையிலான ஒரே வேறுபாடு, மேலான அல்லாஹ்வுக்குக் கீழ்ப்படிவதிலும் அவனது தூதர் (ஸல்) அவர்களைப் பின்பற்றுவதிலும் அமைந்துள்ள மார்க்கப்பற்று மட்டுமே. புறம் பேசுவதையும் பிறரை இழிவாகக் கருதுவதையும் தடை செய்த பிறகு, மனிதர்கள் அனைவரும் மனிதாபிமான அடிப்படையில் சமமானவர்களே என்று உணர்த்தும் வகையில் அல்லாஹ் கூறினான்:\n\r\n\n\r\nيأَيُّهَا النَّاسُ إِنَّا خَلَقْنَـكُم مِّن ذَكَرٍ وَأُنْثَى وَجَعَلْنَـكُمْ شُعُوباً وَقَبَآئِلَ لِتَعَـرَفُواْ\n\r\n\n\r\n(மனிதர்களே! நிச்சயமாக நாம் உங்களை ஓர் ஆண் மற்றும் ஒரு பெண்ணிலிருந்தே படைத்தோம்; மேலும் நீங்கள் ஒருவரையொருவர் அறிந்துகொள்வதற்காக உங்களை நாடுகளாகவும் (தேசங்களாகவும்) கோத்திரங்களாகவும் ஆக்கினோம்.) அதாவது, அவர்கள் தங்கள் தேசம் அல்லது கோத்திரத்தின் மூலம் ஒருவரையொருவர் அடையாளம் கண்டு கொள்வதற்காக. அல்லாஹ்வின் வசனமான,\n\r\n\n\r\nلِتَعَـرَفُواْ\n\r\n\n\r\n(நீங்கள் ஒருவரையொருவர் அறிந்துகொள்வதற்காக.) என்பது, \"இன்னாரின் மகனான இன்னார், இன்ன கோத்திரத்தைச் சேர்ந்தவர்\" என்று ஒருவர் தங்களை அறிமுகப்படுத்திக் கொள்வதைக் குறிக்கிறது என்று முஜாஹித் (ரஹ்) அவர்கள் கூறினார்கள். சுஃப்யான் அத்-தவ்ரீ (ரஹ்) அவர்கள் கூறுகையில்: \"(யமனிலிருந்த) ஹிம்யர் கோத்திரத்தினர் தங்கள் மாகாணங்களின் அடிப்படையில் ஒருவரையொருவர் அடையாளம் கண்டு கொண்டனர். அதேசமயம் ஹிஜாஸ் (மேற்கு அரேபியா) பகுதியிலிருந்த அரபியர்கள் தங்கள் கோத்திரங்களின் அடிப்படையில் ஒருவரையொருவர் அடையாளம் கண்டு கொண்டனர்.\"\n\r\n\n\r\nதக்வாவினால் (இறை அச்சத்தினால்) மட்டுமே கண்ணியம் கிடைக்கிறது\n\r\n\n\r\nமேலான அல்லாஹ் கூறினான்:\n\r\n\n\r\nإِنَّ أَكْرَمَكُمْ عَندَ اللَّهِ أَتْقَـكُمْ\n\r\n\n\r\n(நிச்சயமாக, அல்லாஹ்விடம் உங்களில் மிகக் கண்ணியமானவர் உங்களில் அதிக தக்வா (இறை அச்சம்) உடையவரே ஆவார்.) அதாவது, 'மேலான அல்லாஹ்விடம் நீங்கள் கண்ணியத்தைப் பெறுவது உங்களது குடும்பப் பாரம்பரியத்தினால் அல்ல, மாறாக தக்வாவின் மூலமேயாகும்.' இக்கருத்தை உறுதிப்படுத்தும் பல ஹதீஸ்கள் நபி (ஸல்) அவர்களிடமிருந்து அறிவிக்கப்பட்டுள்ளன. இமாம் புகாரி (ரஹ்), அபூ ஹுரைரா (ரழி) அவர்கள் அறிவிப்பதாகப் பதிவு செய்துள்ளார்கள்: \"மக்களில் மிகவும் கண்ணியமானவர் யார்? என்று சிலர் நபி (ஸல்) அவர்களிடம் கேட்டார்கள். அதற்கு அவர்கள்:\n\r\n\n\r\n«أَكْرَمُهُمْ عِنْدَ اللهِ أَتْقَاهُم»\n\r\n\n\r\n(அவர்களில் யார் அதிக தக்வா உடையவரோ, அவரே அல்லாஹ்விடம் மிகவும் கண்ணியமானவர்) என்று பதிலளித்தார்கள். அதற்கு அவர்கள்: 'நாங்கள் இதைப் பற்றிக் கேட்கவில்லை' என்றார்கள். அப்போது நபி (ஸல்) அவர்கள்:\n\r\n\n\r\n«فَأَكْرَمُ النَّاسِ يُوسُفُ نَبِيُّ اللهِ، ابْنُ نَبِيِّ اللهِ، ابْنِ نَبِيِّ اللهِ ابْنِ خَلِيلِ الله»\n\r\n\n\r\n(அப்படியானால், அல்லாஹ்வின் கலீலுடைய (நண்பருடைய) மகனின், மகனின், மகனான அல்லாஹ்வின் நபியாகிய யூசுஃப் (அலை) அவர்களே மக்களில் மிகவும் கண்ணியமானவர்) என்றார்கள். அப்போதும் அவர்கள்: 'நாங்கள் இதைப் பற்றிக் கேட்கவில்லை' என்றார்கள். நபி (ஸல்) அவர்கள்:\n\r\n\n\r\n«فَعَنْ مَعَادِنِ الْعَرَبِ تَسْأَلُونِّي»\n\r\n\n\r\n؟ (அப்படியானால், அரபு வம்சாவளிகளைப் பற்றித் தான் நீங்கள் என்னிடம் கேட்கிறீர்களா?) என்று கேட்டார்கள். அவர்கள்: 'ஆம்' என்றார்கள். நபி (ஸல்) அவர்கள்:\n\r\n\n\r\n«فَخِيَارُكُمْ فِي الْجَاهِلِيَّةِ خِيَارُكُمْ فِي الْإِسْلَامِ إِذَا فَقُهُوا»\n\r\n\n\r\n(ஜாஹிலிய்யா (அறியாமை) காலத்தில் உங்களில் சிறந்தவர்களாக இருந்தவர்களே இஸ்லாத்திலும் சிறந்தவர்கள்; அவர்கள் மார்க்க அறிவைப் பெற்றிருந்தால்) என்று கூறினார்கள்.\" இமாம் புகாரி (ரஹ்) இந்த ஹதீஸைத் தமது ஸஹீஹ் நூலில் பல இடங்களிலும், இமாம் நஸாயீ (ரஹ்) அவர்கள் தமது சுனன் நூலின் தஃப்ஸீர் பிரிவிலும் பதிவு செய்துள்ளனர். இமாம் முஸ்லிம் (ரஹ்), அபூ ஹுரைரா (ரழி) அவர்கள் வாயிலாகப் பதிவு செய்துள்ளார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِنَّ اللهَ لَا يَنْظُرُ إِلَى صُوَرِكُمْ وَأَمْوَالِكُمْ وَلكِنْ يَنْظُرُ إِلَى قُلُوبِكُمْ وَأَعْمَالِكُم»\n\r\n\n\r\n(நிச்சயமாக, அல்லாஹ் உங்கள் உருவங்களையோ உங்கள் செல்வங்களையோ பார்ப்பதில்லை. மாறாக, அவன் உங்கள் உள்ளங்களையும் உங்கள் செயல்களையுமே பார்க்கிறான்). இப்னு மாஜா (ரஹ்) அவர்களும் இந்த ஹதீஸைப் பதிவு செய்துள்ளார்கள். இமாம் இப்னு அபீ ஹாதிம் (ரஹ்), அப்துல்லாஹ் பின் உமர் (ரழி) அவர்கள் அறிவிப்பதாகப் பதிவு செய்துள்ளார்கள்: \"மக்கா வெற்றிகொள்ளப்பட்ட நாளில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தங்களது 'அல்-கஸ்வா' எனும் ஒட்டகத்தின் மீது அமர்ந்து கஃபாவைத் தவாஃப் செய்தார்கள். அப்போது தமது கையிலிருந்த ஒரு குச்சியால் கஃபாவின் மூலைகளைத் தொட்டுக் கொண்டிருந்தார்கள். மஸ்ஜிதுல் ஹராமில் ஒட்டகம் அமர்வதற்கு இடம் கிடைக்காததால், மனிதர்களின் கைகளின் உதவியோடு அவர்கள் கீழே இறங்கினார்கள். அவர்கள் தமது ஒட்டகத்தைப் பள்ளத்தாக்கின் அடிப்பகுதிக்குக் கொண்டு சென்று அமர வைத்தார்கள். பின்னர் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அல்-கஸ்வாவின் மீது அமர்ந்தபடி உரை நிகழ்த்தினார்கள். மேலான அல்லாஹ்வைப் போற்றிப் புகழ்ந்த பிறகு அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«يَا أَيُّهَا النَّاسُ إِنَّ اللهَ تَعَالَى قَدْ أَذْهَبَ عَنْكُمْ عُبِّيَّةَ الْجَاهِلِيَّةِ وَتَعَظُّمَهَا بِآبَائِهَا، فَالنَّاسُ رَجُلَانِ: رَجُلٌ بَرٌّ تَقِيٌّ كَرِيمٌ عَلَى اللهِ تَعَالَى، وَرَجُلٌ فَاجِرٌ شَقِيٌّ هَيِّنٌ عَلَى اللهِ تَعَالَى، إِنَّ اللهَ عَزَّ وَجَلَّ يَقُولُ:\n\r\n\n\r\nيأَيُّهَا النَّاسُ إِنَّا خَلَقْنَـكُم مِّن ذَكَرٍ وَأُنْثَى وَجَعَلْنَـكُمْ شُعُوباً وَقَبَآئِلَ لِتَعَـرَفُواْ إِنَّ أَكْرَمَكُمْ عَندَ اللَّهِ أَتْقَـكُمْ إِنَّ اللَّهَ عَلِيمٌ خَبِيرٌ »\n\r\n\n\r\n(மக்களே! ஜாஹிலிய்யா காலத்துப் பெருமைகளையும், தங்களது முன்னோர்களைக் கொண்டு பெருமை பாராட்டும் பழக்கத்தையும் மேலான அல்லாஹ் உங்களிடமிருந்து அகற்றிவிட்டான். மனிதர்கள் இரு வகையினரே: ஒருவன் நல்லவன், தக்வா உடையவன், அவன் மேலான அல்லாஹ்விடம் கண்ணியமானவன். மற்றொருவன் பாவி, துரதிர்ஷ்டசாலி, அவன் மேலான அல்லாஹ்விடம் அற்பமானவன். நிச்சயமாக, வல்லமையும் கண்ணியமும் மிக்க அல்லாஹ் கூறுகிறான்: (மனிதர்களே! நிச்சயமாக நாம் உங்களை ஓர் ஆண் மற்றும் ஒரு பெண்ணிலிருந்தே படைத்தோம்; மேலும் நீங்கள் ஒருவரையொருவர் அறிந்துகொள்வதற்காக உங்களை நாடுகளாகவும் கோத்திரங்களாகவும் ஆக்கினோம். நிச்சயமாக, அல்லாஹ்விடம் உங்களில் மிகக் கண்ணியமானவர் உங்களில் அதிக தக்வா உடையவரே ஆவார். நிச்சயமாக அல்லாஹ் எல்லாம் அறிந்தவன், நன்கறிந்தவன்.))\" நபி (ஸல்) அவர்கள் மேலும் கூறினார்கள்:\n\r\n\n\r\n«أَقُولُ قَوْلِي هذَا وَأَسْتَغْفِرُ اللهَ لِي وَلَكُم»\n\r\n\n\r\n(நான் இதைக் கூறிவிட்டு, எனக்காகவும் உங்களுக்காகவும் அல்லாஹ்விடம் மன்னிப்புக் கோருகிறேன்.)\" இதனை அப்த் பின் ஹுமைத் பதிவு செய்துள்ளார்கள்.\n\r\n\n\r\nமேலும் இமாம் அஹ்மத் (ரஹ்) அவர்கள் பதிவு செய்துள்ளார்கள்: அபூ நழ்ரா (ரஹ்) அவர்கள், அய்யாமுத் தஷ்ரீக் (ஹஜ்ஜின் போது மினாவில் தங்கும்) நாட்களின் நடுப்பகுதியில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஆற்றிய உரையைக் கேட்ட ஒருவரிடமிருந்து அறிவிக்கிறார்கள்: (அதில் நபி (ஸல்) அவர்கள் கூறினார்கள்:)\n\r\n\n\r\n«يَا أَيُّهَا النَّاسُ، أَلَا إِنَّ رَبَّكُمْ وَاحِدٌ، وَإِنَّ أَبَاكُمْ وَاحِدٌ، لَا فَضْلَ لِعَرَبِيٍّ عَلَى أَعْجَمِيٍّ، وَلَا لِعَجَمِيٍّ عَلَى عَرَبِيٍّ، وَلَا لِأَحْمَرَ عَلَى أَسْوَدَ، وَلَا لِأَسْوَدَ عَلَى أَحْمَرَ، إِلَّا بِالتَّقْوَى، أَبَلَّغْتُ؟»\n\r\n\n\r\n(\"மக்களே! அறிந்துகொள்ளுங்கள்! நிச்சயமாக உங்கள் இறைவன் ஒருவனே; உங்கள் தந்தை ஒருவரே. ஓர் அரபியருக்கு அரபியல்லாதவரை விடவோ, அரபியல்லாதவருக்கு அரபியரை விடவோ, சிவப்பு நிறத்தவருக்குக் கருப்பரை விடவோ, கருப்பருக்குச் சிவப்பு நிறத்தவரை விடவோ தக்வாவைத் தவிர வேறு எவ்விதச் சிறப்பும் இல்லை. நான் (இச்செய்தியை) சேர்த்துவிட்டேனா?\") என்று கேட்டார்கள். அதற்கு மக்கள், \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் சேர்த்துவிட்டார்கள்\" என்று பதிலளித்தார்கள். பிறகு, \"இங்கு வந்திருப்பவர் வராதவருக்கு இதனை எடுத்துரைக்கட்டும்\" என்று கூறினார்கள்.\n\r\n\n\r\nமேலான அல்லாஹ் கூறினான்:\n\r\n\n\r\nإِنَّ اللَّهَ عَلِيمٌ خَبِيرٌ\n\r\n\n\r\n(நிச்சயமாக அல்லாஹ் எல்லாம் அறிந்தவன், நன்கறிந்தவன்). இதன் பொருள், அவன் உங்களைப் பற்றியும், உங்கள் அனைத்து விவகாரங்கள் குறித்தும் நன்கறிந்தவன் என்பதாகும். அல்லாஹ் தான் நாடியவர்களுக்கு நேர்வழி காட்டுகிறான், தான் நாடியவர்களை வழிகேட்டில் விடுகிறான், தான் நாடியவர்கள் மீது கருணை காட்டுகிறான், தான் நாடியவர்களைத் தண்டிக்கிறான், தான் நாடியவர்களை மற்றவர்களை விட உயர்த்துகிறான். இவை அனைத்திலும் அவன் மிக்க ஞானமுடையவனாகவும், எல்லாம் அறிந்தவனாகவும், நன்கறிந்தவனாகவும் இருக்கிறான். திருமண ஒப்பந்தத்தின்போது (இரு குடும்பத்தாருக்கும் இடையிலான) அந்தஸ்து சமமாக இருக்க வேண்டும் என்பது ஒரு கட்டாய நிபந்தனையல்ல என்பதற்கு இந்த கண்ணியமிக்க வசனத்தையும் நாம் குறிப்பிட்ட ஹதீஸ்களையும் பல அறிஞர்கள் ஆதாரமாகக் கொள்கின்றனர். இவ்விஷயத்தில் தேவைப்படும் ஒரே தகுதி மார்க்கப்பற்று மட்டுமே என்று அவர்கள் கூறுகின்றனர். மேலான அல்லாஹ் கூறியிருப்பதைப் போல:\n\r\n\n\r\nإِنَّ أَكْرَمَكُمْ عَندَ اللَّهِ أَتْقَـكُمْ\n\r\n\n\r\n(நிச்சயமாக, அல்லாஹ்விடம் உங்களில் மிகக் கண்ணியமானவர் உங்களில் அதிக தக்வா உடையவரே.)"},"14":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=49&ayah=18\" class=\"link\">49:18</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 49:18 ஐ பார்க்கவும்"},"15":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=49&ayah=18\" class=\"link\">49:18</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 49:18 ஐ பார்க்கவும்"},"16":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=49&ayah=18\" class=\"link\">49:18</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 49:18 ஐ பார்க்கவும்"},"17":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=49&ayah=18\" class=\"link\">49:18</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 49:18 ஐ பார்க்கவும்"},"18":{"html":"<strong>முஃமினுக்கும் முஸ்லிமுக்கும் இடையில் வேறுபாடு உள்ளது</strong><br />\r\n<br />\r\nமுஃமினுக்கும் முஸ்லிமுக்கும் இடையில் வேறுபாடு உள்ளது<br />\r\n<br />\r\nஇஸ்லாத்தை ஏற்றுக் கொண்டபோது, தங்களை உண்மையான இறைநம்பிக்கையாளர்கள் (முஃமின்கள்) என்று உரிமை கோரிய கிராமப்புற அரபுகளை (பதுவீன்களை) அல்லாஹ் கண்டிக்கிறான். இருப்பினும், ஈமான் (இறைநம்பிக்கை) இன்னும் அவர்களின் உள்ளங்களில் உறுதியாக வேரூன்றவில்லை.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَالَتِ</span> <span class=\"quran-arabic-font text-success\">الْأَعْرَابُ</span> <span class=\"quran-arabic-font text-success\">ءَامَنَّا</span> <span class=\"quran-arabic-font text-success\">قُل</span> <span class=\"quran-arabic-font text-success\">لَّمْ</span> <span class=\"quran-arabic-font text-success\">تُؤْمِنُواْ</span> <span class=\"quran-arabic-font text-success\">وَلَـكِن</span> <span class=\"quran-arabic-font text-success\">قُولُواْ</span> <span class=\"quran-arabic-font text-success\">أَسْلَمْنَا</span> <span class=\"quran-arabic-font text-success\">وَلَمَّا</span> <span class=\"quran-arabic-font text-success\">يَدْخُلِ</span> <span class=\"quran-arabic-font text-success\">الايمَـنُ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">قُلُوبِكُمْ</span><br />\r\n<br />\r\n(அந்தக் கிராமவாசிகள், \"நாங்கள் ஈமான் கொண்டோம்\" எனக் கூறுகின்றனர். (நபியே!) நீர் கூறுவீராக: \"நீங்கள் ஈமான் கொள்ளவில்லை. மாறாக, 'நாங்கள் கீழ்ப்படிந்தோம் (இஸ்லாத்தை ஏற்றோம்)' என்றே சொல்லுங்கள். ஏனெனில் ஈமான் இன்னும் உங்கள் உள்ளங்களில் நுழையவில்லை...\") அஹ்லுஸ் ஸுன்னா வல்-ஜமாஆ அறிஞர்களின் கருத்துப்படி, இஸ்லாத்தை விட ஈமான் என்பது ஒரு மேலான நிலை என்பதற்கு இந்த கண்ணியமிக்க வசனம் சான்றாக அமைகிறது. ஜிப்ரீல் (அலை) அவர்கள் நபி (ஸல்) அவர்களிடம் இஸ்லாம், ஈமான் மற்றும் இஹ்ஸான் பற்றி வினவிய ஹதீஸிலும் இது தெளிவாகிறது. இதன் மூலம் ஒரு பொதுவான நிலையிலிருந்து குறிப்பிட்ட நிலைக்கும், அதிலிருந்து இன்னும் மேலான ஒரு நிலைக்கும் படிப்படியாக உயர்வு ஏற்படுகிறது. இமாம் அஹ்மத் அவர்கள் ஆமிர் பின் ஸஅத் பின் அபீ வக்காஸ் (ரழி) அவர்கள் வழியாகப் பதிவு செய்துள்ளார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் சில மனிதர்களுக்கு (தர்மப் பொருட்களை) வழங்கினார்கள்; ஆனால் அவர்களில் ஒருவருக்கு மட்டும் எதையும் வழங்கவில்லை. அப்போது ஸஅத் (ரழி) அவர்கள், 'அல்லாஹ்வின் தூதரே! நீங்கள் இன்னாருக்கும் இன்னாருக்கும் வழங்கினீர்கள். ஆனால் இன்னாருக்கு மட்டும் எதையும் வழங்கவில்லையே? அவர் ஒரு முஃமின் (இறைநம்பிக்கையாளர்) தானே!' என்று கேட்டார்கள். அதற்கு நபி (ஸல்) அவர்கள்,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">مُسْلِمٌ؟</span>»<br />\r\n<br />\r\n(அல்லது ஒரு முஸ்லிம் என்று சொல்) என்று கூறினார்கள். ஸஅத் (ரழி) அவர்கள் மூன்று முறை அவ்வாறே கேட்டார்கள். ஒவ்வொரு முறையும் நபி (ஸல்) அவர்கள்,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">مُسْلِمٌ؟</span>»<br />\r\n<br />\r\n(அல்லது ஒரு முஸ்லிம் என்று சொல்) என்றே பதிலளித்தார்கள். பின்னர் நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنِّي</span> <span class=\"quran-arabic-font text-success\">لَأُعْطِي</span> <span class=\"quran-arabic-font text-success\">رِجَالًا</span> <span class=\"quran-arabic-font text-success\">وَأَدَعُ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">أَحَبَّ</span> <span class=\"quran-arabic-font text-success\">إِلَيَّ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ،فَلَمْ</span> <span class=\"quran-arabic-font text-success\">أُعْطِهِ</span> <span class=\"quran-arabic-font text-success\">شَيْئًا</span> <span class=\"quran-arabic-font text-success\">مَخَافَةَ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يُكَبُّوا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">وُجُوهِهِم</span>»<br />\r\n<br />\r\n(சிலர் எனக்கு மிகவும் விருப்பமானவர்களாக இருந்தும், அவர்கள் நரக நெருப்பில் முகங்குப்புற வீழ்த்தப்படுவார்களோ என்ற அச்சத்தின் காரணமாக அவர்களுக்கு எதையும் கொடுக்காமல் விடுத்து, மற்றவர்களுக்கு நான் கொடுக்கிறேன்.)\" இந்த ஹதீஸ் புகாரி மற்றும் முஸ்லிம் ஆகிய இரு ஸஹீஹ்களிலும் இடம்பெற்றுள்ளது. எனவே, நபி (ஸல்) அவர்கள் முஃமின் மற்றும் முஸ்லிம் ஆகிய நிலைகளுக்கு இடையே வேறுபாடு காட்டினார்கள். இது இஸ்லாத்தை விட ஈமான் என்பது ஒரு பிரத்யேகமான உயர்ந்த நிலை என்பதைக் காட்டுகிறது. ஸஹீஹ் அல்-புகாரியின் ஈமான் பற்றிய அத்தியாயத்தின் விளக்கவுரையின் ஆரம்பத்தில், இது குறித்து விரிவாகவும் ஆதாரங்களுடன் நான் குறிப்பிட்டுள்ளேன். எல்லாப் புகழும் அல்லாஹ்வுக்கே, எல்லா அருள்களும் அவனிடமிருந்தே உண்டாகின்றன.<br />\r\n<br />\r\nஆகவே, இந்த வசனத்தில் குறிப்பிடப்பட்டுள்ள கிராமவாசிகள் நயவஞ்சகர்கள் (முனாஃபிக்குகள்) அல்ல என்பதையும், மாறாக அவர்கள் இன்னும் ஈமான் உறுதியாக நிலைபெறாத முஸ்லிம்கள் என்பதையும் இது நிரூபிக்கிறது. அவர்கள் தங்களுக்குக் கிடைத்த நிலையை விட மேலான நிலையைத் தங்களுக்குரியதாக உரிமை கோரியதால், அவர்களுக்குப் பாடம் புகட்டப்பட்டது. இந்த விளக்கமானது இப்னு அப்பாஸ் (ரழி), இப்ராஹீம் அந்-நகஈ, கதாதா ஆகியோரின் கருத்துடனும் இப்னு ஜரீர் அவர்களின் தெரிவுடனும் ஒத்துப்போகிறது. இந்தக் கிராமவாசிகளுக்குப் பாடம் புகட்டப்பட்டது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُل</span> <span class=\"quran-arabic-font text-success\">لَّمْ</span> <span class=\"quran-arabic-font text-success\">تُؤْمِنُواْ</span> <span class=\"quran-arabic-font text-success\">وَلَـكِن</span> <span class=\"quran-arabic-font text-success\">قُولُواْ</span> <span class=\"quran-arabic-font text-success\">أَسْلَمْنَا</span> <span class=\"quran-arabic-font text-success\">وَلَمَّا</span> <span class=\"quran-arabic-font text-success\">يَدْخُلِ</span> <span class=\"quran-arabic-font text-success\">الايمَـنُ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">قُلُوبِكُمْ</span><br />\r\n<br />\r\n(நீர் கூறுவீராக: \"நீங்கள் ஈமான் கொள்ளவில்லை. ஆனால் 'நாங்கள் முஸ்லிம்கள்' என்று சொல்லுங்கள். ஏனெனில் ஈமான் இன்னும் உங்கள் உள்ளங்களில் நுழையவில்லை...\") அதாவது, 'நீங்கள் இன்னும் ஈமானின் எதார்த்தத்தை அடையவில்லை.' கண்ணியமிக்க அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِن</span> <span class=\"quran-arabic-font text-success\">تُطِيعُواْ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">وَرَسُولَهُ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَلِتْكُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">أَعْمَـلِكُمْ</span> <span class=\"quran-arabic-font text-success\">شَيْئاً</span><br />\r\n<br />\r\n(ஆனால் நீங்கள் அல்லாஹ்வுக்கும் அவனுடைய தூதருக்கும் கீழ்ப்படிந்து நடந்தால், அவன் உங்கள் நற்செயல்களின் கூலியில் எதையும் குறைக்க மாட்டான்...) அதாவது அல்லாஹ் கூறுகிறான்: \"அவன் உங்கள் நற்கூலிகளில் எதையும் குறைக்க மாட்டான்.\" அல்லாஹ் மேலும் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَلَتْنَـهُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">عَمَلِهِم</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span><br />\r\n<br />\r\n(அவர்களுடைய செயல்களின் நற்கூலியில் எதையும் நாம் அவர்களுக்குக் குறைக்க மாட்டோம்.) (<a href=\"qurandisp.php?sura=52&ayah=21\" class=\"link\">52:21</a>) அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">غَفُورٌ</span> <span class=\"quran-arabic-font text-success\">رَّحِيمٌ</span><br />\r\n<br />\r\n(நிச்சயமாக அல்லாஹ் மிக மன்னிப்பவன், நிகரற்ற அன்புடையவன்.) அவனிடம் மன்னிப்புக் கேட்டு மீளுபவர்களுக்கு அவன் மன்னிப்பு அளிக்கிறான். அல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّمَا</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنُونَ</span><br />\r\n<br />\r\n(உண்மையான முஃமின்கள் யாரெனில்), பூரண ஈமான் கொண்டவர்கள்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">بِاللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَرَسُولِهِ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يَرْتَابُواْ</span><br />\r\n<br />\r\n(அல்லாஹ்வையும் அவனுடைய தூதரையும் ஈமான் கொண்டு, பின்னர் எத்தகைய சந்தேகமும் கொள்ளாதவர்கள்.) அவர்களுக்கு எந்தச் சந்தேகமும் இல்லை, அவர்களின் ஈமான் அசைக்கப்படவில்லை. மாறாக, அவர்களின் ஈமான் உறுதியான நம்பிக்கையில் நிலைத்திருந்தது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَجَـهَدُواْ</span> <span class=\"quran-arabic-font text-success\">بِأَمْوَلِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَأَنفُسِهِمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">سَبِيلِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span><br />\r\n<br />\r\n(தங்களின் செல்வங்களையும் உயிர்களையும் கொண்டு அல்லாஹ்வின் பாதையில் ஜிஹாது - அறப்போர் செய்தவர்கள்.) அதாவது, அவர்கள் அல்லாஹ்வின் திருப்பொருத்தத்தை நாடி, அவனுக்குக் கீழ்ப்படிந்து தங்களின் உயிரையும் தங்களின் மிகவும் விருப்பமான செல்வத்தையும் மனமுவந்து தியாகம் செய்தார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الصَّـدِقُونَ</span><br />\r\n<br />\r\n(அவர்களே உண்மையானவர்கள்.) 'தங்கள் நாவினால் மட்டும் வெளிப்படையாக ஈமான் கொண்டதாகக் கூறிக்கொள்ளும் சில கிராமவாசிகளைப் போல் அல்லாமல், இவர்கள் தாங்கள் ஈமான் கொண்டவர்கள் என்று கூறினால் அக்கூற்றில் உண்மையானவர்களாக இருப்பார்கள்!' அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">أَتُعَلِّمُونَ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">بِدِينِكُمْ</span><br />\r\n<br />\r\n(கூறுவீராக: \"உங்களுடைய மார்க்கத்தைப் பற்றி அல்லாஹ்வுக்கா நீங்கள் கற்றுக் கொடுக்கிறீர்கள்?\") 'உங்கள் உள்ளங்களில் இருப்பவை குறித்து அல்லாஹ்வுக்கா நீங்கள் அறிவிக்கிறீர்கள்?'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">السَّمَـوَتِ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span><br />\r\n<br />\r\n(வானங்களில் உள்ளவற்றையும் பூமியில் உள்ளவற்றையும் அல்லாஹ் நன்கறிவான்.) வானங்களிலும் பூமியிலும் ஒரு அணுவளவோ அல்லது அதைவிடப் பெரியதோ சிறியதோ எதுவும் அவனது அறிவிலிருந்து தப்புவதில்லை.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">بِكُلِّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">عَلِيمٌ</span><br />\r\n<br />\r\n(அல்லாஹ் ஒவ்வொன்றையும் அறிந்தவன்.) அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَمُنُّونَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكَ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">أَسْلَمُواْ</span> <span class=\"quran-arabic-font text-success\">قُل</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">تَمُنُّواْ</span> <span class=\"quran-arabic-font text-success\">عَلَىَّ</span> <span class=\"quran-arabic-font text-success\">إِسْلَـمَكُمْ</span><br />\r\n<br />\r\n(தாங்கள் இஸ்லாத்தை ஏற்றதை உமக்குச் செய்த உபகாரமாகக் கருதுகின்றனர். \"உங்களுடைய இஸ்லாத்தை எனக்குச் செய்த உபகாரமாகக் கருதாதீர்கள்\" என்று கூறுவீராக...) அதாவது இஸ்லாத்தை ஏற்றதையும், ரஸூல் (ஸல்) அவர்களைப் பின்பற்றி அவருக்கு உதவியதையும் அவருக்குச் செய்த உபகாரமாக அந்தப் பதுவீன்கள் கருதினார்கள். அவர்களின் இந்தப் பொய்யான கூற்றை அல்லாஹ் மறுத்தான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُل</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">تَمُنُّواْ</span> <span class=\"quran-arabic-font text-success\">عَلَىَّ</span> <span class=\"quran-arabic-font text-success\">إِسْلَـمَكُمْ</span><br />\r\n<br />\r\n(கூறுவீராக: \"உங்கள் இஸ்லாத்தை எனக்குச் செய்த உபகாரமாகக் கருதாதீர்கள்...\") 'ஏனெனில் உங்கள் இஸ்லாத்தின் நன்மை உங்களுக்கே உரியது. இது அல்லாஹ் உங்களுக்குச் செய்த பேரருளாகும்.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بَلِ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">يَمُنُّ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">هَداكُمْ</span> <span class=\"quran-arabic-font text-success\">لِلايمَـنِ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">صَـدِقِينَ</span><br />\r\n<br />\r\n(அப்படியல்ல! நீங்கள் (ஈமானில்) உண்மையானவர்களாக இருந்தால், ஈமானின் பால் உங்களுக்கு நேர்வழி காட்டியதற்காக அல்லாஹ்வே உங்கள் மீது பேரருள் புரிந்துள்ளான்.) 'நீங்கள் முஃமின்கள் என்ற உங்கள் கூற்றில் நீங்கள் உண்மையாளர்களாக இருந்தால் (இது பொருந்தும்).' ஹுனைன் போரின் போது நபி (ஸல்) அவர்கள் அன்ஸாரிகளிடம் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">مَعْشَرَ</span> <span class=\"quran-arabic-font text-success\">الْأَنْصَارِ</span> <span class=\"quran-arabic-font text-success\">أَلَمْ</span> <span class=\"quran-arabic-font text-success\">أَجِدْكُمْ</span> <span class=\"quran-arabic-font text-success\">ضُلَّالًا</span> <span class=\"quran-arabic-font text-success\">فَهَدَاكُمُ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">بِي؟</span> <span class=\"quran-arabic-font text-success\">وَكُنْتُمْ</span> <span class=\"quran-arabic-font text-success\">مُتَفَرِّقِينَ</span> <span class=\"quran-arabic-font text-success\">فَأَلَّفَكُمُ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">بِي؟</span> <span class=\"quran-arabic-font text-success\">وَكُنْتُمْ</span> <span class=\"quran-arabic-font text-success\">عَالَةً</span> <span class=\"quran-arabic-font text-success\">فَأَغْنَاكُمُ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">بِي؟</span>»<br />\r\n<br />\r\n(அன்ஸார் கூட்டத்தினரே! நீங்கள் வழிதவறி இருந்த போது உங்களைக் கண்டு, என் மூலமாக அல்லாஹ் உங்களுக்கு நேர்வழி காட்டவில்லையா? நீங்கள் சிதறிப்போயிருந்த போது என் மூலமாக அல்லாஹ் உங்களை ஒன்று சேர்க்கவில்லையா? நீங்கள் ஏழ்மையில் இருந்த போது என் மூலமாக அல்லாஹ் உங்களைச் செல்வந்தர்களாக்கவில்லையா?) நபி (ஸல்) அவர்கள் எதை வினவினாலும், அதற்கு அவர்கள், \"அல்லாஹ்வும் அவனது தூதருமே எங்களுக்குப் பெரும் உபகாரம் செய்தவர்கள்\" என்று பதிலளிப்பார்கள். அல்-ஹாஃபிழ் அபூ பக்ர் அல்-பஸ்ஸார் அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்கள் வழியாகப் பதிவு செய்துள்ளார்கள்: \"பனூ அஸத் கோத்திரத்தினர் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் வந்து, 'அல்லாஹ்வின் தூதரே! நாங்கள் இஸ்லாத்தை ஏற்றுக் கொண்டோம். அரபுகள் உங்களுக்கு எதிராகப் போர் செய்தபோது நாங்கள் உங்களுக்கு எதிராகப் போர் செய்யவில்லை' என்று கூறினார்கள்.\" அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">فِقْهَهُمْ</span> <span class=\"quran-arabic-font text-success\">قَلِيلٌ</span> <span class=\"quran-arabic-font text-success\">وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">الشَّيْطَانَ</span> <span class=\"quran-arabic-font text-success\">يَنْطِقُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَلْسِنَتِهِم</span>»<br />\r\n<br />\r\n(நிச்சயமாக இவர்களின் புரிதல் மிகக் குறைவு; ஷைத்தான் இவர்களின் நாவுகள் வழியாகப் பேசுகிறான்.) பின்னர் இந்த வசனம் அருளப்பட்டது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَمُنُّونَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكَ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">أَسْلَمُواْ</span> <span class=\"quran-arabic-font text-success\">قُل</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">تَمُنُّواْ</span> <span class=\"quran-arabic-font text-success\">عَلَىَّ</span> <span class=\"quran-arabic-font text-success\">إِسْلَـمَكُمْ</span> <span class=\"quran-arabic-font text-success\">بَلِ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">يَمُنُّ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">هَداكُمْ</span> <span class=\"quran-arabic-font text-success\">لِلايمَـنِ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">صَـدِقِينَ</span><br />\r\n<br />\r\n(தாங்கள் இஸ்லாத்தை ஏற்றதை உமக்குச் செய்த உபகாரமாகக் கருதுகின்றனர். கூறுவீராக: \"உங்களுடைய இஸ்லாத்தை எனக்குச் செய்த உபகாரமாகக் கருதாதீர்கள். மாறாக, நீங்கள் உண்மையாளர்களாக இருந்தால், ஈமானின் பால் உங்களுக்கு நேர்வழி காட்டியதற்காக அல்லாஹ்வே உங்கள் மீது பேரருள் புரிந்துள்ளான்.\")<br />\r\n<br />\r\nபின்னர் அல்லாஹ், அவனுக்கு எல்லாப் படைப்புகளைப் பற்றியும் முழுமையான அறிவு உண்டு என்றும், அவன் அனைத்தையும் பார்ப்பவன் என்றும் நினைவூட்டுகிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">غَيْبَ</span> <span class=\"quran-arabic-font text-success\">السَّمَـوَتِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">بَصِيرٌ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">تَعْمَلُونَ</span><br />\r\n<br />\r\n(நிச்சயமாக அல்லாஹ் வானங்கள் மற்றும் பூமியின் மறைவானவற்றை நன்கறிகிறான். மேலும் நீங்கள் செய்பவற்றை அல்லாஹ் உற்று நோக்குபவன்.) இத்துடன் ஸூரத்துல் ஹுஜுராத்தின் தஃப்சீர் நிறைவுற்றது. எல்லாப் புகழும் அல்லாஹ்வுக்கே உரியது. எல்லா அருள்களும் அவனிடமிருந்தே உண்டாகின்றன. வெற்றியும் தவறுகளிலிருந்து பாதுகாப்பும் அவனிடமிருந்தே கிடைக்கின்றன.<br />\r\n<br />\r\n<br />\r\n<br />","text":"முஃமினுக்கும் முஸ்லிமுக்கும் இடையில் வேறுபாடு உள்ளது\n\r\n\n\r\nமுஃமினுக்கும் முஸ்லிமுக்கும் இடையில் வேறுபாடு உள்ளது\n\r\n\n\r\nஇஸ்லாத்தை ஏற்றுக் கொண்டபோது, தங்களை உண்மையான இறைநம்பிக்கையாளர்கள் (முஃமின்கள்) என்று உரிமை கோரிய கிராமப்புற அரபுகளை (பதுவீன்களை) அல்லாஹ் கண்டிக்கிறான். இருப்பினும், ஈமான் (இறைநம்பிக்கை) இன்னும் அவர்களின் உள்ளங்களில் உறுதியாக வேரூன்றவில்லை.\n\r\n\n\r\nقَالَتِ الْأَعْرَابُ ءَامَنَّا قُل لَّمْ تُؤْمِنُواْ وَلَـكِن قُولُواْ أَسْلَمْنَا وَلَمَّا يَدْخُلِ الايمَـنُ فِى قُلُوبِكُمْ\n\r\n\n\r\n(அந்தக் கிராமவாசிகள், \"நாங்கள் ஈமான் கொண்டோம்\" எனக் கூறுகின்றனர். (நபியே!) நீர் கூறுவீராக: \"நீங்கள் ஈமான் கொள்ளவில்லை. மாறாக, 'நாங்கள் கீழ்ப்படிந்தோம் (இஸ்லாத்தை ஏற்றோம்)' என்றே சொல்லுங்கள். ஏனெனில் ஈமான் இன்னும் உங்கள் உள்ளங்களில் நுழையவில்லை...\") அஹ்லுஸ் ஸுன்னா வல்-ஜமாஆ அறிஞர்களின் கருத்துப்படி, இஸ்லாத்தை விட ஈமான் என்பது ஒரு மேலான நிலை என்பதற்கு இந்த கண்ணியமிக்க வசனம் சான்றாக அமைகிறது. ஜிப்ரீல் (அலை) அவர்கள் நபி (ஸல்) அவர்களிடம் இஸ்லாம், ஈமான் மற்றும் இஹ்ஸான் பற்றி வினவிய ஹதீஸிலும் இது தெளிவாகிறது. இதன் மூலம் ஒரு பொதுவான நிலையிலிருந்து குறிப்பிட்ட நிலைக்கும், அதிலிருந்து இன்னும் மேலான ஒரு நிலைக்கும் படிப்படியாக உயர்வு ஏற்படுகிறது. இமாம் அஹ்மத் அவர்கள் ஆமிர் பின் ஸஅத் பின் அபீ வக்காஸ் (ரழி) அவர்கள் வழியாகப் பதிவு செய்துள்ளார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் சில மனிதர்களுக்கு (தர்மப் பொருட்களை) வழங்கினார்கள்; ஆனால் அவர்களில் ஒருவருக்கு மட்டும் எதையும் வழங்கவில்லை. அப்போது ஸஅத் (ரழி) அவர்கள், 'அல்லாஹ்வின் தூதரே! நீங்கள் இன்னாருக்கும் இன்னாருக்கும் வழங்கினீர்கள். ஆனால் இன்னாருக்கு மட்டும் எதையும் வழங்கவில்லையே? அவர் ஒரு முஃமின் (இறைநம்பிக்கையாளர்) தானே!' என்று கேட்டார்கள். அதற்கு நபி (ஸல்) அவர்கள்,\n\r\n\n\r\n«أَوْ مُسْلِمٌ؟»\n\r\n\n\r\n(அல்லது ஒரு முஸ்லிம் என்று சொல்) என்று கூறினார்கள். ஸஅத் (ரழி) அவர்கள் மூன்று முறை அவ்வாறே கேட்டார்கள். ஒவ்வொரு முறையும் நபி (ஸல்) அவர்கள்,\n\r\n\n\r\n«أَوْ مُسْلِمٌ؟»\n\r\n\n\r\n(அல்லது ஒரு முஸ்லிம் என்று சொல்) என்றே பதிலளித்தார்கள். பின்னர் நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِنِّي لَأُعْطِي رِجَالًا وَأَدَعُ مَنْ هُوَ أَحَبَّ إِلَيَّ مِنْهُمْ،فَلَمْ أُعْطِهِ شَيْئًا مَخَافَةَ أَنْ يُكَبُّوا فِي النَّارِ عَلَى وُجُوهِهِم»\n\r\n\n\r\n(சிலர் எனக்கு மிகவும் விருப்பமானவர்களாக இருந்தும், அவர்கள் நரக நெருப்பில் முகங்குப்புற வீழ்த்தப்படுவார்களோ என்ற அச்சத்தின் காரணமாக அவர்களுக்கு எதையும் கொடுக்காமல் விடுத்து, மற்றவர்களுக்கு நான் கொடுக்கிறேன்.)\" இந்த ஹதீஸ் புகாரி மற்றும் முஸ்லிம் ஆகிய இரு ஸஹீஹ்களிலும் இடம்பெற்றுள்ளது. எனவே, நபி (ஸல்) அவர்கள் முஃமின் மற்றும் முஸ்லிம் ஆகிய நிலைகளுக்கு இடையே வேறுபாடு காட்டினார்கள். இது இஸ்லாத்தை விட ஈமான் என்பது ஒரு பிரத்யேகமான உயர்ந்த நிலை என்பதைக் காட்டுகிறது. ஸஹீஹ் அல்-புகாரியின் ஈமான் பற்றிய அத்தியாயத்தின் விளக்கவுரையின் ஆரம்பத்தில், இது குறித்து விரிவாகவும் ஆதாரங்களுடன் நான் குறிப்பிட்டுள்ளேன். எல்லாப் புகழும் அல்லாஹ்வுக்கே, எல்லா அருள்களும் அவனிடமிருந்தே உண்டாகின்றன.\n\r\n\n\r\nஆகவே, இந்த வசனத்தில் குறிப்பிடப்பட்டுள்ள கிராமவாசிகள் நயவஞ்சகர்கள் (முனாஃபிக்குகள்) அல்ல என்பதையும், மாறாக அவர்கள் இன்னும் ஈமான் உறுதியாக நிலைபெறாத முஸ்லிம்கள் என்பதையும் இது நிரூபிக்கிறது. அவர்கள் தங்களுக்குக் கிடைத்த நிலையை விட மேலான நிலையைத் தங்களுக்குரியதாக உரிமை கோரியதால், அவர்களுக்குப் பாடம் புகட்டப்பட்டது. இந்த விளக்கமானது இப்னு அப்பாஸ் (ரழி), இப்ராஹீம் அந்-நகஈ, கதாதா ஆகியோரின் கருத்துடனும் இப்னு ஜரீர் அவர்களின் தெரிவுடனும் ஒத்துப்போகிறது. இந்தக் கிராமவாசிகளுக்குப் பாடம் புகட்டப்பட்டது:\n\r\n\n\r\nقُل لَّمْ تُؤْمِنُواْ وَلَـكِن قُولُواْ أَسْلَمْنَا وَلَمَّا يَدْخُلِ الايمَـنُ فِى قُلُوبِكُمْ\n\r\n\n\r\n(நீர் கூறுவீராக: \"நீங்கள் ஈமான் கொள்ளவில்லை. ஆனால் 'நாங்கள் முஸ்லிம்கள்' என்று சொல்லுங்கள். ஏனெனில் ஈமான் இன்னும் உங்கள் உள்ளங்களில் நுழையவில்லை...\") அதாவது, 'நீங்கள் இன்னும் ஈமானின் எதார்த்தத்தை அடையவில்லை.' கண்ணியமிக்க அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَإِن تُطِيعُواْ اللَّهَ وَرَسُولَهُ لاَ يَلِتْكُمْ مِّنْ أَعْمَـلِكُمْ شَيْئاً\n\r\n\n\r\n(ஆனால் நீங்கள் அல்லாஹ்வுக்கும் அவனுடைய தூதருக்கும் கீழ்ப்படிந்து நடந்தால், அவன் உங்கள் நற்செயல்களின் கூலியில் எதையும் குறைக்க மாட்டான்...) அதாவது அல்லாஹ் கூறுகிறான்: \"அவன் உங்கள் நற்கூலிகளில் எதையும் குறைக்க மாட்டான்.\" அல்லாஹ் மேலும் கூறினான்:\n\r\n\n\r\nوَمَآ أَلَتْنَـهُمْ مِّنْ عَمَلِهِم مِّن شَىْءٍ\n\r\n\n\r\n(அவர்களுடைய செயல்களின் நற்கூலியில் எதையும் நாம் அவர்களுக்குக் குறைக்க மாட்டோம்.) (52:21) அல்லாஹ் கூறினான்:\n\r\n\n\r\nإِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ\n\r\n\n\r\n(நிச்சயமாக அல்லாஹ் மிக மன்னிப்பவன், நிகரற்ற அன்புடையவன்.) அவனிடம் மன்னிப்புக் கேட்டு மீளுபவர்களுக்கு அவன் மன்னிப்பு அளிக்கிறான். அல்லாஹ்வின் கூற்று:\n\r\n\n\r\nإِنَّمَا الْمُؤْمِنُونَ\n\r\n\n\r\n(உண்மையான முஃமின்கள் யாரெனில்), பூரண ஈமான் கொண்டவர்கள்,\n\r\n\n\r\nالَّذِينَ ءَامَنُواْ بِاللَّهِ وَرَسُولِهِ ثُمَّ لَمْ يَرْتَابُواْ\n\r\n\n\r\n(அல்லாஹ்வையும் அவனுடைய தூதரையும் ஈமான் கொண்டு, பின்னர் எத்தகைய சந்தேகமும் கொள்ளாதவர்கள்.) அவர்களுக்கு எந்தச் சந்தேகமும் இல்லை, அவர்களின் ஈமான் அசைக்கப்படவில்லை. மாறாக, அவர்களின் ஈமான் உறுதியான நம்பிக்கையில் நிலைத்திருந்தது.\n\r\n\n\r\nوَجَـهَدُواْ بِأَمْوَلِهِمْ وَأَنفُسِهِمْ فِى سَبِيلِ اللَّهِ\n\r\n\n\r\n(தங்களின் செல்வங்களையும் உயிர்களையும் கொண்டு அல்லாஹ்வின் பாதையில் ஜிஹாது - அறப்போர் செய்தவர்கள்.) அதாவது, அவர்கள் அல்லாஹ்வின் திருப்பொருத்தத்தை நாடி, அவனுக்குக் கீழ்ப்படிந்து தங்களின் உயிரையும் தங்களின் மிகவும் விருப்பமான செல்வத்தையும் மனமுவந்து தியாகம் செய்தார்கள்.\n\r\n\n\r\nأُوْلَـئِكَ هُمُ الصَّـدِقُونَ\n\r\n\n\r\n(அவர்களே உண்மையானவர்கள்.) 'தங்கள் நாவினால் மட்டும் வெளிப்படையாக ஈமான் கொண்டதாகக் கூறிக்கொள்ளும் சில கிராமவாசிகளைப் போல் அல்லாமல், இவர்கள் தாங்கள் ஈமான் கொண்டவர்கள் என்று கூறினால் அக்கூற்றில் உண்மையானவர்களாக இருப்பார்கள்!' அல்லாஹ் கூறினான்:\n\r\n\n\r\nقُلْ أَتُعَلِّمُونَ اللَّهَ بِدِينِكُمْ\n\r\n\n\r\n(கூறுவீராக: \"உங்களுடைய மார்க்கத்தைப் பற்றி அல்லாஹ்வுக்கா நீங்கள் கற்றுக் கொடுக்கிறீர்கள்?\") 'உங்கள் உள்ளங்களில் இருப்பவை குறித்து அல்லாஹ்வுக்கா நீங்கள் அறிவிக்கிறீர்கள்?'\n\r\n\n\r\nوَاللَّهُ يَعْلَمُ مَا فِى السَّمَـوَتِ وَمَا فِى الْأَرْضِ\n\r\n\n\r\n(வானங்களில் உள்ளவற்றையும் பூமியில் உள்ளவற்றையும் அல்லாஹ் நன்கறிவான்.) வானங்களிலும் பூமியிலும் ஒரு அணுவளவோ அல்லது அதைவிடப் பெரியதோ சிறியதோ எதுவும் அவனது அறிவிலிருந்து தப்புவதில்லை.\n\r\n\n\r\nوَاللَّهُ بِكُلِّ شَيْءٍ عَلِيمٌ\n\r\n\n\r\n(அல்லாஹ் ஒவ்வொன்றையும் அறிந்தவன்.) அல்லாஹ் கூறினான்:\n\r\n\n\r\nيَمُنُّونَ عَلَيْكَ أَنْ أَسْلَمُواْ قُل لاَّ تَمُنُّواْ عَلَىَّ إِسْلَـمَكُمْ\n\r\n\n\r\n(தாங்கள் இஸ்லாத்தை ஏற்றதை உமக்குச் செய்த உபகாரமாகக் கருதுகின்றனர். \"உங்களுடைய இஸ்லாத்தை எனக்குச் செய்த உபகாரமாகக் கருதாதீர்கள்\" என்று கூறுவீராக...) அதாவது இஸ்லாத்தை ஏற்றதையும், ரஸூல் (ஸல்) அவர்களைப் பின்பற்றி அவருக்கு உதவியதையும் அவருக்குச் செய்த உபகாரமாக அந்தப் பதுவீன்கள் கருதினார்கள். அவர்களின் இந்தப் பொய்யான கூற்றை அல்லாஹ் மறுத்தான்:\n\r\n\n\r\nقُل لاَّ تَمُنُّواْ عَلَىَّ إِسْلَـمَكُمْ\n\r\n\n\r\n(கூறுவீராக: \"உங்கள் இஸ்லாத்தை எனக்குச் செய்த உபகாரமாகக் கருதாதீர்கள்...\") 'ஏனெனில் உங்கள் இஸ்லாத்தின் நன்மை உங்களுக்கே உரியது. இது அல்லாஹ் உங்களுக்குச் செய்த பேரருளாகும்.'\n\r\n\n\r\nبَلِ اللَّهُ يَمُنُّ عَلَيْكُمْ أَنْ هَداكُمْ لِلايمَـنِ إِن كُنتُمْ صَـدِقِينَ\n\r\n\n\r\n(அப்படியல்ல! நீங்கள் (ஈமானில்) உண்மையானவர்களாக இருந்தால், ஈமானின் பால் உங்களுக்கு நேர்வழி காட்டியதற்காக அல்லாஹ்வே உங்கள் மீது பேரருள் புரிந்துள்ளான்.) 'நீங்கள் முஃமின்கள் என்ற உங்கள் கூற்றில் நீங்கள் உண்மையாளர்களாக இருந்தால் (இது பொருந்தும்).' ஹுனைன் போரின் போது நபி (ஸல்) அவர்கள் அன்ஸாரிகளிடம் கூறினார்கள்:\n\r\n\n\r\n«يَا مَعْشَرَ الْأَنْصَارِ أَلَمْ أَجِدْكُمْ ضُلَّالًا فَهَدَاكُمُ اللهُ بِي؟ وَكُنْتُمْ مُتَفَرِّقِينَ فَأَلَّفَكُمُ اللهُ بِي؟ وَكُنْتُمْ عَالَةً فَأَغْنَاكُمُ اللهُ بِي؟»\n\r\n\n\r\n(அன்ஸார் கூட்டத்தினரே! நீங்கள் வழிதவறி இருந்த போது உங்களைக் கண்டு, என் மூலமாக அல்லாஹ் உங்களுக்கு நேர்வழி காட்டவில்லையா? நீங்கள் சிதறிப்போயிருந்த போது என் மூலமாக அல்லாஹ் உங்களை ஒன்று சேர்க்கவில்லையா? நீங்கள் ஏழ்மையில் இருந்த போது என் மூலமாக அல்லாஹ் உங்களைச் செல்வந்தர்களாக்கவில்லையா?) நபி (ஸல்) அவர்கள் எதை வினவினாலும், அதற்கு அவர்கள், \"அல்லாஹ்வும் அவனது தூதருமே எங்களுக்குப் பெரும் உபகாரம் செய்தவர்கள்\" என்று பதிலளிப்பார்கள். அல்-ஹாஃபிழ் அபூ பக்ர் அல்-பஸ்ஸார் அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்கள் வழியாகப் பதிவு செய்துள்ளார்கள்: \"பனூ அஸத் கோத்திரத்தினர் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் வந்து, 'அல்லாஹ்வின் தூதரே! நாங்கள் இஸ்லாத்தை ஏற்றுக் கொண்டோம். அரபுகள் உங்களுக்கு எதிராகப் போர் செய்தபோது நாங்கள் உங்களுக்கு எதிராகப் போர் செய்யவில்லை' என்று கூறினார்கள்.\" அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِنَّ فِقْهَهُمْ قَلِيلٌ وَإِنَّ الشَّيْطَانَ يَنْطِقُ عَلَى أَلْسِنَتِهِم»\n\r\n\n\r\n(நிச்சயமாக இவர்களின் புரிதல் மிகக் குறைவு; ஷைத்தான் இவர்களின் நாவுகள் வழியாகப் பேசுகிறான்.) பின்னர் இந்த வசனம் அருளப்பட்டது:\n\r\n\n\r\nيَمُنُّونَ عَلَيْكَ أَنْ أَسْلَمُواْ قُل لاَّ تَمُنُّواْ عَلَىَّ إِسْلَـمَكُمْ بَلِ اللَّهُ يَمُنُّ عَلَيْكُمْ أَنْ هَداكُمْ لِلايمَـنِ إِن كُنتُمْ صَـدِقِينَ\n\r\n\n\r\n(தாங்கள் இஸ்லாத்தை ஏற்றதை உமக்குச் செய்த உபகாரமாகக் கருதுகின்றனர். கூறுவீராக: \"உங்களுடைய இஸ்லாத்தை எனக்குச் செய்த உபகாரமாகக் கருதாதீர்கள். மாறாக, நீங்கள் உண்மையாளர்களாக இருந்தால், ஈமானின் பால் உங்களுக்கு நேர்வழி காட்டியதற்காக அல்லாஹ்வே உங்கள் மீது பேரருள் புரிந்துள்ளான்.\")\n\r\n\n\r\nபின்னர் அல்லாஹ், அவனுக்கு எல்லாப் படைப்புகளைப் பற்றியும் முழுமையான அறிவு உண்டு என்றும், அவன் அனைத்தையும் பார்ப்பவன் என்றும் நினைவூட்டுகிறான்.\n\r\n\n\r\nإِنَّ اللَّهَ يَعْلَمُ غَيْبَ السَّمَـوَتِ وَالْأَرْضِ وَاللَّهُ بَصِيرٌ بِمَا تَعْمَلُونَ\n\r\n\n\r\n(நிச்சயமாக அல்லாஹ் வானங்கள் மற்றும் பூமியின் மறைவானவற்றை நன்கறிகிறான். மேலும் நீங்கள் செய்பவற்றை அல்லாஹ் உற்று நோக்குபவன்.) இத்துடன் ஸூரத்துல் ஹுஜுராத்தின் தஃப்சீர் நிறைவுற்றது. எல்லாப் புகழும் அல்லாஹ்வுக்கே உரியது. எல்லா அருள்களும் அவனிடமிருந்தே உண்டாகின்றன. வெற்றியும் தவறுகளிலிருந்து பாதுகாப்பும் அவனிடமிருந்தே கிடைக்கின்றன."}}};})(self);
